-- Name: dismiss_bug_update(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.dismiss_bug_update(p_report uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE bug_reports SET update_seen_at = now() WHERE id = p_report AND user_id = auth.uid();
$$;


--
-- Name: dismiss_cost_note(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.dismiss_cost_note(p_note uuid) RETURNS void
