--
-- Name: draw_game_card(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.draw_game_card(p_trip uuid, p_category text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id bigint; v_game integer; v_category text; v_week integer; BEGIN IF p_category='spicy' THEN PERFORM trip_private.require_feature(p_trip,'party_cards'); END IF;
IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF;
IF NOT (trip_private.is_leader(p_trip) OR trip_private.lab_bypass(p_trip) OR EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND host_id=auth.uid() AND NOT skipped AND starts_at BETWEEN now()-interval '4 hours' AND now()+interval '2 hours')) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can draw cards'; END IF;
IF p_category='spicy' AND NOT trip_private.is_approved_adult(p_trip,auth.uid()) THEN RAISE EXCEPTION '21+ approval required'; END IF;
IF NOT trip_private.games_live(p_trip) THEN RAISE EXCEPTION 'Games open only while your game night is live'; END IF;
IF p_category IN ('travel','food','childhood','deep','spicy') THEN
 SELECT n.game_number,f.category,n.week_number INTO v_game,v_category,v_week FROM public.game_night_flow f JOIN public.game_nights n ON n.trip_id=f.trip_id AND n.week_number=f.week_number WHERE f.trip_id=p_trip AND f.phase='cards' AND n.starts_at<=clock_timestamp()+interval '12 hours' AND n.starts_at>=clock_timestamp()-interval '12 hours' ORDER BY n.starts_at DESC LIMIT 1;
 IF v_game IS NULL OR v_category IS DISTINCT FROM p_category THEN RAISE EXCEPTION 'Draw from tonight''s category during card rounds'; END IF;
 IF NOT trip_private.night_open(p_trip, v_week) THEN RAISE EXCEPTION 'Cards draw only while the game night is live'; END IF;
 SELECT c.id INTO v_id FROM public.game_cards c
  WHERE (c.category=p_category AND c.game_number=v_game AND (c.trip_id IS NULL OR c.trip_id=p_trip))
     OR (c.game_number IS NULL AND c.trip_id IS NULL AND c.category IN (p_category, CASE WHEN p_category='spicy' THEN 'spicy' ELSE 'get-to-know' END))
  ORDER BY NOT trip_private.in_slice(p_trip, c.id::text), EXISTS(SELECT 1 FROM public.content_seen s WHERE s.trip_id=p_trip AND s.kind='card' AND s.item_key=c.id::text),
           (c.game_number IS NULL),
           EXISTS(SELECT 1 FROM public.content_seen s WHERE s.trip_id IN (SELECT trip_private.captain_trip_ids(p_trip)) AND s.kind='card' AND s.item_key=c.id::text),
           random() LIMIT 1;
ELSE
 SELECT c.id INTO v_id FROM public.game_cards c WHERE c.category=p_category AND c.game_number IS NULL AND (c.trip_id IS NULL OR c.trip_id=p_trip)
  ORDER BY NOT trip_private.in_slice(p_trip, c.id::text), EXISTS(SELECT 1 FROM public.content_seen s WHERE s.trip_id=p_trip AND s.kind='card' AND s.item_key=c.id::text),
           EXISTS(SELECT 1 FROM public.content_seen s WHERE s.trip_id IN (SELECT trip_private.captain_trip_ids(p_trip)) AND s.kind='card' AND s.item_key=c.id::text),
           random() LIMIT 1;
END IF;
IF v_id IS NULL THEN RAISE EXCEPTION 'No cards in this category'; END IF;
INSERT INTO public.content_seen(trip_id,kind,item_key) VALUES (p_trip,'card',v_id::text) ON CONFLICT DO NOTHING;
INSERT INTO public.trip_play_state(trip_id,draw_card_id,draw_category,draw_at) VALUES(p_trip,v_id,p_category,clock_timestamp()) ON CONFLICT(trip_id) DO UPDATE SET draw_card_id=EXCLUDED.draw_card_id,draw_category=EXCLUDED.draw_category,draw_at=EXCLUDED.draw_at;
RETURN v_id; END $$;


--
-- Name: edit_trip(uuid, text, text, date, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.edit_trip(p_trip uuid, p_name text, p_destination text, p_start_date date, p_end_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can edit trip details'; END IF;
 IF length(trim(coalesce(p_name,''))) NOT BETWEEN 1 AND 100 OR length(trim(coalesce(p_destination,''))) NOT BETWEEN 1 AND 120 OR p_start_date IS NULL OR p_end_date IS NULL OR p_end_date < p_start_date THEN RAISE EXCEPTION 'Check your trip details'; END IF;
 UPDATE public.trips SET name=trim(p_name),destination=trim(p_destination),start_date=p_start_date,end_date=p_end_date WHERE id=p_trip;
END $$;


--
-- Name: edit_trip_day(uuid, date, jsonb, jsonb, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.edit_trip_day(p_trip uuid, p_date date, p_bingo jsonb, p_quests jsonb, p_theme text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can edit games'; END IF;
IF jsonb_typeof(p_bingo)<>'array' OR jsonb_array_length(p_bingo) NOT IN (0,9) OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_bingo) v WHERE length(trim(v)) NOT BETWEEN 1 AND 120) THEN RAISE EXCEPTION 'Bingo needs 9 short squares'; END IF;
IF jsonb_typeof(p_quests)<>'array' OR jsonb_array_length(p_quests) NOT IN (0,3) OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_quests) v WHERE length(trim(v)) NOT BETWEEN 1 AND 160) THEN RAISE EXCEPTION 'Quests need 3 short tasks'; END IF;
IF length(coalesce(p_theme,'')) > 80 THEN RAISE EXCEPTION 'Keep the photo theme short'; END IF;
UPDATE public.trip_day_games SET bingo=p_bingo, quests=p_quests, photo_theme=coalesce(nullif(trim(p_theme),''),photo_theme) WHERE trip_id=p_trip AND day_date=p_date;
IF NOT FOUND THEN RAISE EXCEPTION 'Set up this day first'; END IF; END $$;


--
-- Name: effective_crowning(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.effective_crowning(p_trip uuid, p_season text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT CASE
   WHEN p_season='game' AND t.kind='trip' THEN ((t.start_date - 1 + time '23:59') AT TIME ZONE t.home_timezone)
   WHEN s.crowning_mode='takeoff' THEN coalesce(s.crowning_at,(SELECT n.starts_at+interval '3 hours' FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped AND (n.starts_at AT TIME ZONE t.home_timezone)::date<t.start_date ORDER BY n.starts_at DESC LIMIT 1))
   WHEN s.crowning_mode='departure' THEN (t.start_date+time '08:00') AT TIME ZONE t.home_timezone
   ELSE s.crowning_at END
 FROM public.season_settings s JOIN public.trips t ON t.id=s.trip_id WHERE s.trip_id=p_trip AND s.season=p_season $$;


--
-- Name: end_trip(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.end_trip(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE tr public.trips; today date; traveler record; BEGIN
IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain' AND status='approved') THEN RAISE EXCEPTION 'Only the Captain can end the trip'; END IF;
SELECT * INTO tr FROM public.trips WHERE id=p_trip FOR UPDATE; today := (now() AT TIME ZONE tr.home_timezone)::date;
IF tr.ended_at IS NOT NULL THEN RETURN; END IF;
IF today < tr.end_date OR today > tr.end_date + 1 THEN RAISE EXCEPTION 'You can end the trip from its last day until a day after'; END IF;
UPDATE public.trips SET ended_at = now() WHERE id=p_trip;
IF tr.is_sandbox THEN RETURN; END IF;
IF tr.kind = 'at_home' THEN
  INSERT INTO public.postcard_stickers(user_id,trip_id,pack) SELECT user_id, p_trip, tr.at_home_pack FROM public.trip_members WHERE trip_id=p_trip AND status='approved' ON CONFLICT DO NOTHING;
ELSE
  FOR traveler IN SELECT user_id FROM public.trip_members WHERE trip_id=p_trip AND status='approved' LOOP
    PERFORM trip_private.sync_passport(traveler.user_id);
  END LOOP;
  IF EXISTS (SELECT 1 FROM public.orders WHERE trip_id=p_trip AND status IN ('beta_free','paid'))
     AND (SELECT count(*) FROM public.trip_members WHERE trip_id=p_trip AND status='approved') >= 3
     AND NOT EXISTS (SELECT 1 FROM public.reward_codes WHERE user_id=auth.uid() AND used_at IS NULL AND expires_at > now()) THEN
    INSERT INTO public.reward_codes(user_id,code,cents,source_trip,expires_at) VALUES (auth.uid(), 'CAPT-' || upper(substr(md5(gen_random_uuid()::text),1,6)), 200, p_trip, now() + interval '90 days');
  END IF;
END IF;
END $$;


--
-- Name: enforce_seat_cap(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.enforce_seat_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cap int; v_used int;
BEGIN
  IF TG_OP='UPDATE' AND (OLD.status IN ('approved','pending') OR NEW.status NOT IN ('approved','pending')) THEN RETURN NEW; END IF;
  PERFORM 1 FROM public.trips WHERE id=NEW.trip_id FOR UPDATE;
  v_cap := trip_private.seat_cap(NEW.trip_id);
  IF v_cap IS NULL THEN RETURN NEW; END IF;
  SELECT count(*) INTO v_used FROM public.trip_members WHERE trip_id=NEW.trip_id AND user_id<>NEW.user_id AND status IN ('approved','pending');
  IF v_used >= v_cap THEN RAISE EXCEPTION 'This flight is full'; END IF;
  RETURN NEW;
END $$;


--
-- Name: ensure_sealed(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ensure_sealed(p_trip uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE t public.trips; d record; v_card public.security_missions; v_dest text; v_show date; c record;
BEGIN
 IF auth.uid() IS DISTINCT FROM p_user OR NOT trip_private.is_trip_member(p_trip,p_user) THEN RAISE EXCEPTION 'Only approved members can see quests'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF NOT FOUND OR t.kind NOT IN ('trip','at_home') THEN RETURN; END IF;
 IF t.id='a4842ba8-540c-4595-9417-a9a7fb53f395'::uuid AND t.season_rule='legacy' THEN RETURN; END IF;
 IF t.season_rule='a2c' AND t.kind='trip' AND t.start_date>current_date AND t.game_plan IS NULL THEN RETURN; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(p_trip::text||p_user::text||'sealed'));
 v_dest:=coalesce(nullif(btrim(regexp_replace(coalesce(t.destination,''),'\s*\((sandbox|at home)\)\s*$','','i')),''),nullif(initcap(replace(t.at_home_pack,'_',' ')),''),'your destination');
 FOR d IN SELECT * FROM trip_private.sealed_drops(p_trip) s WHERE s.drop_at<=now() LOOP
  IF EXISTS (SELECT 1 FROM public.sealed_quests q WHERE q.trip_id=p_trip AND q.user_id=p_user AND q.kind='sealed' AND q.drop_no=d.drop_no) THEN CONTINUE; END IF;
  IF t.season_rule='a2c' THEN
   SELECT * INTO c FROM trip_private.a2c_quest_card(p_trip,p_user,'sealed',d.drop_no,v_dest);
   IF NOT FOUND THEN CONTINUE; END IF;
   INSERT INTO public.sealed_quests(trip_id,user_id,kind,drop_no,drop_at,value,title,mission_text,backstory,keywords,presentation_tag,insight)
   VALUES(p_trip,p_user,'sealed',d.drop_no,d.drop_at,d.value,c.title,c.mission_text,c.backstory,c.keywords,c.presentation_tag,c.insight) ON CONFLICT DO NOTHING;
  ELSE
   SELECT * INTO v_card FROM public.security_missions sm WHERE sm.kind='checkin' AND sm.trip_id IS NULL AND sm.presentation_tag IS NULL
    AND NOT EXISTS(SELECT 1 FROM public.sealed_quests x WHERE x.trip_id=p_trip AND x.user_id=p_user AND (lower(btrim(x.title))=lower(btrim(replace(sm.title,'{destination}',v_dest))) OR lower(btrim(x.mission_text))=lower(btrim(replace(sm.text,'{destination}',v_dest)))))
    AND NOT EXISTS(SELECT 1 FROM public.season_quests x WHERE x.trip_id=p_trip AND x.user_id=p_user AND (lower(btrim(x.title))=lower(btrim(replace(sm.title,'{destination}',v_dest))) OR lower(btrim(x.mission_text))=lower(btrim(replace(sm.text,'{destination}',v_dest)))))
    ORDER BY md5(sm.id::text||p_trip::text||p_user::text||d.drop_no::text) LIMIT 1;
   IF NOT FOUND THEN EXIT; END IF;
   INSERT INTO public.sealed_quests(trip_id,user_id,kind,drop_no,drop_at,value,title,mission_text,backstory,keywords)
   VALUES(p_trip,p_user,'sealed',d.drop_no,d.drop_at,d.value,replace(coalesce(v_card.title,'Discover the destination'),'{destination}',v_dest),replace(coalesce(v_card.text,''),'{destination}',v_dest),replace(coalesce(v_card.backstory,''),'{destination}',v_dest),ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(coalesce(v_card.keywords,'{}')) k)) ON CONFLICT DO NOTHING;
  END IF;
 END LOOP;
 v_show:=CASE WHEN t.kind='trip' THEN coalesce(t.game_start,(t.created_at AT TIME ZONE t.home_timezone)::date) ELSE t.start_date END;
 IF (now() AT TIME ZONE t.home_timezone)::date>=v_show AND NOT EXISTS (SELECT 1 FROM public.sealed_quests q WHERE q.trip_id=p_trip AND q.user_id=p_user AND q.kind='showcase') THEN
  IF t.season_rule='a2c' THEN
   SELECT * INTO c FROM trip_private.a2c_quest_card(p_trip,p_user,'showcase',0,v_dest);
   IF FOUND THEN INSERT INTO public.sealed_quests(trip_id,user_id,kind,drop_no,drop_at,value,title,mission_text,backstory,keywords,presentation_tag,insight)
    VALUES(p_trip,p_user,'showcase',0,now(),20,c.title,c.mission_text,c.backstory,c.keywords,c.presentation_tag,c.insight) ON CONFLICT DO NOTHING; END IF;
  ELSE
   SELECT * INTO v_card FROM public.security_missions sm WHERE sm.kind='home' AND sm.trip_id IS NULL AND sm.presentation_tag IS NULL
    AND NOT EXISTS (SELECT 1 FROM public.sealed_quests x WHERE x.trip_id=p_trip AND x.user_id=p_user AND (lower(btrim(x.title))=lower(btrim(replace(sm.title,'{destination}',v_dest))) OR lower(btrim(x.mission_text))=lower(btrim(replace(sm.text,'{destination}',v_dest)))))
    AND NOT EXISTS (SELECT 1 FROM public.season_quests x WHERE x.trip_id=p_trip AND x.user_id=p_user AND (lower(btrim(x.title))=lower(btrim(replace(sm.title,'{destination}',v_dest))) OR lower(btrim(x.mission_text))=lower(btrim(replace(sm.text,'{destination}',v_dest)))))
    ORDER BY md5(sm.id::text||p_trip::text||p_user::text||'showcase') LIMIT 1;
   IF FOUND THEN INSERT INTO public.sealed_quests(trip_id,user_id,kind,drop_no,drop_at,value,title,mission_text,backstory,keywords)
    VALUES(p_trip,p_user,'showcase',0,now(),20,replace(coalesce(v_card.title,'Your Showcase'),'{destination}',v_dest),replace(coalesce(v_card.text,''),'{destination}',v_dest),replace(coalesce(v_card.backstory,''),'{destination}',v_dest),ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(coalesce(v_card.keywords,'{}')) k)) ON CONFLICT DO NOTHING; END IF;
  END IF;
 END IF;
END $_$;


--
-- Name: ensure_season_quests(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ensure_season_quests(p_trip uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF auth.uid() IS DISTINCT FROM p_user OR NOT trip_private.is_trip_member(p_trip,p_user) THEN RAISE EXCEPTION 'Only approved members can see quests'; END IF; END $$;


--
-- Name: ensure_weekly_questions(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ensure_weekly_questions(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE n record; tz text; d date; t public.trips; v_start date; v_nights int; k int := 0; BEGIN
SELECT * INTO t FROM public.trips WHERE id=p_trip; tz := t.home_timezone;
v_start := trip_private.season_start(p_trip);
SELECT count(*) INTO v_nights FROM public.game_nights WHERE trip_id=p_trip;
IF v_nights <= 1 THEN RETURN; END IF;
FOR n IN SELECT cur.week_number, cur.starts_at cur_start, prev.starts_at prev_start FROM public.game_nights cur JOIN public.game_nights prev ON prev.trip_id=cur.trip_id AND prev.week_number=cur.week_number-1
  WHERE cur.trip_id=p_trip AND NOT EXISTS (SELECT 1 FROM public.weekly_questions q WHERE q.trip_id=p_trip AND q.week_number=cur.week_number) LOOP
  d := (n.prev_start AT TIME ZONE tz)::date;
  IF n.cur_start - n.prev_start < interval '7 days' THEN d := d + 1; ELSE d := d + (8 - extract(isodow FROM d)::int); END IF;
  INSERT INTO public.weekly_questions(trip_id, week_number, prompt, drops_at) VALUES (p_trip, n.week_number, trip_private.pick_weekly_prompt(p_trip), (d + time '09:00') AT TIME ZONE tz) ON CONFLICT DO NOTHING;
END LOOP;
FOR n IN SELECT cur.week_number, cur.starts_at cur_start, prev.starts_at prev_start FROM public.game_nights cur JOIN public.game_nights prev ON prev.trip_id=cur.trip_id AND prev.week_number=cur.week_number-1
  WHERE cur.trip_id=p_trip AND cur.starts_at - prev.starts_at >= interval '14 days' LOOP
  d := (n.prev_start AT TIME ZONE tz)::date; d := d + (8 - extract(isodow FROM d)::int) + 7;
  IF d < (n.cur_start AT TIME ZONE tz)::date AND NOT EXISTS (SELECT 1 FROM public.weekly_questions q WHERE q.trip_id=p_trip AND (q.week_number=2000+n.week_number OR abs((q.drops_at AT TIME ZONE tz)::date - d) <= 1)) THEN
    INSERT INTO public.weekly_questions(trip_id, week_number, prompt, drops_at) VALUES (p_trip, 2000+n.week_number, trip_private.pick_weekly_prompt(p_trip), (d + time '09:00') AT TIME ZONE tz) ON CONFLICT DO NOTHING;
  END IF;
END LOOP;
IF t.start_date - v_start < 14 THEN
  d := v_start + 1;
  WHILE d < t.start_date LOOP
    IF NOT EXISTS (SELECT 1 FROM public.weekly_questions q WHERE q.trip_id=p_trip AND q.week_number=1000+k)
       AND NOT EXISTS (SELECT 1 FROM public.weekly_questions q WHERE q.trip_id=p_trip AND q.week_number<1000 AND abs((q.drops_at AT TIME ZONE tz)::date - d) <= 1) THEN
      INSERT INTO public.weekly_questions(trip_id, week_number, prompt, drops_at) VALUES (p_trip, 1000+k, trip_private.pick_weekly_prompt(p_trip), (d + time '09:00') AT TIME ZONE tz) ON CONFLICT DO NOTHING;
    END IF; k := k + 1; d := d + 2; END LOOP;
END IF;
UPDATE public.weekly_questions SET phase='revealed', revealed_at=now() WHERE trip_id=p_trip AND week_number>=1000 AND revealed_at IS NULL AND drops_at + trip_private.bonus_window(p_trip) <= now();
END $$;


--
-- Name: extend_draw_timer(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.extend_draw_timer(p_trip uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE s public.trip_play_state%ROWTYPE; n integer;
BEGIN
  IF NOT (trip_private.is_leader(p_trip) OR trip_private.lab_bypass(p_trip) OR EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND host_id=auth.uid() AND NOT skipped AND starts_at BETWEEN now()-interval '4 hours' AND now()+interval '2 hours')) THEN
    RAISE EXCEPTION 'Only the host, Captain or Co-Captain can extend the timer';
  END IF;
  SELECT * INTO s FROM public.trip_play_state WHERE trip_id=p_trip FOR UPDATE;
  IF NOT FOUND OR s.timer_label IS DISTINCT FROM '20-sec Draw' OR s.timer_ends_at IS NULL OR s.timer_ends_at <= now() THEN
    RAISE EXCEPTION 'Start the drawing timer first';
  END IF;
  n := COALESCE(s.timer_secs, 20);
  IF n < 20 OR n >= 60 THEN RAISE EXCEPTION 'The drawing timer has reached its extra-time limit'; END IF;
  UPDATE public.trip_play_state SET timer_secs=n+10, timer_ends_at=s.timer_ends_at + interval '10 seconds', updated_at=now() WHERE trip_id=p_trip;
  RETURN n+10;
END $$;


