-- Name: finalize_season(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.finalize_season(p_trip uuid, p_season text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 PERFORM trip_private.crown_season(p_trip, p_season);
END $$;


--
-- Name: founder_age_tiers(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founder_age_tiers() RETURNS TABLE(tier text, people integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$ BEGIN
 IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
 RETURN QUERY SELECT trip_private.age_range(CASE WHEN pp.dob IS NULL THEN NULL ELSE extract(year FROM age(current_date,pp.dob))::int END), count(*)::int
  FROM auth.users u LEFT JOIN public.player_private pp ON pp.user_id=u.id
  WHERE NOT EXISTS (SELECT 1 FROM public.sandbox_bots b WHERE b.user_id=u.id) GROUP BY 1 ORDER BY 1; END $$;


--
-- Name: founder_bug_reports(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founder_bug_reports() RETURNS TABLE(id uuid, created_at timestamp with time zone, page text, description text, screenshot_path text, user_agent text, app_version text, trip_id uuid, trip_name text, reporter text, status text, founder_note text, issue_id uuid, issue_title text, issue_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  RETURN QUERY SELECT r.id, r.created_at, r.page, r.description, r.screenshot_path, r.user_agent, r.app_version, r.trip_id, t.name,
    coalesce(nullif(pp.game_name,''), nullif(p.display_name,''), 'Player'), r.status, r.founder_note, r.issue_id, i.title,
    (SELECT count(DISTINCT r2.user_id)::int FROM bug_reports r2 WHERE r2.issue_id = r.issue_id)
  FROM bug_reports r LEFT JOIN trips t ON t.id = r.trip_id LEFT JOIN profiles p ON p.id = r.user_id
  LEFT JOIN player_profiles pp ON pp.user_id = r.user_id LEFT JOIN bug_issues i ON i.id = r.issue_id
  WHERE r.trip_id IS NULL OR NOT coalesce(t.is_sandbox, false)
  ORDER BY r.created_at DESC LIMIT 500;
END $$;


--
-- Name: founder_checkins(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founder_checkins() RETURNS TABLE(id uuid, created_at timestamp with time zone, trip_name text, reporter text, context text, context_key text, answers jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  RETURN QUERY SELECT c.id, c.created_at, t.name, coalesce(nullif(pp.game_name,''), nullif(p.display_name,''), 'Player'), c.context, c.context_key, c.answers
  FROM checkin_responses c JOIN trips t ON t.id = c.trip_id LEFT JOIN profiles p ON p.id = c.user_id LEFT JOIN player_profiles pp ON pp.user_id = c.user_id
  WHERE NOT t.is_sandbox ORDER BY c.created_at DESC LIMIT 300;
END $$;


--
-- Name: founder_link_report(uuid, uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founder_link_report(p_report uuid, p_issue uuid, p_title text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_issue uuid := p_issue; v_status text; v_note text;
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  IF v_issue IS NULL AND nullif(trim(p_title),'') IS NOT NULL THEN
    SELECT status, founder_note INTO v_status, v_note FROM bug_reports WHERE id = p_report;
    INSERT INTO bug_issues(title, status, founder_note) VALUES (left(trim(p_title),140), coalesce(v_status,'new'), v_note) RETURNING id INTO v_issue;
  END IF;
  IF v_issue IS NOT NULL THEN
    SELECT status, founder_note INTO v_status, v_note FROM bug_issues WHERE id = v_issue;
    UPDATE bug_reports SET issue_id = v_issue,
      status_changed_at = CASE WHEN status IS DISTINCT FROM v_status THEN now() ELSE status_changed_at END,
      update_seen_at = CASE WHEN status IS DISTINCT FROM v_status THEN NULL ELSE update_seen_at END,
      status = v_status, founder_note = v_note WHERE id = p_report;
  ELSE
    UPDATE bug_reports SET issue_id = NULL WHERE id = p_report;
  END IF;
  RETURN v_issue;
END $$;


--
-- Name: founder_open_summary(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founder_open_summary() RETURNS TABLE(issue_id uuid, title text, page text, status text, people integer, reports integer, last_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  RETURN QUERY SELECT r.issue_id, coalesce(i.title, left(min(r.description), 80)), min(r.page), min(r.status),
    count(DISTINCT r.user_id)::int, count(*)::int, max(r.created_at)
  FROM bug_reports r LEFT JOIN bug_issues i ON i.id = r.issue_id LEFT JOIN trips t ON t.id = r.trip_id
  WHERE r.status IN ('new','looking','need_info') AND NOT coalesce(t.is_sandbox,false)
  GROUP BY r.issue_id, i.title, CASE WHEN r.issue_id IS NULL THEN r.id END
  ORDER BY count(DISTINCT r.user_id) DESC, max(r.created_at) DESC;
END $$;


--
-- Name: founder_trips(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founder_trips() RETURNS TABLE(id uuid, name text, kind text, captain text, start_date date, created_at timestamp with time zone, rules_version smallint, is_sandbox boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  RETURN QUERY
    SELECT t.id, t.name, t.kind,
           (SELECT coalesce(p.display_name, 'Captain') FROM public.trip_members m
            LEFT JOIN public.profiles p ON p.id = m.user_id
            WHERE m.trip_id = t.id AND m.role = 'captain' LIMIT 1),
           t.start_date, t.created_at, t.rules_version, coalesce(t.is_sandbox, false)
    FROM public.trips t ORDER BY t.created_at DESC;
END $$;


--
-- Name: founder_update_report(uuid, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founder_update_report(p_report uuid, p_status text, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_issue uuid;
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  SELECT issue_id INTO v_issue FROM bug_reports WHERE id = p_report;
  IF v_issue IS NOT NULL THEN
    UPDATE bug_issues SET status = p_status, founder_note = left(p_note, 500), updated_at = now() WHERE id = v_issue;
    UPDATE bug_reports SET status_changed_at = CASE WHEN status IS DISTINCT FROM p_status THEN now() ELSE status_changed_at END,
      update_seen_at = CASE WHEN status IS DISTINCT FROM p_status THEN NULL ELSE update_seen_at END,
      status = p_status, founder_note = left(p_note, 500) WHERE issue_id = v_issue;
  ELSE
    UPDATE bug_reports SET status_changed_at = CASE WHEN status IS DISTINCT FROM p_status THEN now() ELSE status_changed_at END,
      update_seen_at = CASE WHEN status IS DISTINCT FROM p_status THEN NULL ELSE update_seen_at END,
      status = p_status, founder_note = left(p_note, 500) WHERE id = p_report;
  END IF;
END $$;


--
-- Name: founding_member(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founding_member(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT auth.uid() IS NOT NULL AND (p_user=auth.uid() OR EXISTS(SELECT 1 FROM public.trip_members a JOIN public.trip_members b ON a.trip_id=b.trip_id WHERE a.user_id=auth.uid() AND a.status='approved' AND b.user_id=p_user AND b.status='approved')) AND EXISTS(SELECT 1 FROM public.account_consents c WHERE c.user_id=p_user AND c.founding_member) $$;


--
-- Name: founding_signup_trg(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.founding_signup_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF (SELECT founding_open FROM public.app_settings LIMIT 1) THEN INSERT INTO public.account_consents(user_id,founding_member) VALUES(NEW.id,true) ON CONFLICT(user_id) DO UPDATE SET founding_member=true,updated_at=now(); END IF; RETURN NEW; END $$;


--
-- Name: game_board(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.game_board(p_trip uuid) RETURNS TABLE(user_id uuid, stamps integer, mx integer, pen integer, attended integer, score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH pen AS (SELECT hp.user_id, sum(hp.stamps)::int n FROM public.host_penalties hp JOIN public.game_nights gn ON gn.trip_id=hp.trip_id AND gn.week_number=hp.week_number AND NOT gn.skipped
   WHERE hp.trip_id=p_trip AND NOT EXISTS (SELECT 1 FROM public.skip_passes sp WHERE sp.trip_id=p_trip AND sp.user_id=hp.user_id AND sp.kind='captain' AND sp.ref=hp.week_number::text) GROUP BY hp.user_id),
att AS (SELECT s.user_id, count(*)::int n FROM public.game_scores s JOIN public.game_nights gn ON gn.trip_id=s.trip_id AND gn.week_number=s.week_number AND NOT gn.skipped AND gn.starts_at <= now() WHERE s.trip_id=p_trip AND s.here GROUP BY s.user_id),
bon AS (SELECT * FROM trip_private.mission_bonus(p_trip))
SELECT g.user_id, g.stamps, g.mx, coalesce(pen.n,0), coalesce(att.n,0),
  least(100, greatest(0, (CASE WHEN g.mx>0 THEN round(g.stamps*100.0/g.mx) ELSE 0 END)::int - coalesce(pen.n,0) + coalesce(bon.points,0)))::int
FROM trip_private.game_stamps(p_trip) g LEFT JOIN pen ON pen.user_id=g.user_id LEFT JOIN att ON att.user_id=g.user_id LEFT JOIN bon ON bon.user_id=g.user_id $$;


--
-- Name: game_card_view(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.game_card_view(p_trip uuid, p_category text DEFAULT NULL::text) RETURNS TABLE(id bigint, trip_id uuid, category text, prompt text, created_at timestamp with time zone, updated_at timestamp with time zone, game_number integer, answer text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id bigint; BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=auth.uid() AND m.status='approved') THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 IF p_category IS NULL THEN
  SELECT s.draw_card_id INTO v_id FROM public.trip_play_state s WHERE s.trip_id=p_trip;
  RETURN QUERY SELECT c.id,c.trip_id,c.category,trip_private.render_card(p_trip,c.prompt),c.created_at,c.updated_at,c.game_number,c.answer FROM public.game_cards c WHERE c.id=v_id AND (c.category<>'spicy' OR trip_private.is_approved_adult(p_trip,auth.uid()));
 ELSIF p_category IN ('most-likely','would-you-rather','get-to-know') THEN
  RETURN QUERY SELECT c.id,c.trip_id,c.category,trip_private.render_card(p_trip,c.prompt),c.created_at,c.updated_at,c.game_number,c.answer FROM public.game_cards c WHERE c.category=p_category AND (c.trip_id IS NULL OR c.trip_id=p_trip) ORDER BY random() LIMIT 30;
 ELSE RAISE EXCEPTION 'Only the current card or clean vote prompts are available'; END IF;
END $$;


--
-- Name: game_day_status(uuid, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.game_day_status(p_trip uuid, p_date date) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; v_len int; v_idx int; v_tag text; BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
SELECT * INTO t FROM public.trips WHERE id=p_trip;
IF p_date < t.start_date OR p_date > t.end_date THEN RETURN 'off'; END IF;
SELECT coalesce(g.tag, dt.tag) INTO v_tag FROM (SELECT 1) x LEFT JOIN public.trip_day_games g ON g.trip_id=p_trip AND g.day_date=p_date LEFT JOIN public.trip_day_tags dt ON dt.trip_id=p_trip AND dt.day_date=p_date;
IF v_tag='Travel' THEN RETURN 'travel'; END IF;
IF p_date = ANY(t.rest_days) THEN RETURN 'rest'; END IF;
IF t.surprise_mode THEN
  IF p_date > trip_private.trip_today(p_trip) AND NOT trip_private.is_leader(p_trip) THEN RETURN 'hidden'; END IF;
  RETURN CASE WHEN abs(hashtext(p_trip::text || p_date::text)) % 2 = 0 THEN 'surprise' ELSE 'rest' END;
END IF;
v_len := t.end_date - t.start_date + 1;
IF v_len <= 10 OR coalesce(t.game_days_every, 2) = 1 THEN RETURN 'game'; END IF;
SELECT count(*) INTO v_idx FROM generate_series(t.start_date, p_date - 1, interval '1 day') s(d)
  LEFT JOIN public.trip_day_games g ON g.trip_id=p_trip AND g.day_date=s.d::date LEFT JOIN public.trip_day_tags dt ON dt.trip_id=p_trip AND dt.day_date=s.d::date
  WHERE coalesce(g.tag,dt.tag) IS DISTINCT FROM 'Travel' AND NOT (s.d::date = ANY(t.rest_days));
RETURN CASE WHEN v_idx % 2 = 0 THEN 'game' ELSE 'rest' END; END $$;


--
-- Name: game_name_problem(text, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.game_name_problem(p_name text, p_user uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE n text := coalesce(p_name,''); norm text; len int;
BEGIN
  len := char_length(btrim(n));
  IF len < 2 THEN RETURN 'Game names need at least 2 characters.'; END IF;
  IF len > 15 THEN RETURN 'Game names can be up to 15 characters.'; END IF;
  IF n <> btrim(n) THEN RETURN 'Remove spaces at the start or end.'; END IF;
  IF n ~ '\s\s' THEN RETURN 'Use only one space between words.'; END IF;
  IF n !~ '[[:alpha:][:digit:]]' THEN RETURN 'Add at least one letter or number.'; END IF;
  IF n ~* '(https?:|www\.|\.(com|net|org|app|io|co|me|gg|tv)(\W|$))' THEN RETURN 'Links aren''t allowed in game names.'; END IF;
  IF n ~ '@[[:alnum:]_]' THEN RETURN '@handles aren''t allowed in game names.'; END IF;
  norm := public.normalize_game_name(n);
  IF norm ~ '(fuck|shit|bitch|cunt|nigg|fag|whore|slut|dick|pussy|rape|nazi|retard)' THEN RETURN 'Please pick a friendlier name.'; END IF;
  IF norm ~ '(tripjunkie|captain|admin|support|founder)'
     AND NOT EXISTS (SELECT 1 FROM app_admins WHERE user_id = p_user) THEN
    RETURN 'That name is reserved. Try something else.'; END IF;
  IF EXISTS (SELECT 1 FROM player_profiles WHERE public.normalize_game_name(game_name) = norm AND user_id IS DISTINCT FROM p_user) THEN
    RETURN 'TAKEN'; END IF;
  RETURN NULL;
END $_$;


--
-- Name: game_rooms(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.game_rooms() RETURNS TABLE(trip_id uuid, nickname text, country text, region text, city text, nights_played integer, ended boolean, crowns jsonb, leaders jsonb, is_member boolean, requested boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR coalesce(trip_private.age_of(auth.uid()),0) < 18 THEN RETURN; END IF;
  RETURN QUERY
  SELECT t.id, t.room_nickname, t.room_country, t.room_region, t.room_city,
    (SELECT count(*)::int FROM game_nights gn WHERE gn.trip_id=t.id AND NOT gn.skipped AND gn.starts_at <= now()),
    (t.ended_at IS NOT NULL OR t.end_date < current_date),
    coalesce((SELECT jsonb_agg(sc.season) FROM season_champions sc WHERE sc.trip_id=t.id), '[]'::jsonb),
    coalesce((SELECT jsonb_agg(jsonb_build_object('name', x.name, 'score', x.score, 'stamp', x.stamp) ORDER BY x.score DESC) FROM (
       SELECT CASE WHEN coalesce(pp.public_leaderboard,true) THEN coalesce(nullif(pc.game_name,''),'Player') ELSE 'Traveler' END AS name, b.score,
       CASE WHEN coalesce(pp.public_leaderboard,true) THEN
         (SELECT jsonb_build_object('country',s.country,'state',s.state,'city',s.city,'date',s.stamped_on,'trip',s.trip_name,'squad',s.squad_count,'count',(SELECT count(*) FROM passport_stamps sx WHERE sx.user_id=s.user_id AND sx.trip_id=t.id)) FROM passport_stamps s WHERE s.user_id=b.user_id AND s.trip_id=t.id ORDER BY s.stamped_on DESC LIMIT 1)
       ELSE NULL END AS stamp
       FROM trip_private.game_board(t.id) b
       JOIN trip_members m ON m.trip_id=t.id AND m.user_id=b.user_id AND m.status='approved'
       LEFT JOIN trip_player_cards pc ON pc.trip_id=t.id AND pc.user_id=b.user_id
       LEFT JOIN player_profiles pp ON pp.user_id=b.user_id
       WHERE coalesce(trip_private.age_of(b.user_id),0) >= 18
       ORDER BY b.score DESC LIMIT CASE WHEN (t.ended_at IS NOT NULL OR t.end_date < current_date) THEN 3 ELSE 5 END) x), '[]'::jsonb),
    EXISTS (SELECT 1 FROM trip_members m WHERE m.trip_id=t.id AND m.user_id=auth.uid() AND m.status='approved'),
    EXISTS (SELECT 1 FROM room_requests r WHERE r.trip_id=t.id AND r.user_id=auth.uid() AND r.status='pending' AND r.expires_at > now())
  FROM trips t WHERE t.room_listed AND NOT t.is_sandbox AND t.room_nickname IS NOT NULL AND t.room_country IS NOT NULL
  ORDER BY t.created_at;
END $$;


--
-- Name: game_stamps(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.game_stamps(p_trip uuid) RETURNS TABLE(user_id uuid, stamps integer, mx integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH v AS (SELECT coalesce((SELECT here_stamps FROM public.stamp_settings WHERE trip_id=p_trip),1) h, coalesce((SELECT win_stamps FROM public.stamp_settings WHERE trip_id=p_trip),3) w, coalesce((SELECT host_stamps FROM public.stamp_settings WHERE trip_id=p_trip),1) ho),
g AS (SELECT m.user_id,
  sum(v.h + v.w + CASE WHEN n.host_id=m.user_id THEN v.ho ELSE 0 END) mx,
  sum(CASE WHEN s.here THEN v.h + CASE WHEN n.host_id=m.user_id THEN v.ho ELSE 0 END ELSE 0 END + CASE WHEN s.won THEN v.w ELSE 0 END) stamps
  FROM public.trip_members m CROSS JOIN v JOIN public.game_nights n ON n.trip_id=m.trip_id AND n.starts_at <= now() AND NOT n.skipped
  LEFT JOIN public.game_scores s ON s.trip_id=m.trip_id AND s.week_number=n.week_number AND s.user_id=m.user_id
  WHERE m.trip_id=p_trip AND m.status='approved'
    AND NOT EXISTS (SELECT 1 FROM public.skip_passes sp WHERE sp.trip_id=p_trip AND sp.user_id=m.user_id AND sp.kind='captain' AND sp.ref=n.week_number::text)
  GROUP BY m.user_id),
qw AS (SELECT (3*count(*) FILTER (WHERE week_number < 1000) + count(*) FILTER (WHERE week_number >= 1000))::int total FROM public.weekly_questions WHERE trip_id=p_trip AND revealed_at IS NOT NULL),
qa AS (SELECT a.user_id, (count(*) + 2*count(*) FILTER (WHERE q.winner_id=a.user_id))::int n FROM public.weekly_answers a JOIN public.weekly_questions q ON q.trip_id=a.trip_id AND q.week_number=a.week_number AND q.revealed_at IS NOT NULL WHERE a.trip_id=p_trip GROUP BY a.user_id)
SELECT m.user_id, (coalesce(g.stamps,0)+coalesce(qa.n,0)+m.start_stamps)::int, (coalesce(g.mx,0)+qw.total)::int
FROM public.trip_members m JOIN public.trips t ON t.id=m.trip_id AND t.season_scoring CROSS JOIN qw LEFT JOIN g ON g.user_id=m.user_id LEFT JOIN qa ON qa.user_id=m.user_id
WHERE m.trip_id=p_trip AND m.status='approved' AND NOT m.season_closed $$;


--
-- Name: games_live(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.games_live(p_trip uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RETURN false; END IF;
  RETURN trip_private.lab_bypass(p_trip) OR EXISTS (SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped AND trip_private.night_open(p_trip, n.week_number));
END $$;


--
-- Name: guard_archived_trip(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_archived_trip() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR trip_private.is_app_admin() THEN RETURN NEW; END IF;
  IF trip_private.trip_is_archived(NEW.trip_id)
     OR (TG_OP = 'UPDATE' AND trip_private.trip_is_archived(OLD.trip_id)) THEN
    RAISE EXCEPTION 'TRIP_ARCHIVED: This trip is archived and can''t be changed.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_archived_trip_row(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_archived_trip_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR trip_private.is_app_admin() THEN RETURN NEW; END IF;
  IF NEW.rules_version IS DISTINCT FROM OLD.rules_version THEN
    RAISE EXCEPTION 'Only an app admin can archive or restore a trip';
  END IF;
  IF OLD.rules_version = 1 THEN
    RAISE EXCEPTION 'TRIP_ARCHIVED: This trip is archived and can''t be changed.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_auth_signup_age(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_auth_signup_age() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
DECLARE v_dob date; v_text text; v_age int;
BEGIN
 IF NEW.id IS NULL OR NEW.created_at IS NULL THEN RETURN NEW; END IF;
 IF coalesce(NEW.raw_app_meta_data->>'sandbox_bot','') = 'true' THEN RETURN NEW; END IF;
 IF NEW.raw_app_meta_data->>'provider' = 'email' AND NEW.raw_user_meta_data->>'legal_version' IN ('2026-10-02','2026-10-03') THEN
   v_text := NEW.raw_user_meta_data->>'birthday';
   IF v_text IS NULL OR v_text !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'A birthday is required to sign up'; END IF;
   BEGIN v_dob := v_text::date; EXCEPTION WHEN others THEN RAISE EXCEPTION 'Check your birthday'; END;
   IF v_dob > current_date OR v_dob < date '1900-01-01' THEN RAISE EXCEPTION 'Check your birthday'; END IF;
   v_age := extract(year FROM age(current_date,v_dob))::int;
   IF v_age < 13 THEN RAISE EXCEPTION 'Family Mode is coming soon. TripJunkies accounts are for ages 13 and up.'; END IF;
 ELSIF NEW.raw_app_meta_data->>'provider' = 'email' AND NEW.created_at >= timestamptz '2026-10-02 22:00:00+00' THEN
   RAISE EXCEPTION 'Please provide your birthday and accept the current Terms';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_generated_content(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_generated_content() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_text text; BEGIN v_text:=CASE TG_TABLE_NAME WHEN 'game_cards' THEN to_jsonb(NEW)->>'prompt' WHEN 'weekly_question_pool' THEN to_jsonb(NEW)->>'prompt' WHEN 'at_home_pack_items' THEN coalesce(to_jsonb(NEW)->>'title','')||' '||coalesce(to_jsonb(NEW)->>'body','') WHEN 'content_variants' THEN to_jsonb(NEW)->>'text' WHEN 'security_missions' THEN coalesce(to_jsonb(NEW)->>'title','')||' '||coalesce(to_jsonb(NEW)->>'text','') ELSE '' END; IF NOT trip_private.content_text_safe(v_text) THEN RAISE EXCEPTION 'Content did not pass the safety check'; END IF; RETURN NEW; END $$;


--
-- Name: guard_local_trip_membership(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_local_trip_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_mode text; v_captain uuid;
BEGIN
 SELECT t.play_arrangement INTO v_mode FROM public.trips t WHERE t.id=NEW.trip_id;
 IF v_mode IN ('solo','offline') THEN
   SELECT m.user_id INTO v_captain FROM public.trip_members m WHERE m.trip_id=NEW.trip_id AND m.role='captain' LIMIT 1;
   IF v_captain IS NOT NULL AND NEW.user_id IS DISTINCT FROM v_captain THEN
     RAISE EXCEPTION 'This room is played on one phone; guests do not join with accounts';
   END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_open_trip(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_open_trip() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t uuid; BEGIN
IF TG_TABLE_NAME = 'live_vote_ballots' THEN SELECT trip_id INTO t FROM public.live_votes WHERE id = coalesce(NEW.vote_id, OLD.vote_id);
ELSIF TG_OP = 'DELETE' THEN t := OLD.trip_id; ELSE t := NEW.trip_id; END IF;
IF t IS NOT NULL AND NOT coalesce(trip_private.trip_open(t), true) THEN RAISE EXCEPTION 'This trip has ended — it''s read-only now'; END IF;
RETURN coalesce(NEW, OLD); END $$;


--
-- Name: guard_order_money(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_order_money() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.collected_cents <> 0 OR NEW.status <> 'beta_free' OR NEW.provider_ref IS NOT NULL THEN
    IF trip_private.beta_free() THEN RAISE EXCEPTION 'Free during beta — nothing can be charged.'; END IF;
    IF NEW.status='paid' AND NEW.provider_ref IS NULL THEN RAISE EXCEPTION 'Paid status needs a verified payment.'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_public_leaderboard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.guard_public_leaderboard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF coalesce(trip_private.age_of(NEW.user_id),0) < 18 THEN NEW.public_leaderboard := false; END IF; RETURN NEW; END $$;


--
-- Name: has_beta_access(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.has_beta_access() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL AND ((SELECT public_launch FROM public.app_settings LIMIT 1)
    OR EXISTS (SELECT 1 FROM public.beta_access WHERE user_id=auth.uid())
    OR EXISTS (SELECT 1 FROM public.trip_members WHERE user_id=auth.uid() AND status='approved')
    OR trip_private.is_app_admin()) $$;


--
-- Name: has_teen_member(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.has_teen_member(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.status IN ('approved','pending') AND trip_private.age_of(m.user_id) BETWEEN 0 AND 17 AND NOT EXISTS (SELECT 1 FROM public.sandbox_bots b WHERE b.user_id=m.user_id)) $$;


--
-- Name: hide_inspiration(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.hide_inspiration(p_card uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF; UPDATE public.cultural_inspirations SET hidden_at=now() WHERE id=p_card AND hidden_at IS NULL; IF FOUND THEN INSERT INTO trip_private.inspiration_moderation(card_id,actor,action) VALUES(p_card,auth.uid(),'hide'); END IF; END $$;


--
-- Name: home_day_action(uuid, text, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.home_day_action(p_session uuid, p_action text, p_choice integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE s public.home_day_sessions; v_next uuid; BEGIN
 SELECT * INTO s FROM public.home_day_sessions WHERE id=p_session FOR UPDATE;
 IF NOT FOUND OR NOT trip_private.is_trip_member(s.trip_id,auth.uid()) THEN RAISE EXCEPTION 'Join this experience first'; END IF;
 IF now()<s.starts_at THEN RAISE EXCEPTION 'This Game Day has not started'; END IF;
 IF p_action='complete' AND s.step IN ('card','present') THEN
   INSERT INTO public.home_day_results(session_id,user_id,completed_at) VALUES(s.id,auth.uid(),now()) ON CONFLICT(session_id,user_id) DO UPDATE SET completed_at=coalesce(home_day_results.completed_at,EXCLUDED.completed_at);
 ELSIF p_action='presented' THEN
   IF NOT trip_private.is_leader(s.trip_id) OR s.step<>'present' OR s.presenter_id IS NULL THEN RAISE EXCEPTION 'The host marks each presentation'; END IF;
   INSERT INTO public.home_day_results(session_id,user_id,presented_at) VALUES(s.id,s.presenter_id,now()) ON CONFLICT(session_id,user_id) DO UPDATE SET presented_at=coalesce(home_day_results.presented_at,EXCLUDED.presented_at);
   SELECT m.user_id INTO v_next FROM public.trip_members m WHERE m.trip_id=s.trip_id AND m.status='approved' AND m.user_id<>s.presenter_id AND NOT EXISTS(SELECT 1 FROM public.home_day_results r WHERE r.session_id=s.id AND r.user_id=m.user_id AND r.presented_at IS NOT NULL) ORDER BY m.approved_at,m.joined_at LIMIT 1;
   UPDATE public.home_day_sessions SET presenter_id=v_next,step=CASE WHEN v_next IS NULL THEN 'vote' ELSE 'present' END WHERE id=s.id;
 ELSIF p_action='next' THEN
   IF NOT trip_private.is_leader(s.trip_id) OR s.step<>'card' THEN RAISE EXCEPTION 'Only the host opens presentations'; END IF;
   SELECT m.user_id INTO v_next FROM public.trip_members m WHERE m.trip_id=s.trip_id AND m.status='approved' ORDER BY m.approved_at,m.joined_at LIMIT 1;
   UPDATE public.home_day_sessions SET presenter_id=v_next,step=CASE WHEN v_next IS NULL THEN 'vote' ELSE 'present' END WHERE id=s.id;
 ELSIF p_action='vote' THEN
   IF s.step<>'vote' OR p_choice NOT IN (0,1) THEN RAISE EXCEPTION 'Voting is not open'; END IF;
   INSERT INTO public.home_day_results(session_id,user_id,voted_at,choice) VALUES(s.id,auth.uid(),now(),p_choice) ON CONFLICT(session_id,user_id) DO UPDATE SET voted_at=EXCLUDED.voted_at,choice=EXCLUDED.choice;
 ELSIF p_action='reveal' THEN
   IF NOT trip_private.is_leader(s.trip_id) OR s.step<>'vote' THEN RAISE EXCEPTION 'Only the host reveals votes'; END IF;
   IF NOT EXISTS (SELECT 1 FROM public.home_day_results WHERE session_id=s.id AND voted_at IS NOT NULL) THEN RAISE EXCEPTION 'Wait for at least one vote'; END IF;
   UPDATE public.home_day_sessions SET step='done',revealed_at=now() WHERE id=s.id;
   IF NOT EXISTS (SELECT 1 FROM public.home_day_sessions WHERE trip_id=s.trip_id AND step<>'done') THEN
     INSERT INTO public.season_champions(trip_id,season,user_id,score,stamps)
       SELECT s.trip_id,'home',x.user_id,x.points,0 FROM trip_private.home_day_scores(s.trip_id) x
       WHERE x.points > 0 AND x.points = (SELECT max(y.points) FROM trip_private.home_day_scores(s.trip_id) y)
       ON CONFLICT DO NOTHING;
   END IF;
 ELSE RAISE EXCEPTION 'This step is not open'; END IF;
END $$;


--
-- Name: home_day_finish_postcard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.home_day_finish_postcard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pack text; BEGIN
 IF NEW.step='done' AND OLD.step IS DISTINCT FROM NEW.step AND NOT EXISTS (SELECT 1 FROM public.home_day_sessions s WHERE s.trip_id=NEW.trip_id AND s.id<>NEW.id AND s.step<>'done') THEN
   SELECT at_home_pack INTO v_pack FROM public.trips WHERE id=NEW.trip_id AND kind='at_home';
   IF v_pack IS NOT NULL THEN
     INSERT INTO public.postcard_stickers(user_id,trip_id,pack) SELECT user_id,NEW.trip_id,v_pack FROM public.trip_members WHERE trip_id=NEW.trip_id AND status='approved' ON CONFLICT DO NOTHING;
   END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: home_day_schedule(uuid, date, time without time zone, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.home_day_schedule(p_trip uuid, p_day date, p_time time without time zone, p_all boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can set session times'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF t.kind NOT IN ('at_home','cultural_inspiration') OR p_day NOT BETWEEN t.start_date AND t.end_date OR p_time IS NULL THEN RAISE EXCEPTION 'Choose an experience day and time'; END IF;
 IF p_all THEN
   UPDATE public.home_day_sessions SET starts_at=(day_date+p_time) AT TIME ZONE t.home_timezone WHERE trip_id=p_trip AND step='card' AND starts_at>now();
 ELSE
   UPDATE public.home_day_sessions SET starts_at=(p_day+p_time) AT TIME ZONE t.home_timezone WHERE trip_id=p_trip AND day_date=p_day AND step='card' AND starts_at>now();
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'This session has already started'; END IF;
END $$;


--
-- Name: home_day_scores(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.home_day_scores(p_trip uuid) RETURNS TABLE(user_id uuid, points integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this experience first'; END IF; RETURN QUERY SELECT m.user_id,(coalesce(sum((CASE WHEN r.completed_at IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN r.presented_at IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN r.voted_at IS NOT NULL THEN 1 ELSE 0 END)) FILTER (WHERE s.revealed_at IS NOT NULL),0)+coalesce(q.points,0))::int FROM public.trip_members m LEFT JOIN public.home_day_sessions s ON s.trip_id=m.trip_id LEFT JOIN public.home_day_results r ON r.session_id=s.id AND r.user_id=m.user_id LEFT JOIN trip_private.season_quest_bonus(p_trip,'preflight') q ON q.user_id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' GROUP BY m.user_id,q.points ORDER BY 2 DESC,m.user_id; END $$;


--
-- Name: home_day_view(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.home_day_view(p_trip uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE result jsonb; t public.trips; BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this experience first'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF t.kind NOT IN ('at_home','cultural_inspiration') THEN RAISE EXCEPTION 'Not a home experience'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'day',s.day_date,'startsAt',s.starts_at,'place',s.place,'step',s.step,'presenter',s.presenter_id,'revealed',s.revealed_at IS NOT NULL,'title',CASE WHEN now()>=s.starts_at THEN i.title END,'body',CASE WHEN now()>=s.starts_at THEN i.body END,'mine',coalesce((SELECT jsonb_build_object('completed',r.completed_at IS NOT NULL,'presented',r.presented_at IS NOT NULL,'voted',r.voted_at IS NOT NULL,'choice',r.choice) FROM public.home_day_results r WHERE r.session_id=s.id AND r.user_id=auth.uid()),'{}'::jsonb),'counts',CASE WHEN s.revealed_at IS NOT NULL THEN (SELECT jsonb_build_array(count(*) FILTER(WHERE choice=0),count(*) FILTER(WHERE choice=1)) FROM public.home_day_results r WHERE r.session_id=s.id) ELSE NULL END) ORDER BY s.day_date),'[]'::jsonb) INTO result
 FROM public.home_day_sessions s JOIN public.at_home_pack_items i ON i.id=s.card_id WHERE s.trip_id=p_trip;
 RETURN result;
END $$;


--
-- Name: host_check_in(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.host_check_in(p_trip uuid, p_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE n public.game_nights; BEGIN
 SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
 IF NOT FOUND OR n.host_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only tonight''s host can check in'; END IF;
 IF clock_timestamp() < n.starts_at - interval '2 hours' OR clock_timestamp() > n.starts_at + interval '3 hours' THEN RAISE EXCEPTION 'Check-in opens 2 hours before game night'; END IF;
 UPDATE public.game_nights SET host_checked_in_at = coalesce(host_checked_in_at, now()) WHERE trip_id=p_trip AND week_number=p_week; END $$;


--
-- Name: in_slice(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.in_slice(p_trip uuid, p_key text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ SELECT true $$;


--
-- Name: FUNCTION in_slice(p_trip uuid, p_key text); Type: COMMENT; Schema: trip_private; Owner: -
--

COMMENT ON FUNCTION trip_private.in_slice(p_trip uuid, p_key text) IS 'M1-10: always true (the weekly preview slice is gone). Kept only for older callers.';


--
-- Name: inspiration_age_gate(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.inspiration_age_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a int := coalesce(trip_private.age_of(NEW.creator_id),0); pa int; BEGIN
 IF a < 18 AND NOT EXISTS (SELECT 1 FROM public.sandbox_bots WHERE user_id=NEW.creator_id) THEN RAISE EXCEPTION 'Posting experiences is for players 18 and older'; END IF;
 IF NEW.partner_id IS NOT NULL THEN
   pa := coalesce(trip_private.age_of(NEW.partner_id),0);
   IF pa < 13 OR (pa < 18 AND NOT (NEW.trip_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=NEW.trip_id AND m.user_id=NEW.partner_id AND m.status='approved'))) THEN
     RAISE EXCEPTION 'Team up partners under 18 must be in this trip''s squad'; END IF;
 END IF;
 NEW.captain_approved_at := CASE WHEN a >= 21 OR trip_private.is_captain(NEW.trip_id) THEN now() ELSE NULL END;
 RETURN NEW; END $$;


--
-- Name: inspiration_keep_approval(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.inspiration_keep_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF NEW.captain_approved_at IS DISTINCT FROM OLD.captain_approved_at AND coalesce(current_setting('trip.approving',true),'') <> 'on' THEN NEW.captain_approved_at := OLD.captain_approved_at; END IF; RETURN NEW; END $$;


--
-- Name: inspiration_place_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.inspiration_place_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NEW.country IS NOT NULL AND NEW.country !~ '^[A-Z]{2}$' THEN RAISE EXCEPTION 'Choose a country'; END IF;
  IF TG_OP='INSERT' AND NEW.country IS NULL THEN RAISE EXCEPTION 'Choose a country'; END IF;
  NEW.region := nullif(left(btrim(coalesce(NEW.region,'')),80),'');
  NEW.city := nullif(left(btrim(coalesce(NEW.city,'')),80),'');
  -- Public approval is founder-only (via moderate_inspiration); clients can never set it.
  IF TG_OP='INSERT' THEN NEW.public_approved_at := NULL;
  ELSIF NEW.public_approved_at IS DISTINCT FROM OLD.public_approved_at AND coalesce(current_setting('trip.moderating',true),'')<>'on' THEN NEW.public_approved_at := OLD.public_approved_at; END IF;
  IF NOT NEW.feature_later THEN NEW.public_approved_at := NULL; END IF;
  RETURN NEW;
END $_$;


--
-- Name: inspiration_public(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.inspiration_public(p_card uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS(SELECT 1 FROM public.cultural_inspirations c JOIN public.trips t ON t.id=c.trip_id WHERE c.id=p_card AND c.captain_approved_at IS NOT NULL AND c.feature_later AND c.public_approved_at IS NOT NULL AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND NOT coalesce(t.is_sandbox,false)) $$;


--
-- Name: inspiration_validate(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.inspiration_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.trip_id<>OLD.trip_id OR NEW.creator_id<>OLD.creator_id OR NEW.partner_id IS DISTINCT FROM OLD.partner_id OR NEW.mode<>OLD.mode THEN RAISE EXCEPTION 'Experience ownership cannot be changed'; END IF; END IF; IF NEW.partner_id IS NOT NULL AND NOT trip_private.is_trip_member(NEW.trip_id,NEW.partner_id) THEN RAISE EXCEPTION 'Partner must be in the squad'; END IF; IF NEW.photo_path IS NOT NULL AND (split_part(NEW.photo_path,'/',1)<>NEW.id::text OR NEW.photo_path !~* '\.(jpe?g|png|webp)$') THEN RAISE EXCEPTION 'Invalid photo path'; END IF; NEW.updated_at:=now(); RETURN NEW; END $_$;


--
-- Name: inspiration_vote_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.inspiration_vote_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NEW.choice<>'love' THEN RAISE EXCEPTION 'Only emoji reactions are available'; END IF; RETURN NEW; END $$;


--
-- Name: inspiration_vote_validate(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.inspiration_vote_validate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$ BEGIN IF NEW.card_id<>OLD.card_id OR NEW.voter_id<>OLD.voter_id THEN RAISE EXCEPTION 'Ballot cannot be reassigned'; END IF; RETURN NEW; END $$;


--
-- Name: is_app_admin(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.is_app_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.app_admins WHERE user_id = auth.uid()) $$;


--
-- Name: is_approved_adult(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.is_approved_adult(p_trip uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT auth.uid()=p_user AND EXISTS (SELECT 1 FROM public.trips t JOIN public.trip_adult_approvals a ON a.trip_id=t.id AND a.user_id=p_user WHERE t.id=p_trip AND t.vibe='party' AND NOT t.has_minors AND trip_private.is_trip_member(p_trip,p_user) AND coalesce(trip_private.age_of(p_user),0)>=21 AND NOT coalesce((SELECT no_alcohol FROM public.player_private WHERE user_id=p_user),false)) $$;


--
-- Name: is_captain(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.is_captain(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') $$;


--
-- Name: is_leader(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.is_leader(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role IN ('captain','co_captain')) $$;


--
-- Name: is_trip_member(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.is_trip_member(p_trip uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id = p_trip AND user_id = p_user AND status = 'approved') $$;


--
-- Name: is_unlocked(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.is_unlocked(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT coalesce((SELECT unlocked_at IS NOT NULL FROM public.trips WHERE id=p_trip), false) $$;


--
-- Name: is_window_room(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.is_window_room(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.culture_experiences WHERE trip_id=p_trip AND a2e_kind='inspire') $$;


--
-- Name: join_trip(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.join_trip(p_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips%ROWTYPE; inv public.trip_invites%ROWTYPE; v_count integer; v_approved integer; v_code text := upper(trim(coalesce(p_code,''))); v_age int; v_status text; via_invite boolean := false; was_removed boolean := false; v_teen_invite boolean := false; BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  PERFORM trip_private.code_rate_check();
  v_age := trip_private.age_of(auth.uid());
  IF v_age IS NULL THEN RAISE EXCEPTION 'Add your date of birth first'; END IF;
  IF length(v_code) = 10 THEN
    SELECT * INTO inv FROM public.trip_invites WHERE token=v_code FOR UPDATE;
    IF NOT FOUND THEN INSERT INTO trip_private.code_attempts(user_id) VALUES (auth.uid()); RETURN NULL; END IF;
    SELECT * INTO t FROM public.trips WHERE id=inv.trip_id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id = t.id AND user_id = auth.uid()) THEN RETURN t.id; END IF;
    IF inv.used_at IS NOT NULL OR inv.cancelled_at IS NOT NULL OR inv.expires_at <= now() THEN RAISE EXCEPTION 'This invite link has expired or was already used. Ask your Captain for a new one.'; END IF;
    via_invite := true;
    v_teen_invite := inv.teen AND inv.guardian_confirmed_at IS NOT NULL;
  ELSE
    SELECT * INTO t FROM public.trips WHERE join_code = v_code FOR UPDATE;
    IF NOT FOUND THEN INSERT INTO trip_private.code_attempts(user_id) VALUES (auth.uid()); RETURN NULL; END IF;
    IF EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id = t.id AND user_id = auth.uid()) THEN RETURN t.id; END IF;
    IF NOT t.join_locked AND NOT t.join_code_enabled THEN RAISE EXCEPTION 'This trip''s join code is turned off. Ask your Captain for a personal invite link.'; END IF;
    was_removed := EXISTS (SELECT 1 FROM trip_private.trip_removals WHERE trip_id=t.id AND user_id=auth.uid());
  END IF;
  IF t.join_locked THEN RAISE EXCEPTION 'This trip isn''t taking new members right now'; END IF;
  IF v_age < 18 THEN
    IF NOT v_teen_invite AND t.season_rule IS DISTINCT FROM 'a2c' THEN RAISE EXCEPTION 'Under 18? Ask your trip''s Captain for a teen invite link.'; END IF;
    IF t.vibe='party' THEN RAISE EXCEPTION 'This trip isn''t open to players under 18'; END IF;
    IF EXISTS (SELECT 1 FROM public.trip_members m WHERE m.user_id=auth.uid()) THEN RAISE EXCEPTION 'Players under 18 can be in one trip at a time'; END IF;
  END IF;
  SELECT count(*), count(*) FILTER (WHERE status='approved') INTO v_count, v_approved FROM public.trip_members WHERE trip_id = t.id;
  IF v_approved >= t.max_squad THEN RAISE EXCEPTION 'This squad is full'; END IF;
  IF v_count >= 30 THEN RAISE EXCEPTION 'This trip is full (30 players max)'; END IF;
  IF v_count >= 20 AND NOT t.big_group THEN RAISE EXCEPTION 'This trip is at 20 players. The Captain can unlock the Big Group add-on for up to 30.'; END IF;
  v_status := CASE WHEN t.require_approval OR v_age < 21 OR was_removed THEN 'pending' ELSE 'approved' END;
  IF via_invite THEN
    UPDATE public.trip_invites SET used_by=auth.uid(), used_at=now() WHERE id=inv.id;
    DELETE FROM trip_private.trip_removals WHERE trip_id=t.id AND user_id=auth.uid();
  END IF;
  INSERT INTO public.trip_members(trip_id,user_id,status,approved_at) VALUES(t.id,auth.uid(),v_status,CASE WHEN v_status='approved' THEN now() END);
  IF v_status = 'approved' THEN
    PERFORM trip_private.apply_join_baseline(t.id, auth.uid());
    INSERT INTO public.beta_access(user_id, source) VALUES (auth.uid(), 'invite') ON CONFLICT DO NOTHING;
  END IF;
  RETURN t.id;
END $$;


--
-- Name: join_waitlist(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.join_waitlist(p_email text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE e text := lower(trim(coalesce(p_email,''))); BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  IF e !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' OR length(e) > 254 THEN RAISE EXCEPTION 'Please enter a valid email'; END IF;
  IF (SELECT count(*) FROM public.waitlist WHERE user_id=auth.uid()) >= 3 THEN RETURN; END IF;
  INSERT INTO public.waitlist(email, user_id) VALUES (e, auth.uid()) ON CONFLICT (email) DO NOTHING; END $_$;


--
-- Name: junkie_rank(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.junkie_rank(p_user uuid) RETURNS TABLE(tier text, points integer, next_tier text, next_at integer, tier_at integer, passport_junkie boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pts int; v_best int; v_intl int;
BEGIN
  IF p_user IS NULL OR (p_user <> auth.uid() AND NOT EXISTS (SELECT 1 FROM public.trip_members a JOIN public.trip_members b ON b.trip_id=a.trip_id AND b.status='approved' WHERE a.user_id=auth.uid() AND a.status='approved' AND b.user_id=p_user)) THEN RAISE EXCEPTION 'Not allowed'; END IF;
  WITH real AS (
    SELECT t.id, m.role FROM public.trips t JOIN public.trip_members m ON m.trip_id=t.id AND m.user_id=p_user AND m.status='approved'
    WHERE t.kind='trip' AND NOT t.is_sandbox AND (t.ended_at IS NOT NULL OR current_date > t.end_date)
      AND (SELECT count(*) FROM public.trip_members x WHERE x.trip_id=t.id AND x.status='approved') >= 3),
  home_all AS (
    SELECT t.id, row_number() OVER (PARTITION BY date_trunc('month', t.end_date) ORDER BY t.end_date, t.id) rn
    FROM public.trips t JOIN public.trip_members m ON m.trip_id=t.id AND m.user_id=p_user AND m.status='approved'
    WHERE t.kind='at_home' AND NOT t.is_sandbox AND (t.ended_at IS NOT NULL OR current_date > t.end_date)),
  home AS (SELECT id FROM home_all WHERE rn <= 4)
  SELECT
    (SELECT count(*) FROM real)*100 + (SELECT count(*) FROM real WHERE role='captain')*25
    + (SELECT count(*) FROM public.season_champions c WHERE c.user_id=p_user AND c.trip_id IN (SELECT id FROM real))*50
    + (SELECT count(*) FROM home)*40
    + (SELECT count(*) FROM public.season_champions c WHERE c.user_id=p_user AND c.trip_id IN (SELECT id FROM home))*20
    + (SELECT count(*) FROM public.culture_experiences e WHERE e.creator_id=p_user AND e.finished_at IS NOT NULL AND (e.trip_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.trips s WHERE s.id=e.trip_id AND s.is_sandbox)))*40
    + coalesce((SELECT sum(CASE trip_private.solo_fare((x.sc->>'points')::int,(x.sc->>'available')::int) WHEN 'First Class' THEN 30 WHEN 'Business' THEN 20 WHEN 'Economy' THEN 10 ELSE 0 END)
        FROM (SELECT trip_private.solo_score(e.id) sc FROM public.culture_experiences e WHERE e.creator_id=p_user AND e.play_mode='solo' AND e.finished_at IS NOT NULL) x),0)
    + (SELECT count(*) FROM public.mission_claims c JOIN public.trips s ON s.id=c.trip_id AND NOT s.is_sandbox WHERE c.user_id=p_user AND c.status='released')*5
  INTO v_pts;
  INSERT INTO public.junkie_ranks(user_id,best_points) VALUES (p_user, v_pts)
    ON CONFLICT (user_id) DO UPDATE SET best_points=greatest(public.junkie_ranks.best_points, excluded.best_points), updated_at=now()
    RETURNING best_points INTO v_best;
  PERFORM trip_private.sync_passport(p_user);
  SELECT count(*) INTO v_intl FROM public.passport_stamps s JOIN public.trips t ON t.id=s.trip_id AND t.kind='trip' AND NOT t.is_sandbox AND t.unlocked_at IS NOT NULL AND (t.ended_at IS NOT NULL OR current_date > t.end_date) AND (SELECT count(*) FROM public.trip_members x WHERE x.trip_id=t.id AND x.status='approved') >= 3 WHERE s.user_id=p_user AND s.kind='international';
  RETURN QUERY SELECT
    CASE WHEN v_best>=3000 THEN 'World Class 👑' WHEN v_best>=1500 THEN 'Jet Setter' WHEN v_best>=750 THEN 'First Class' WHEN v_best>=250 THEN 'Frequent Flyer' ELSE 'Carry-On' END,
    v_pts,
    CASE WHEN v_best>=3000 THEN NULL WHEN v_best>=1500 THEN 'World Class 👑' WHEN v_best>=750 THEN 'Jet Setter' WHEN v_best>=250 THEN 'First Class' ELSE 'Frequent Flyer' END,
    CASE WHEN v_best>=3000 THEN NULL WHEN v_best>=1500 THEN 3000 WHEN v_best>=750 THEN 1500 WHEN v_best>=250 THEN 750 ELSE 250 END,
    CASE WHEN v_best>=3000 THEN 3000 WHEN v_best>=1500 THEN 1500 WHEN v_best>=750 THEN 750 WHEN v_best>=250 THEN 250 ELSE 0 END,
    v_intl >= 5;
END $$;


--
-- Name: lab_as(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_as(p_trip uuid, p_action text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE me uuid := auth.uid(); v_claims text := current_setting('request.jwt.claims', true); v_sub text := current_setting('request.jwt.claim.sub', true);
  t public.trips; b record; r record; wk int; ok int := 0; fail int := 0; last_err text := ''; pair int[]; cnt int[] := ARRAY[0,0]; pick int; v uuid; host uuid; s public.host_swaps; k int := 0;
  answers text[] := ARRAY['Street food at midnight 🍜','Getting lost on purpose','Karaoke until sunrise','The beach, obviously 🏖️','A tuk-tuk race','Matching outfits day','Sunset boat ride','Trying every mango sticky rice'];
BEGIN
  PERFORM trip_private.lab_guard(p_trip);
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  IF p_action = 'qotw' THEN
    SELECT max(q.week_number) INTO wk FROM public.weekly_questions q LEFT JOIN public.game_nights g ON g.trip_id=q.trip_id AND g.week_number=q.week_number WHERE q.trip_id=p_trip AND q.drops_at <= now() AND q.revealed_at IS NULL AND (g.starts_at IS NULL OR g.starts_at > now());
    IF wk IS NULL THEN RAISE EXCEPTION 'No open Question of the Week right now — use Time travel › QOTW open'; END IF;
    FOR b IN SELECT m.user_id FROM public.trip_members m JOIN public.sandbox_bots sb ON sb.user_id=m.user_id WHERE m.trip_id=p_trip LOOP
      k := k + 1;
      BEGIN PERFORM trip_private.lab_become(b.user_id); PERFORM public.answer_weekly_question(p_trip, wk, answers[1 + (k % 8)], (ARRAY['😂','🔥','✈️','🌴'])[1 + (k % 4)]); ok := ok + 1;
      EXCEPTION WHEN others THEN fail := fail + 1; last_err := SQLERRM; END;
    END LOOP;
  ELSIF p_action IN ('vote','tie') THEN
    SELECT min(week_number) INTO wk FROM public.weekly_questions WHERE trip_id=p_trip AND phase='voting';
    IF wk IS NOT NULL THEN
      SELECT array_agg(idx ORDER BY idx) INTO pair FROM (SELECT DISTINCT idx FROM trip_private.ordered_answers(p_trip, wk) ORDER BY idx LIMIT 2) z;
      FOR b IN SELECT m.user_id FROM public.trip_members m JOIN public.sandbox_bots sb ON sb.user_id=m.user_id WHERE m.trip_id=p_trip LOOP
        BEGIN
          PERFORM trip_private.lab_become(b.user_id);
          IF p_action='tie' AND array_length(pair,1) = 2 THEN
            pick := NULL;
            FOR r IN SELECT q.idx, q.mine FROM public.qotw_answers(p_trip, wk) q WHERE q.idx = ANY(pair) LOOP
              IF NOT r.mine AND (pick IS NULL OR cnt[array_position(pair, r.idx)] < cnt[array_position(pair, pick)]) THEN pick := r.idx; END IF;
            END LOOP;
          ELSE
            SELECT q.idx INTO pick FROM public.qotw_answers(p_trip, wk) q WHERE NOT q.mine ORDER BY random() LIMIT 1;
          END IF;
          IF pick IS NOT NULL THEN
            PERFORM public.vote_weekly_answer(p_trip, wk, pick); ok := ok + 1;
            IF pick = ANY(pair) THEN cnt[array_position(pair, pick)] := cnt[array_position(pair, pick)] + 1; END IF;
          END IF;
        EXCEPTION WHEN others THEN fail := fail + 1; last_err := SQLERRM; END;
      END LOOP;
    END IF;
    k := 0;
    FOR r IN SELECT id, jsonb_array_length(options) n FROM public.live_votes WHERE trip_id=p_trip AND status='open' LOOP
      FOR b IN SELECT m.user_id FROM public.trip_members m JOIN public.sandbox_bots sb ON sb.user_id=m.user_id WHERE m.trip_id=p_trip LOOP
        k := k + 1;
        BEGIN PERFORM trip_private.lab_become(b.user_id);
          PERFORM public.cast_live_vote(r.id, CASE WHEN p_action='tie' THEN k % 2 ELSE floor(random()*greatest(r.n,1))::int END); ok := ok + 1;
        EXCEPTION WHEN others THEN fail := fail + 1; last_err := SQLERRM; END;
      END LOOP;
    END LOOP;
    IF wk IS NULL AND k = 0 THEN RAISE EXCEPTION 'Nothing to vote on — start Question of the Week voting or a live vote first'; END IF;
  ELSIF p_action = 'turn' THEN
    FOR r IN SELECT room, week_number FROM public.game_night_turns WHERE trip_id=p_trip AND active LOOP
      host := coalesce((SELECT tt.host_id FROM public.trip_teams tt WHERE r.room <> 'all' AND tt.id::text = r.room),
                       (SELECT host_id FROM public.game_nights WHERE trip_id=p_trip AND week_number=r.week_number), trip_private.captain_of(p_trip));
      BEGIN PERFORM trip_private.lab_become(host); PERFORM public.next_room_turn(p_trip, r.room); ok := ok + 1;
      EXCEPTION WHEN others THEN fail := fail + 1; last_err := SQLERRM; END;
    END LOOP;
    IF ok + fail = 0 THEN RAISE EXCEPTION 'No card rounds running — start the rounds on game night first'; END IF;
  ELSIF p_action IN ('swap_accept','swap_decline') THEN
    SELECT * INTO s FROM public.host_swaps WHERE trip_id=p_trip AND status='open' ORDER BY created_at DESC LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'No open host swap — tap "Swap my host night" as the host first'; END IF;
    IF p_action = 'swap_decline' THEN
      UPDATE public.host_swaps SET status='cancelled', updated_at=now() WHERE id=s.id; ok := 1;
    ELSE
      v := CASE WHEN s.to_user IS NOT NULL THEN s.to_user ELSE (SELECT m.user_id FROM public.trip_members m JOIN public.sandbox_bots sb ON sb.user_id=m.user_id WHERE m.trip_id=p_trip AND m.user_id<>s.from_user ORDER BY random() LIMIT 1) END;
      IF NOT EXISTS (SELECT 1 FROM public.sandbox_bots WHERE user_id=v) THEN RAISE EXCEPTION 'That swap was offered to a real person, not a bot'; END IF;
      PERFORM trip_private.lab_become(v); PERFORM public.respond_host_swap(s.id, 'accept'); ok := 1;
    END IF;
  ELSIF p_action = 'skip' THEN
    SELECT min(week_number) INTO wk FROM public.game_nights WHERE trip_id=p_trip AND starts_at > now() - interval '3 hours';
    IF wk IS NULL THEN RAISE EXCEPTION 'No upcoming game night'; END IF;
    SELECT m.user_id INTO v FROM public.trip_members m JOIN public.sandbox_bots sb ON sb.user_id=m.user_id WHERE m.trip_id=p_trip AND m.role='player'
      AND NOT EXISTS (SELECT 1 FROM public.game_nights g WHERE g.trip_id=p_trip AND g.week_number=wk AND g.host_id=m.user_id) ORDER BY random() LIMIT 1;
    PERFORM trip_private.lab_become(v); PERFORM public.use_night_pass(p_trip, wk); ok := 1;
  ELSIF p_action = 'noshow' THEN
    SELECT min(week_number) INTO wk FROM public.game_nights WHERE trip_id=p_trip AND starts_at > now() - interval '3 hours' AND NOT EXISTS (SELECT 1 FROM public.game_night_flow f WHERE f.trip_id=p_trip AND f.week_number=game_nights.week_number);
    IF wk IS NULL THEN RAISE EXCEPTION 'No upcoming game night to no-show'; END IF;
    SELECT m.user_id INTO v FROM public.trip_members m JOIN public.sandbox_bots sb ON sb.user_id=m.user_id WHERE m.trip_id=p_trip AND m.role='player' ORDER BY random() LIMIT 1;
    UPDATE public.game_nights SET host_id=v, starts_at = now() - interval '20 minutes' WHERE trip_id=p_trip AND week_number=wk;
    ok := 1;
  ELSIF p_action = 'paid' THEN
    FOR r IN SELECT cs.item_id, cs.user_id, cs.share_cents - cs.paid_cents due FROM public.cost_shares cs JOIN public.sandbox_bots sb ON sb.user_id=cs.user_id WHERE cs.trip_id=p_trip AND cs.paid_cents < cs.share_cents AND cs.reported_at IS NULL LOOP
      BEGIN PERFORM trip_private.lab_become(r.user_id); PERFORM public.report_cost_payment(r.item_id, r.due, (ARRAY['Zelle','Cash App','Venmo'])[1 + floor(random()*3)::int]); ok := ok + 1;
      EXCEPTION WHEN others THEN fail := fail + 1; last_err := SQLERRM; END;
    END LOOP;
    IF ok + fail = 0 THEN RAISE EXCEPTION 'No unpaid bot shares — add a cost in Captain Tools first'; END IF;
  ELSIF p_action = 'join' THEN
    SELECT user_id INTO v FROM public.sandbox_bots WHERE trip_id IS NULL ORDER BY created_at LIMIT 1;
    IF v IS NULL THEN RAISE EXCEPTION 'No spare bot ready'; END IF;
    INSERT INTO public.player_private(user_id,dob) VALUES (v, date '1995-06-15') ON CONFLICT DO NOTHING;
    PERFORM trip_private.lab_become(v); PERFORM public.join_trip(t.join_code);
    PERFORM trip_private.lab_become(me);
    UPDATE public.sandbox_bots SET trip_id=p_trip WHERE user_id=v;
    PERFORM trip_private.lab_card(p_trip, v, (SELECT name FROM public.sandbox_bots WHERE user_id=v), 7);
    ok := 1;
  ELSIF p_action = 'feedback' THEN
    FOR b IN SELECT m.user_id FROM public.trip_members m JOIN public.sandbox_bots sb ON sb.user_id=m.user_id WHERE m.trip_id=p_trip LOOP
      k := k + 1;
      BEGIN PERFORM trip_private.lab_become(b.user_id);
        PERFORM public.submit_trip_feedback(p_trip, false, 6 + (k % 5), (ARRAY['game_nights','qotw','bingo','photo_wall','wrapped','other'])[1 + (k % 6)], NULL, (ARRAY['Best squad ever 💖','Same time next year?','Bangkok forever 🌃'])[1 + (k % 3)]); ok := ok + 1;
      EXCEPTION WHEN others THEN fail := fail + 1; last_err := SQLERRM; END;
    END LOOP;
  ELSE RAISE EXCEPTION 'Unknown bot action'; END IF;
  PERFORM set_config('request.jwt.claims', coalesce(v_claims,''), true);
  PERFORM set_config('request.jwt.claim.sub', coalesce(v_sub,''), true);
  RETURN ok || ' done' || CASE WHEN fail > 0 THEN ' · ' || fail || ' skipped (' || last_err || ')' ELSE '' END;
END $$;


--
-- Name: lab_at_home(text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_at_home(p_pack text, p_length text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_trip uuid; me uuid := auth.uid(); tz text := 'America/Los_Angeles'; today date; v_start date; b record; k int := 0; len int; BEGIN
  PERFORM trip_private.lab_guard(NULL);
  IF p_pack NOT IN ('thailand','mexico','japan') OR p_length NOT IN ('weekend','week','two_weeks') THEN RAISE EXCEPTION 'Pick one of the presets'; END IF;
  IF (SELECT count(*) FROM public.sandbox_bots WHERE trip_id IS NULL) < 3 THEN RAISE EXCEPTION 'Not enough bots ready'; END IF;
  today := (now() AT TIME ZONE tz)::date;
  v_start := CASE WHEN p_length='weekend' THEN today - ((extract(isodow FROM today)::int - 5 + 7) % 7) ELSE today END;
  len := CASE p_length WHEN 'weekend' THEN 3 WHEN 'week' THEN 7 ELSE 14 END;
  IF v_start + len - 1 < today THEN v_start := today + ((5 - extract(isodow FROM today)::int + 7) % 7); END IF;
  INSERT INTO public.trips(name,destination,start_date,end_date,home_timezone,trip_timezone,join_code,is_sandbox,kind,at_home_pack,at_home_length,season_scoring,require_approval,unlocked_at,unlocked_by)
  VALUES ('🧪 At Home · ' || initcap(p_pack) || ' · ' || CASE p_length WHEN 'weekend' THEN 'Weekend' WHEN 'week' THEN '1 week' ELSE '2 weeks' END,
    initcap(p_pack) || ' (at home)', v_start, v_start + len - 1, tz, tz, public.new_trip_code(), true, 'at_home', p_pack, p_length, false, false, now(), me) RETURNING id INTO v_trip;
  INSERT INTO public.sandbox_trips(trip_id,size,days,window_days) VALUES (v_trip,4,len,0);
  INSERT INTO public.trip_members(trip_id,user_id,role,approved_at) VALUES (v_trip,me,'captain',now());
  PERFORM trip_private.lab_card(v_trip, me, 'Founder', 0);
  FOR b IN SELECT user_id, name FROM public.sandbox_bots WHERE trip_id IS NULL ORDER BY created_at, user_id LIMIT 3 LOOP
    k := k + 1;
    UPDATE public.sandbox_bots SET trip_id=v_trip WHERE user_id=b.user_id;
    INSERT INTO public.trip_members(trip_id,user_id,role,approved_at) VALUES (v_trip,b.user_id,'player',now());
    PERFORM trip_private.lab_card(v_trip, b.user_id, b.name, k);
  END LOOP;
  PERFORM trip_private.plan_at_home(v_trip);
  RETURN v_trip;
END $$;


--
-- Name: lab_at_home_bots(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_at_home_bots(p_trip uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a record; b record; n int := 0; BEGIN
  PERFORM trip_private.lab_guard(p_trip);
  FOR a IN SELECT p.id FROM trip_private.at_home_plan(p_trip) p WHERE p.kind='question' AND p.released AND NOT p.revealed LOOP
    FOR b IN SELECT user_id, name FROM public.sandbox_bots WHERE trip_id=p_trip LOOP
      INSERT INTO public.at_home_answers(activity_id,user_id,answer) VALUES (a.id, b.user_id, (ARRAY['Totally the karaoke one 🎤','Mango everything 🥭','A tiny dumpling stand','Me, obviously 😎','Whoever brings snacks'])[1 + floor(random()*5)::int]) ON CONFLICT DO NOTHING;
    END LOOP;
    FOR b IN SELECT user_id FROM public.sandbox_bots WHERE trip_id=p_trip LOOP
      INSERT INTO public.at_home_votes(activity_id,voter_id,target_id)
      SELECT a.id, b.user_id, s.user_id FROM public.at_home_answers s WHERE s.activity_id=a.id AND s.user_id<>b.user_id ORDER BY random() LIMIT 1 ON CONFLICT DO NOTHING;
    END LOOP;
    n := n + 1;
  END LOOP;
  RETURN n || ' question(s) answered and voted by bots';
END $$;


--
-- Name: lab_become(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_become(p_uid uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_uid, 'role', 'authenticated')::text, true);
  PERFORM set_config('request.jwt.claim.sub', p_uid::text, true);
END $$;


--
-- Name: lab_bypass(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_bypass(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT trip_private.is_app_admin() AND EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND is_sandbox) $$;


--
-- Name: lab_card(uuid, uuid, text, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_card(p_trip uuid, p_user uuid, p_name text, p_n integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE pp public.player_profiles;
BEGIN
  IF EXISTS (SELECT 1 FROM public.sandbox_bots WHERE user_id=p_user) THEN
    INSERT INTO public.player_private(user_id,dob) VALUES (p_user, date '1995-06-15') ON CONFLICT DO NOTHING;
  END IF;
  SELECT * INTO pp FROM public.player_profiles WHERE user_id=p_user;
  IF FOUND THEN
    INSERT INTO public.trip_player_cards(trip_id,user_id,real_name,game_name,avatar_style,avatar_seed,hometown,occupation,fun_fact,pronouns)
    VALUES (p_trip,p_user,pp.real_name,pp.game_name,CASE WHEN pp.avatar_style='photo' THEN 'street' ELSE pp.avatar_style END,pp.avatar_seed,pp.hometown,pp.occupation,pp.fun_fact,pp.pronouns) ON CONFLICT DO NOTHING;
  ELSE
    INSERT INTO public.trip_player_cards(trip_id,user_id,real_name,game_name,avatar_style,avatar_seed,hometown,fun_fact)
    VALUES (p_trip,p_user,p_name,p_name,(ARRAY['street','crew','hero'])[1 + (p_n % 3)],p_name || '-' || p_n,'Botville','I am a test bot 🤖') ON CONFLICT DO NOTHING;
  END IF;
END $$;


--
-- Name: lab_create(integer, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_create(p_size integer, p_days integer, p_window integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_trip uuid; me uuid := auth.uid(); today date := (now() AT TIME ZONE 'America/Los_Angeles')::date; b record; k int := 0; v_start date;
BEGIN
  PERFORM trip_private.lab_guard(NULL);
  IF p_size NOT IN (4,10,15,25) OR p_days NOT IN (3,7,21) OR p_window NOT IN (1,10,45,84) THEN RAISE EXCEPTION 'Pick one of the presets'; END IF;
  IF (SELECT count(*) FROM public.sandbox_bots WHERE trip_id IS NULL) < p_size - 1 THEN RAISE EXCEPTION 'Not enough bots ready'; END IF;
  v_start := today + p_window;
  INSERT INTO public.trips(name,destination,start_date,end_date,home_timezone,join_code,is_sandbox)
  VALUES ('🧪 Sandbox · ' || p_size || ' ppl · ' || p_days || 'd','Thailand (sandbox)',v_start,v_start + p_days - 1,'America/Los_Angeles',public.new_trip_code(),true) RETURNING id INTO v_trip;
  UPDATE public.trips SET require_approval=false WHERE id=v_trip;
  INSERT INTO public.sandbox_trips(trip_id,size,days,window_days) VALUES (v_trip,p_size,p_days,p_window);
  INSERT INTO public.trip_members(trip_id,user_id,role) VALUES (v_trip,me,'captain');
  PERFORM trip_private.lab_card(v_trip, me, 'Founder', 0);
  FOR b IN SELECT user_id, name FROM public.sandbox_bots WHERE trip_id IS NULL ORDER BY created_at, user_id LIMIT p_size - 1 LOOP
    k := k + 1;
    UPDATE public.sandbox_bots SET trip_id=v_trip WHERE user_id=b.user_id;
    INSERT INTO public.trip_members(trip_id,user_id,role) VALUES (v_trip,b.user_id,'player');
    PERFORM trip_private.lab_card(v_trip, b.user_id, b.name, k);
  END LOOP;
  PERFORM trip_private.lab_itinerary(v_trip);
  PERFORM trip_private.lab_teams(v_trip);
  BEGIN
    PERFORM trip_private.apply_game_plan(v_trip,'recommended',extract(dow FROM v_start - 1)::int,time '18:00',NULL,1);
  EXCEPTION WHEN others THEN
    INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES (v_trip,1,((v_start - 1) + time '18:00') AT TIME ZONE 'America/Los_Angeles',me) ON CONFLICT DO NOTHING;
    UPDATE public.trips SET game_start = v_start - 1 WHERE id=v_trip;
  END;
  BEGIN PERFORM trip_private.ensure_weekly_questions(v_trip); EXCEPTION WHEN others THEN NULL; END;
  RETURN v_trip;
END $$;


--
-- Name: lab_delete(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_delete(p_trip uuid) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE ids uuid[];
BEGIN
  PERFORM trip_private.lab_guard(p_trip);
  UPDATE public.trips SET ended_at = NULL WHERE id=p_trip;
  SELECT coalesce(array_agg(user_id),'{}') INTO ids FROM public.sandbox_bots WHERE trip_id=p_trip;
  DELETE FROM trip_private.trip_join_grants WHERE trip_id=p_trip;
  DELETE FROM public.sandbox_bots WHERE trip_id=p_trip;
  DELETE FROM public.trips WHERE id=p_trip AND is_sandbox;
  RETURN ids;
END $$;


--
-- Name: lab_extra(uuid, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_extra(p_trip uuid, p_action text, p_arg text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE me uuid := auth.uid(); v uuid; t public.trips; tok text; v_claims text := current_setting('request.jwt.claims', true); v_sub text := current_setting('request.jwt.claim.sub', true);
BEGIN
  PERFORM trip_private.lab_guard(p_trip);
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  IF p_action = 'vibe' THEN
    PERFORM trip_private.set_trip_vibe(p_trip, p_arg); RETURN 'Vibe: ' || p_arg;
  ELSIF p_action IN ('teen','pending') THEN
    SELECT user_id INTO v FROM public.sandbox_bots WHERE trip_id IS NULL ORDER BY created_at LIMIT 1;
    IF v IS NULL THEN RAISE EXCEPTION 'No spare bot ready'; END IF;
    INSERT INTO public.player_private(user_id,dob) VALUES (v, CASE WHEN p_action='teen' THEN current_date - interval '15 years' ELSE date '1995-06-15' END)
      ON CONFLICT (user_id) DO UPDATE SET dob=excluded.dob;
    IF p_action = 'pending' THEN UPDATE public.trips SET require_approval=true WHERE id=p_trip; END IF;
    tok := trip_private.create_trip_invite(p_trip);
    PERFORM trip_private.lab_become(v);
    PERFORM public.join_trip(tok);
    PERFORM set_config('request.jwt.claims', coalesce(v_claims,''), true);
    PERFORM set_config('request.jwt.claim.sub', coalesce(v_sub,''), true);
    UPDATE public.sandbox_bots SET trip_id=p_trip WHERE user_id=v;
    PERFORM trip_private.lab_card(p_trip, v, (SELECT name FROM public.sandbox_bots WHERE user_id=v) || CASE WHEN p_action='teen' THEN ' (teen)' ELSE '' END, 5);
    RETURN CASE WHEN p_action='teen' THEN 'A teen bot joined with an invite and is waiting for approval' ELSE 'A bot is waiting for your approval' END;
  ELSIF p_action = 'noalcohol' THEN
    SELECT m.user_id INTO v FROM public.trip_members m JOIN public.sandbox_bots b ON b.user_id=m.user_id WHERE m.trip_id=p_trip ORDER BY random() LIMIT 1;
    INSERT INTO public.player_private(user_id,dob,no_alcohol) VALUES (v, date '1995-06-15', true) ON CONFLICT (user_id) DO UPDATE SET no_alcohol=true;
    RETURN 'One bot turned on No alcohol (only that bot can see it)';
  ELSIF p_action = 'tz' THEN
    IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = coalesce(nullif(p_arg,''),'Asia/Bangkok')) THEN RAISE EXCEPTION 'Unknown time zone'; END IF;
    UPDATE public.trips SET trip_timezone = coalesce(nullif(p_arg,''),'Asia/Bangkok') WHERE id=p_trip;
    RETURN 'Trip time zone: ' || coalesce(nullif(p_arg,''),'Asia/Bangkok') || ' · trip-day today is ' || trip_private.trip_today(p_trip);
  ELSIF p_action = 'checkin' THEN
    UPDATE public.game_nights SET host_checked_in_at = now() WHERE trip_id=p_trip AND week_number = (SELECT min(week_number) FROM public.game_nights WHERE trip_id=p_trip AND starts_at > now() - interval '3 hours');
    IF NOT FOUND THEN RAISE EXCEPTION 'No upcoming game night'; END IF;
    RETURN 'The host checked in — no -5 for this night';
  ELSIF p_action = 'invite' THEN
    RETURN trip_private.create_trip_invite(p_trip);
  END IF;
  RAISE EXCEPTION 'Unknown Test Lab action';
END $$;


--
-- Name: lab_guard(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_guard(p_trip uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Test Lab is founder-only'; END IF;
  IF p_trip IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND is_sandbox) THEN RAISE EXCEPTION 'Test Lab only works on sandbox trips'; END IF;
END $$;


--
-- Name: lab_itinerary(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_itinerary(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; d date; i int := 0; n int; days jsonb := '[]'::jsonb; fl jsonb; city text; mid int;
BEGIN
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  n := t.end_date - t.start_date + 1; mid := CASE WHEN n >= 7 THEN n/2 ELSE -1 END;
  DELETE FROM public.trip_day_tags WHERE trip_id=p_trip;
  d := t.start_date;
  WHILE d <= t.end_date LOOP
    city := CASE WHEN mid > 0 AND i >= mid THEN 'Phuket' ELSE 'Bangkok' END;
    fl := CASE WHEN i = 0 THEN jsonb_build_array(jsonb_build_object('date',d,'from','LAX','to','BKK'))
               WHEN i = n-1 THEN jsonb_build_array(jsonb_build_object('date',d,'from',CASE WHEN mid>0 THEN 'HKT' ELSE 'BKK' END,'to','LAX'))
               WHEN i = mid THEN jsonb_build_array(jsonb_build_object('date',d,'from','BKK','to','HKT'))
               ELSE '[]'::jsonb END;
    days := days || jsonb_build_object('date',d,'city',city,'note','Sandbox day ' || (i+1),
      'stays', jsonb_build_array(jsonb_build_object('name', city || ' sandbox stay','checkIn',d,'checkOut',d+1)),
      'flights', fl,
      'spots', jsonb_build_array(jsonb_build_object('name', CASE WHEN i%2=0 THEN 'Night market' ELSE 'Rooftop bar' END,'address', city)));
    INSERT INTO public.trip_day_tags(trip_id,day_date,tag) VALUES (p_trip,d,CASE WHEN jsonb_array_length(fl)>0 THEN 'Travel' WHEN i%2=0 THEN 'Explore' ELSE 'Party' END);
    d := d + 1; i := i + 1;
  END LOOP;
  INSERT INTO public.trip_itineraries(trip_id,days) VALUES (p_trip,days) ON CONFLICT (trip_id) DO UPDATE SET days=excluded.days, updated_at=now();
END $$;


--
-- Name: lab_r17(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_r17(p_trip uuid, p_action text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE me uuid := auth.uid(); bot uuid; cap uuid; res text := ''; ok boolean; b record; tm record; claims text; BEGIN
 IF NOT trip_private.is_app_admin() OR NOT EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND is_sandbox) THEN RAISE EXCEPTION 'Test Lab is founder-only'; END IF;
 claims := current_setting('request.jwt.claims', true);
 SELECT m.user_id INTO bot FROM public.trip_members m JOIN public.sandbox_bots s ON s.user_id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' ORDER BY m.joined_at LIMIT 1;
 IF p_action IN ('co_captain_try','takeover_setup') THEN
   UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND role IN ('captain','co_captain');
   UPDATE public.trip_members SET role='captain' WHERE trip_id=p_trip AND user_id=bot;
   UPDATE public.trip_members SET role='co_captain' WHERE trip_id=p_trip AND user_id=me;
 END IF;
 IF p_action='co_captain_try' THEN
   BEGIN PERFORM trip_private.edit_trip(p_trip,'x','y',current_date,current_date+3); res:=res||'dates: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'dates: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.set_trip_vibe(p_trip,'party'); res:=res||'vibe: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'vibe: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.set_trip_timezone(p_trip,'UTC'); res:=res||'time zone: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'time zone: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.create_trip_invite(p_trip); res:=res||'invites: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'invites: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.set_trip_access(p_trip,true,true); res:=res||'approval: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'approval: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.approve_adult_player(p_trip,bot,true); res:=res||'21+: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'21+: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.unlock_trip(p_trip, 4); res:=res||'unlock: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'unlock: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.save_cost_item(p_trip,NULL,'t','other',100,'even','[]'::jsonb,NULL); res:=res||'costs: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'costs: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.manage_trip_member(p_trip,bot,'remove'); res:=res||'remove: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'remove: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   BEGIN PERFORM trip_private.apply_reschedule(p_trip,7,3); res:=res||'plan: ALLOWED ✗; '; EXCEPTION WHEN raise_exception THEN res:=res||'plan: refused ✓; '; WHEN others THEN res:=res||'error '||SQLERRM||'; '; END;
   res := res || 'can run night: ' || CASE WHEN trip_private.is_leader(p_trip) THEN 'yes ✓' ELSE 'no ✗' END;
   RETURN res;
 ELSIF p_action='takeover_setup' THEN
   UPDATE public.profiles SET last_seen_at=now()-interval '15 days' WHERE id=bot;
   RETURN 'A bot is Captain (last seen 15 days ago); you are Co-Captain — open Squad/Trip to see "Take over as Captain".';
 ELSIF p_action='reclaim_setup' THEN
   UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND role IN ('captain','co_captain');
   UPDATE public.trip_members SET role='captain' WHERE trip_id=p_trip AND user_id=bot;
   INSERT INTO public.trip_role_changes(trip_id,from_user,to_user,role,reason,actor) VALUES (p_trip,me,bot,'captain','takeover',bot);
   RETURN 'A bot took over from you 2 minutes ago — you can reclaim for 7 days.';
 ELSIF p_action='teams_pick' THEN
   UPDATE public.trips SET team_mode='pick' WHERE id=p_trip;
   IF NOT EXISTS (SELECT 1 FROM public.trip_teams WHERE trip_id=p_trip) THEN
     INSERT INTO public.trip_teams(trip_id,name,color) VALUES (p_trip,'Mango','orange'),(p_trip,'Neon','blue');
   END IF;
   DELETE FROM public.trip_team_members WHERE trip_id=p_trip;
   FOR b IN SELECT m.user_id FROM public.trip_members m JOIN public.sandbox_bots s ON s.user_id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' ORDER BY m.joined_at LOOP
     PERFORM set_config('request.jwt.claims', json_build_object('sub',b.user_id,'role','authenticated')::text, true);
     ok := false;
     FOR tm IN SELECT id FROM public.trip_teams WHERE trip_id=p_trip ORDER BY name LOOP
       BEGIN PERFORM trip_private.pick_team(p_trip, tm.id); ok := true; EXIT; EXCEPTION WHEN others THEN NULL; END;
     END LOOP;
     IF NOT ok THEN res := res || '1 bot found every team full; '; END IF;
   END LOOP;
   PERFORM set_config('request.jwt.claims', claims, true);
   RETURN res || 'Bots picked teams in order — the first team filled up, the rest overflowed to the next. You pick last.';
 END IF;
 RAISE EXCEPTION 'Unknown lab action';
END $$;


--
-- Name: lab_role(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_role(p_trip uuid, p_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE me uuid := auth.uid(); bot uuid; t public.trips;
BEGIN
  PERFORM trip_private.lab_guard(p_trip);
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  SELECT user_id INTO bot FROM public.trip_members WHERE trip_id=p_trip AND user_id<>me ORDER BY joined_at, user_id LIMIT 1;
  IF p_role = 'captain' THEN
    UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND user_id<>me AND role='captain';
    UPDATE public.trip_members SET role='captain', status='approved' WHERE trip_id=p_trip AND user_id=me;
  ELSIF p_role IN ('player','host','late') THEN
    UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND user_id=me;
    UPDATE public.trip_members SET role='captain' WHERE trip_id=p_trip AND user_id=bot;
    IF p_role = 'host' THEN
      UPDATE public.game_nights SET host_id=me WHERE trip_id=p_trip AND week_number=(SELECT min(week_number) FROM public.game_nights WHERE trip_id=p_trip AND starts_at > now() - interval '3 hours');
    ELSIF p_role = 'late' THEN
      IF NOT EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND starts_at <= now() AND NOT skipped) THEN
        RAISE EXCEPTION 'Time travel to Build-up night first, so game night 1 has been played';
      END IF;
      DELETE FROM public.trip_team_members WHERE trip_id=p_trip AND user_id=me;
      DELETE FROM public.trip_members WHERE trip_id=p_trip AND user_id=me;
      DELETE FROM trip_private.trip_join_grants WHERE trip_id=p_trip AND user_id=me;
      PERFORM trip_private.join_trip(t.join_code);
      PERFORM trip_private.lab_card(p_trip, me, 'Founder', 0);
    END IF;
  ELSE RAISE EXCEPTION 'Unknown role'; END IF;
END $$;


--
-- Name: lab_shift(uuid, text, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_shift(p_trip uuid, p_target text, p_day integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; today date; off interval := interval '0'; v_days int; wk int; n_count int; ts timestamptz; me uuid := auth.uid();
BEGIN
  PERFORM trip_private.lab_guard(p_trip);
  UPDATE public.trips SET ended_at = NULL WHERE id=p_trip;
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  today := (now() AT TIME ZONE t.home_timezone)::date;
  SELECT count(*) INTO n_count FROM public.game_nights WHERE trip_id=p_trip;
  IF p_target = 'before' THEN
    off := ((today + 3) - coalesce(t.game_start, (SELECT min((starts_at AT TIME ZONE t.home_timezone)::date) FROM public.game_nights WHERE trip_id=p_trip), t.start_date - 1)) * interval '1 day';
  ELSIF p_target IN ('kickoff','buildup','takeoff') THEN
    IF n_count = 0 THEN RAISE EXCEPTION 'This sandbox has no game nights'; END IF;
    wk := CASE p_target WHEN 'kickoff' THEN (SELECT min(week_number) FROM public.game_nights WHERE trip_id=p_trip)
                        WHEN 'takeoff' THEN (SELECT max(week_number) FROM public.game_nights WHERE trip_id=p_trip)
                        ELSE (SELECT week_number FROM public.game_nights WHERE trip_id=p_trip ORDER BY week_number OFFSET greatest(0,(n_count-1)/2) LIMIT 1) END;
    SELECT starts_at INTO ts FROM public.game_nights WHERE trip_id=p_trip AND week_number=wk;
    off := (now() - interval '2 minutes') - ts;
  ELSIF p_target = 'qotw' THEN
    SELECT drops_at INTO ts FROM public.weekly_questions WHERE trip_id=p_trip AND week_number < 1000 ORDER BY week_number LIMIT 1;
    IF ts IS NULL THEN SELECT drops_at INTO ts FROM public.weekly_questions WHERE trip_id=p_trip ORDER BY drops_at LIMIT 1; END IF;
    IF ts IS NULL THEN RAISE EXCEPTION 'This sandbox has no Question of the Week (1-night season)'; END IF;
    off := (now() - interval '1 hour') - ts;
  ELSIF p_target IN ('day','rest','surprise') THEN
    off := (today - (t.start_date + greatest(1, least(coalesce(p_day,1), t.end_date - t.start_date + 1)) - 1)) * interval '1 day';
  ELSIF p_target = 'end' THEN off := (today - t.end_date) * interval '1 day';
  ELSIF p_target IN ('feedback','wrapped') THEN off := (today - 1 - t.end_date) * interval '1 day';
  ELSE RAISE EXCEPTION 'Unknown time travel target'; END IF;
  v_days := round(extract(epoch FROM off) / 86400.0)::int;
  UPDATE public.trips SET start_date = start_date + v_days, end_date = end_date + v_days, game_start = game_start + v_days,
    rest_days = ARRAY(SELECT x + v_days FROM unnest(rest_days) x),
    surprise_mode = CASE WHEN p_target='surprise' THEN true WHEN p_target='day' THEN false ELSE surprise_mode END
  WHERE id=p_trip;
  UPDATE public.game_nights SET starts_at = starts_at + off WHERE trip_id=p_trip;
  UPDATE public.weekly_questions SET drops_at = drops_at + off WHERE trip_id=p_trip;
  UPDATE public.season_settings SET crowning_at = crowning_at + off WHERE trip_id=p_trip AND crowning_at IS NOT NULL;
  DELETE FROM public.trip_day_games WHERE trip_id=p_trip;
  DELETE FROM public.bingo_marks WHERE trip_id=p_trip; DELETE FROM public.quest_posts WHERE trip_id=p_trip;
  DELETE FROM public.trivia_answers WHERE trip_id=p_trip; DELETE FROM public.secret_missions WHERE trip_id=p_trip;
  DELETE FROM public.mission_votes WHERE trip_id=p_trip; DELETE FROM public.photo_posts WHERE trip_id=p_trip;
  DELETE FROM public.day_votes WHERE trip_id=p_trip; DELETE FROM public.airport_claims WHERE trip_id=p_trip;
  DELETE FROM public.trip_item_alternatives WHERE trip_id=p_trip;
  PERFORM trip_private.lab_itinerary(p_trip);
  IF p_target = 'rest' THEN
    UPDATE public.trips SET surprise_mode=false, rest_days = array_append(array_remove(rest_days, today), today) WHERE id=p_trip;
  END IF;
  IF p_target IN ('kickoff','buildup','takeoff') THEN
    UPDATE public.game_nights SET host_id = me WHERE trip_id=p_trip AND week_number=wk;
    DELETE FROM public.host_penalties WHERE trip_id=p_trip AND week_number=wk;
  END IF;
  IF p_target = 'feedback' THEN DELETE FROM public.trip_feedback WHERE trip_id=p_trip AND user_id=me; END IF;
  IF p_target = 'wrapped' THEN INSERT INTO public.trip_feedback(trip_id,user_id,skipped) VALUES (p_trip,me,true) ON CONFLICT DO NOTHING; END IF;
  BEGIN PERFORM trip_private.ensure_weekly_questions(p_trip); EXCEPTION WHEN others THEN NULL; END;
  IF p_target IN ('end','feedback','wrapped') THEN UPDATE public.trips SET ended_at = now() WHERE id=p_trip; END IF;
END $$;


--
-- Name: lab_teams(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_teams(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n int; nteams int; ids uuid[] := '{}'; v uuid; m record; k int := 0;
BEGIN
  SELECT count(*) INTO n FROM public.trip_members WHERE trip_id=p_trip;
  DELETE FROM public.trip_teams WHERE trip_id=p_trip;
  IF n < 13 THEN RETURN; END IF;
  nteams := CASE WHEN n > 20 THEN 4 ELSE 3 END;
  FOR k IN 1..nteams LOOP
    INSERT INTO public.trip_teams(trip_id,name,color) VALUES (p_trip,(ARRAY['Team Neon','Team Wave','Team Lime','Team Sun'])[k],(ARRAY['orange','blue','green','yellow'])[k]) RETURNING id INTO v;
    ids := ids || v;
  END LOOP;
  k := 0;
  FOR m IN SELECT user_id FROM public.trip_members WHERE trip_id=p_trip ORDER BY joined_at, user_id LOOP
    INSERT INTO public.trip_team_members(trip_id,user_id,team_id) VALUES (p_trip,m.user_id,ids[1 + (k % nteams)]);
    UPDATE public.trip_teams SET host_id=m.user_id WHERE id=ids[1 + (k % nteams)] AND host_id IS NULL;
    k := k + 1;
  END LOOP;
END $$;


--
-- Name: lab_view(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.lab_view(p_trip uuid, p_view text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE me uuid := auth.uid(); bot uuid; t public.trips; code text;
BEGIN
  PERFORM trip_private.lab_guard(p_trip);
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  DELETE FROM trip_private.lab_views WHERE user_id=me;
  SELECT m.user_id INTO bot FROM public.trip_members m JOIN public.sandbox_bots b ON b.user_id=m.user_id WHERE m.trip_id=p_trip ORDER BY m.joined_at, m.user_id LIMIT 1;
  IF p_view = 'exit' OR p_view = 'captain' THEN
    UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND user_id<>me AND role IN ('captain','co_captain');
    INSERT INTO public.trip_members(trip_id,user_id,role,status) VALUES (p_trip,me,'captain','approved')
      ON CONFLICT (trip_id,user_id) DO UPDATE SET role='captain', status='approved';
    RETURN p_view;
  END IF;
  IF bot IS NULL THEN RAISE EXCEPTION 'This sandbox needs at least one bot'; END IF;
  UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND role IN ('captain','co_captain');
  UPDATE public.trip_members SET role='captain', status='approved' WHERE trip_id=p_trip AND user_id=bot;
  IF p_view = 'co_captain' THEN
    UPDATE public.trip_members SET role='co_captain', status='approved' WHERE trip_id=p_trip AND user_id=me;
  ELSIF p_view = 'player' THEN
    UPDATE public.trip_members SET role='player', status='approved' WHERE trip_id=p_trip AND user_id=me;
  ELSIF p_view = 'teen' THEN
    UPDATE public.trip_members SET role='player', status='approved' WHERE trip_id=p_trip AND user_id=me;
    INSERT INTO trip_private.lab_views(user_id,trip_id,view) VALUES (me,p_trip,'teen');
  ELSIF p_view = 'waiting' THEN
    UPDATE public.trip_members SET role='player', status='pending' WHERE trip_id=p_trip AND user_id=me;
  ELSIF p_view = 'invitee' THEN
    DELETE FROM public.trip_team_members WHERE trip_id=p_trip AND user_id=me;
    DELETE FROM public.trip_members WHERE trip_id=p_trip AND user_id=me;
    INSERT INTO trip_private.lab_views(user_id,trip_id,view) VALUES (me,p_trip,'invitee');
    RETURN t.join_code;
  ELSE RAISE EXCEPTION 'Unknown view'; END IF;
  IF p_view <> 'teen' THEN INSERT INTO trip_private.lab_views(user_id,trip_id,view) VALUES (me,p_trip,p_view); END IF;
  RETURN p_view;
END $$;


--
-- Name: leave_trip(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.leave_trip(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE member_role text; BEGIN
 PERFORM 1 FROM public.trips WHERE id=p_trip FOR UPDATE;
 SELECT role INTO member_role FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid();
 IF member_role IS NULL THEN RAISE EXCEPTION 'Not a member'; END IF;
 IF member_role='captain' AND (SELECT count(*) FROM public.trip_members WHERE trip_id=p_trip AND status='approved')>1 THEN RAISE EXCEPTION 'Pass the crown before leaving'; END IF;
 IF member_role='captain' THEN DELETE FROM public.trips WHERE id=p_trip;
 ELSE
  DELETE FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid();
  INSERT INTO trip_private.trip_removals(trip_id,user_id) VALUES (p_trip,auth.uid()) ON CONFLICT DO NOTHING;
  PERFORM trip_private.log_role(p_trip, auth.uid(), NULL, member_role, 'left trip');
 END IF;
END $$;


--
-- Name: legal_current(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.legal_current(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS(SELECT 1 FROM public.account_consents WHERE user_id=p_user AND legal_version='2026-10-03' AND accepted_at IS NOT NULL) $$;


--
-- Name: legal_dob_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.legal_dob_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF auth.uid() IS NOT NULL THEN
 IF EXISTS (SELECT 1 FROM public.sandbox_bots b WHERE b.user_id = NEW.user_id) THEN RETURN NEW; END IF;
 IF NEW.user_id <> auth.uid() THEN RAISE EXCEPTION 'Not your birthday'; END IF;
 IF NOT trip_private.legal_current(NEW.user_id) THEN RAISE EXCEPTION 'Please agree to the current Terms before continuing'; END IF;
 IF extract(year FROM age(current_date, NEW.dob)) < 13 THEN RAISE EXCEPTION 'Family Mode is coming soon. TripJunkies accounts are for ages 13 and up.'; END IF;
END IF; RETURN NEW; END $$;


--
-- Name: list_beta_codes(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.list_beta_codes() RETURNS TABLE(code text, note text, status text, used_by_name text, created_at timestamp with time zone, expires_at timestamp with time zone, used_at timestamp with time zone, revoked_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
 RETURN QUERY SELECT b.code, b.note,
   CASE WHEN b.used_at IS NOT NULL THEN 'used' WHEN b.revoked_at IS NOT NULL THEN 'revoked' WHEN b.expires_at <= now() THEN 'expired' ELSE 'unused' END,
   CASE WHEN b.used_by IS NULL THEN NULL ELSE coalesce(nullif(pp.game_name,''), nullif(p.display_name,''), 'Player') END,
   b.created_at, b.expires_at, b.used_at, b.revoked_at
 FROM public.beta_codes b LEFT JOIN public.player_profiles pp ON pp.user_id=b.used_by LEFT JOIN public.profiles p ON p.id=b.used_by
 ORDER BY b.created_at DESC LIMIT 500; END $$;


--
-- Name: list_waitlist(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.list_waitlist() RETURNS TABLE(email text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
 RETURN QUERY SELECT w.email, w.created_at FROM public.waitlist w ORDER BY w.created_at; END $$;


--
-- Name: log_ai_call(uuid, text, integer, integer, numeric); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.log_ai_call(p_usage uuid, p_model text, p_in integer, p_out integer, p_cost numeric) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 UPDATE public.ai_usage SET model=left(p_model,80), input_tokens=greatest(0,p_in), output_tokens=greatest(0,p_out), est_cost_usd=greatest(0,p_cost) WHERE id=p_usage AND user_id=auth.uid() AND model IS NULL $$;


--
-- Name: log_cost(uuid, uuid, uuid, text, bigint, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.log_cost(p_trip uuid, p_item uuid, p_target uuid, p_action text, p_amount bigint, p_detail text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO public.cost_log(trip_id,item_id,actor,target_user,action,amount_cents,detail) VALUES (p_trip,p_item,auth.uid(),p_target,p_action,p_amount,left(p_detail,200)) $$;


--
-- Name: log_role(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.log_role(p_trip uuid, p_from uuid, p_to uuid, p_role text, p_reason text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO public.trip_role_changes(trip_id,from_user,to_user,role,reason,actor) VALUES (p_trip,p_from,p_to,p_role,p_reason,auth.uid()) $$;


--
-- Name: manage_trip_member(uuid, uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.manage_trip_member(p_trip uuid, p_user uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE actor_role text; target_role text; old_co uuid; v_age int; is_bot boolean; BEGIN
 PERFORM 1 FROM public.trips WHERE id=p_trip FOR UPDATE;
 SELECT role INTO actor_role FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND status='approved';
 SELECT role INTO target_role FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_user AND status='approved';
 IF actor_role IS DISTINCT FROM 'captain' OR target_role IS NULL OR p_user=auth.uid() THEN RAISE EXCEPTION 'Only the Captain can manage members'; END IF;
 is_bot := EXISTS (SELECT 1 FROM public.sandbox_bots WHERE user_id=p_user);
 v_age := coalesce(trip_private.age_of(p_user),0);
 IF p_action IN ('promote','promote_under21') THEN
  IF target_role='co_captain' THEN RETURN; END IF;
  IF NOT is_bot AND v_age < 18 THEN RAISE EXCEPTION 'Players under 18 can''t be Co-Captain'; END IF;
  IF NOT is_bot AND v_age < 21 AND p_action <> 'promote_under21' THEN RAISE EXCEPTION 'UNDER_21: Confirm first — this player is under 21.'; END IF;
  SELECT user_id INTO old_co FROM public.trip_members WHERE trip_id=p_trip AND role='co_captain' LIMIT 1;
  UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND role='co_captain';
  IF old_co IS NOT NULL THEN PERFORM trip_private.log_role(p_trip, old_co, NULL, 'co_captain', 'replaced'); END IF;
  UPDATE public.trip_members SET role='co_captain' WHERE trip_id=p_trip AND user_id=p_user;
  PERFORM trip_private.log_role(p_trip, old_co, p_user, 'co_captain', CASE WHEN p_action='promote_under21' THEN 'picked by Captain (under 21, confirmed)' ELSE 'picked by Captain' END);
 ELSIF p_action='demote' THEN
  IF target_role<>'co_captain' THEN RETURN; END IF;
  UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND user_id=p_user;
  PERFORM trip_private.log_role(p_trip, p_user, NULL, 'co_captain', 'removed by Captain');
 ELSIF p_action='remove' THEN
  DELETE FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_user; INSERT INTO trip_private.trip_removals(trip_id,user_id) VALUES (p_trip,p_user) ON CONFLICT DO NOTHING;
  PERFORM trip_private.log_role(p_trip, p_user, NULL, target_role, 'removed from trip');
 ELSIF p_action='pass_crown' THEN
  IF v_age < 21 AND NOT is_bot THEN RAISE EXCEPTION 'Captains are 21+. Pick someone 21 or older.'; END IF;
  UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND user_id=auth.uid();
  UPDATE public.trip_members SET role='captain' WHERE trip_id=p_trip AND user_id=p_user;
  PERFORM trip_private.log_role(p_trip, auth.uid(), p_user, 'captain', 'handed off');
 ELSE RAISE EXCEPTION 'Not allowed'; END IF;
END $$;


--
-- Name: mark_bingo(uuid, date, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.mark_bingo(p_trip uuid, p_date date, p_square integer, p_photo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE g public.trip_day_games := trip_private.play_day(p_trip,p_date); BEGIN
 IF g.tag='Travel' OR p_square NOT BETWEEN 0 AND 8 THEN RAISE EXCEPTION 'No bingo today'; END IF;
 IF NOT trip_private.valid_photo(p_trip,p_photo) THEN RAISE EXCEPTION 'Photo upload failed'; END IF;
 INSERT INTO public.bingo_marks(trip_id,day_date,user_id,square,photo_path) VALUES (p_trip,p_date,auth.uid(),p_square,p_photo)
 ON CONFLICT (trip_id,day_date,user_id,square) DO UPDATE SET photo_path=coalesce(public.bingo_marks.photo_path,excluded.photo_path);
END $$;


--
-- Name: member_age_ranges(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.member_age_ranges(p_trip uuid) RETURNS TABLE(user_id uuid, age_range text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Captain only'; END IF;
 RETURN QUERY SELECT m.user_id, trip_private.age_range(coalesce(trip_private.age_of(m.user_id), (SELECT extract(year FROM age(current_date,b.birthday))::int FROM public.player_birthdays b WHERE b.user_id=m.user_id))) FROM public.trip_members m WHERE m.trip_id=p_trip AND m.status='approved'; END $$;


--
-- Name: member_stamp_badges(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.member_stamp_badges(p_trip uuid) RETURNS TABLE(user_id uuid, country text, state text, city text, stamped_on date, trip_name text, squad_count integer, stamp_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RETURN; END IF;
 RETURN QUERY
 SELECT s.user_id, s.country, s.state, s.city, s.stamped_on, s.trip_name, s.squad_count,
   (SELECT count(*) FROM public.passport_stamps x WHERE x.user_id=s.user_id)
 FROM public.passport_stamps s
 JOIN public.trip_members m ON m.user_id=s.user_id AND m.trip_id=p_trip AND m.status='approved'
 WHERE s.trip_id=p_trip AND s.stamped_on=(SELECT max(x.stamped_on) FROM public.passport_stamps x WHERE x.user_id=s.user_id AND x.trip_id=p_trip);
END $$;


--
-- Name: mission_action(uuid, text, integer, uuid, boolean, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.mission_action(p_trip uuid, p_action text, p_slot integer, p_claim uuid, p_layover boolean, p_phase text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_kind text;
  v_t public.trips;
  v_m public.security_missions;
  v_c public.mission_claims;
  v_id uuid;
  v_phase text := coalesce(p_phase,'takeoff');
  v_open boolean;
  v_wopen timestamptz;
  v_wclose timestamptz;
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.trip_members
    WHERE trip_id=p_trip AND user_id=v_uid AND status='approved'
  ) THEN
    RAISE EXCEPTION 'Join this trip first';
  END IF;
  IF v_phase NOT IN ('takeoff','checkin') THEN
    RAISE EXCEPTION 'Unknown mission type';
  END IF;
  SELECT * INTO v_t FROM public.trips WHERE id=p_trip;
  v_open := CASE
    WHEN v_t.kind IN ('at_home','cultural_inspiration') THEN trip_private.trip_today(p_trip) <= v_t.end_date
    ELSE trip_private.trip_today(p_trip) <= v_t.start_date - 1
  END;
  v_wopen := (v_t.start_date + time '00:00') AT TIME ZONE v_t.home_timezone;
  v_wclose := (v_t.start_date + time '23:59') AT TIME ZONE v_t.home_timezone;

  IF p_action = 'reveal' THEN
    IF v_phase='checkin' THEN
      IF NOT v_open THEN RAISE EXCEPTION 'Early Check-In has closed'; END IF;
      IF p_slot IS NULL OR p_slot < 1 OR p_slot > 3 THEN RAISE EXCEPTION 'Pick a task slot'; END IF;
    ELSE
      IF now() < v_wopen THEN RAISE EXCEPTION 'Airport Missions open on departure day'; END IF;
      IF now() > v_wclose THEN RAISE EXCEPTION 'Airport Missions have closed — unrevealed missions are missed'; END IF;
      IF p_slot IS NULL OR p_slot < 1 OR p_slot > 5 THEN RAISE EXCEPTION 'Pick a mission slot'; END IF;
      IF p_slot > 3 AND NOT coalesce(p_layover,false) THEN RAISE EXCEPTION 'Missions 4 and 5 are for layovers'; END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.mission_claims
      WHERE trip_id=p_trip AND user_id=v_uid AND phase=v_phase AND slot=p_slot
    ) THEN
      RAISE EXCEPTION 'Already revealed';
    END IF;
    IF p_slot > 1 AND NOT EXISTS (
      SELECT 1 FROM public.mission_claims
      WHERE trip_id=p_trip AND user_id=v_uid AND phase=v_phase AND slot=p_slot-1 AND status<>'revealed'
    ) THEN
      RAISE EXCEPTION 'Finish the one before this first';
    END IF;
    v_kind := CASE
      WHEN v_phase='checkin' THEN 'checkin'
      WHEN v_t.kind IN ('at_home','cultural_inspiration') THEN 'home'
      ELSE 'trip'
    END;
    SELECT * INTO v_m
    FROM public.security_missions m
    WHERE m.kind=v_kind
      AND (m.trip_id IS NULL OR m.trip_id=p_trip)
      AND NOT EXISTS (
        SELECT 1 FROM public.mission_claims c
        WHERE c.trip_id=p_trip AND c.user_id=v_uid AND c.mission_id=m.id
      )
      AND (
        v_phase<>'checkin'
        OR NOT EXISTS (
          SELECT 1 FROM public.mission_claims c
          WHERE c.trip_id=p_trip AND c.phase='checkin' AND c.mission_id=m.id AND c.user_id<>v_uid
        )
        OR NOT EXISTS (
          SELECT 1 FROM public.security_missions m2
          WHERE m2.kind='checkin'
            AND (m2.trip_id IS NULL OR m2.trip_id=p_trip)
            AND NOT EXISTS (
              SELECT 1 FROM public.mission_claims c2
              WHERE c2.trip_id=p_trip AND c2.phase='checkin' AND c2.mission_id=m2.id
            )
        )
      )
    ORDER BY md5(m.id::text || v_uid::text || p_trip::text)
    LIMIT 1;
    IF v_m.id IS NULL THEN RAISE EXCEPTION 'No more tasks — ask your Captain for more'; END IF;
    INSERT INTO public.mission_claims(trip_id,user_id,slot,mission_id,category,mission_text,points,phase,title,backstory,keywords,revealed_at)
    VALUES (
      p_trip,
      v_uid,
      p_slot,
      v_m.id,
      v_m.category,
      replace(v_m.text,'{destination}',coalesce(nullif(v_t.destination,''),'your destination')),
      CASE WHEN v_phase='checkin' THEN CASE WHEN p_slot=1 THEN 4 ELSE 3 END WHEN p_slot<=3 THEN 2 ELSE 3 END,
      v_phase,
      replace(v_m.title,'{destination}',coalesce(nullif(v_t.destination,''),'your destination')),
      replace(v_m.backstory,'{destination}',coalesce(nullif(v_t.destination,''),'your destination')),
      (SELECT array_agg(replace(k,'{destination}',coalesce(nullif(v_t.destination,''),'your destination'))) FROM unnest(v_m.keywords) k),
      now()
    )
    RETURNING id INTO v_id;
    RETURN v_id;
  END IF;

  SELECT * INTO v_c
  FROM public.mission_claims
  WHERE id=p_claim AND trip_id=p_trip
  FOR UPDATE;
  IF v_c.id IS NULL THEN RAISE EXCEPTION 'Mission not found'; END IF;
  IF p_action IN ('complete','skip') THEN
    IF v_c.user_id <> v_uid THEN RAISE EXCEPTION 'Not your mission'; END IF;
    IF v_c.status <> 'revealed' THEN RAISE EXCEPTION 'Already answered'; END IF;
    IF v_c.phase='checkin' AND p_action='complete' AND NOT v_open THEN RAISE EXCEPTION 'Early Check-In has closed'; END IF;
    IF v_c.phase='takeoff' AND now() > greatest(
      trip_private.trip_season_start_at(p_trip),
      v_c.revealed_at + interval '24 hours'
    ) THEN
      RAISE EXCEPTION 'This mission proof deadline has passed';
    END IF;
    UPDATE public.mission_claims
    SET status = CASE WHEN p_action='complete' THEN 'pending' ELSE 'skipped' END,
        updated_at=now()
    WHERE id=v_c.id;
    RETURN v_c.id;
  ELSIF p_action IN ('verify','decline') THEN
    IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can verify'; END IF;
    IF v_c.status <> 'pending' THEN RAISE EXCEPTION 'Already decided'; END IF;
    IF v_c.user_id = v_uid THEN RAISE EXCEPTION 'Add a Co-Captain to verify your own missions'; END IF;
    UPDATE public.mission_claims
    SET status = CASE WHEN p_action='verify' THEN 'released' ELSE 'declined' END,
        verified_by=v_uid,
        decided_at=now(),
        updated_at=now()
    WHERE id=v_c.id;
    RETURN v_c.id;
  END IF;
  RAISE EXCEPTION 'Unknown action';
END
$$;


--
-- Name: mission_bonus(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.mission_bonus(p_trip uuid) RETURNS TABLE(user_id uuid, points integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT q.user_id, q.points::int FROM trip_private.season_quest_bonus(p_trip,'preflight') q $$;


--
-- Name: mission_window(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.mission_window(p_trip uuid) RETURNS TABLE(opens_at timestamp with time zone, closes_at timestamp with time zone, proof_due_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN
    RAISE EXCEPTION 'Join this trip first';
  END IF;
  RETURN QUERY
  SELECT
    (t.start_date + time '00:00') AT TIME ZONE t.home_timezone,
    (t.start_date + time '23:59') AT TIME ZONE t.home_timezone,
    (
      SELECT min(greatest(
        trip_private.trip_season_start_at(p_trip),
        c.revealed_at + interval '24 hours'
      ))
      FROM public.mission_claims c
      WHERE c.trip_id=p_trip
        AND c.user_id=auth.uid()
        AND c.phase='takeoff'
        AND c.status='revealed'
        AND greatest(
          trip_private.trip_season_start_at(p_trip),
          c.revealed_at + interval '24 hours'
        ) > now()
    )
  FROM public.trips t
  WHERE t.id=p_trip;
END
$$;


--
-- Name: mix_ai_quota(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.mix_ai_quota(p_trip uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_used int; v_remaining int; v_id uuid;
BEGIN PERFORM trip_private.ai_gate('arcade_mix', p_trip, auth.uid());
  IF auth.uid() IS NULL OR NOT trip_private.has_beta_access() OR coalesce(trip_private.age_of(auth.uid()),0) < 18 THEN RAISE EXCEPTION 'Sign in with an eligible account first'; END IF;
  PERFORM 1 FROM public.profiles WHERE id=auth.uid() FOR UPDATE;
  SELECT count(*)::int INTO v_used FROM public.ai_usage WHERE user_id=auth.uid() AND kind='arcade_mix' AND created_at >= date_trunc('day', now());
  IF v_used >= 10 THEN RAISE EXCEPTION 'That is today''s AI limit. Come back tomorrow.'; END IF;
  IF v_used >= 3 THEN
    IF p_trip IS NULL OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'After three free mixes, choose a trip with AI credits.'; END IF;
    IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'LEADER_ONLY: Only the Captain or Co-Captain can spend trip AI credits.'; END IF;
    PERFORM 1 FROM public.trips WHERE id=p_trip FOR UPDATE;
    SELECT remaining INTO v_remaining FROM trip_private.credit_status(p_trip);
    IF coalesce(v_remaining,0) < 1 THEN RAISE EXCEPTION 'OUT_OF_CREDITS: This trip has no AI credits left.'; END IF;
  END IF;
  INSERT INTO public.ai_usage(user_id,trip_id,kind,credits) VALUES(auth.uid(),CASE WHEN v_used >= 3 THEN p_trip ELSE NULL END,'arcade_mix',CASE WHEN v_used >= 3 THEN 1 ELSE 0 END) RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: moderate_inspiration(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.moderate_inspiration(p_card uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  IF p_action NOT IN ('approve','unapprove','hide') THEN RAISE EXCEPTION 'Unknown action'; END IF;
  IF p_action='hide' THEN PERFORM trip_private.hide_inspiration(p_card); RETURN; END IF;
  PERFORM set_config('trip.moderating','on',true);
  UPDATE public.cultural_inspirations SET public_approved_at = CASE WHEN p_action='approve' THEN now() ELSE NULL END WHERE id=p_card AND feature_later AND hidden_at IS NULL;
  PERFORM set_config('trip.moderating','off',true);
  IF FOUND THEN INSERT INTO trip_private.inspiration_moderation(card_id,actor,action) VALUES(p_card,auth.uid(),p_action); END IF;
END $$;


--
-- Name: my_access(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_access() RETURNS TABLE(beta boolean, launch boolean, has_dob boolean, age_range text, no_alcohol boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT trip_private.has_beta_access(), (SELECT public_launch FROM public.app_settings LIMIT 1),
  EXISTS (SELECT 1 FROM public.player_private WHERE user_id=auth.uid()), trip_private.age_range(trip_private.age_of(auth.uid())),
  coalesce((SELECT no_alcohol FROM public.player_private WHERE user_id=auth.uid()), false) $$;


--
-- Name: my_bug_updates(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_bug_updates() RETURNS TABLE(id uuid, page text, status text, founder_note text, status_changed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id, page, status, founder_note, status_changed_at FROM bug_reports
  WHERE user_id = auth.uid() AND status IN ('fixed','need_info') AND update_seen_at IS NULL AND status_changed_at IS NOT NULL
  ORDER BY status_changed_at DESC LIMIT 5;
$$;


--
-- Name: my_lab_view(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_lab_view() RETURNS TABLE(trip_id uuid, view text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT v.trip_id, v.view FROM trip_private.lab_views v WHERE v.user_id=auth.uid() AND trip_private.is_app_admin() $$;


--
-- Name: my_mix_used(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_mix_used() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT count(*)::int FROM public.ai_usage WHERE user_id=auth.uid() AND kind='arcade_mix' AND created_at >= date_trunc('day', now()) $$;


--
-- Name: my_passport(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_passport() RETURNS TABLE(trip_id uuid, stamps integer, crowns integer, junkie boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
SELECT m.trip_id,
  coalesce((SELECT x.game_stamps + x.trip_stamps FROM trip_private.trip_totals(m.trip_id) x WHERE x.user_id=auth.uid()),0),
  (SELECT count(*)::int FROM public.season_champions c WHERE c.trip_id=m.trip_id AND c.user_id=auth.uid()),
  coalesce((SELECT (x.game_stamps+x.trip_stamps) > 0 AND (x.game_stamps+x.trip_stamps) > coalesce((SELECT max(y.game_stamps+y.trip_stamps) FROM trip_private.trip_totals(m.trip_id) y WHERE y.user_id<>auth.uid()),0) FROM trip_private.trip_totals(m.trip_id) x WHERE x.user_id=auth.uid()), false)
FROM public.trip_members m JOIN public.trips tt ON tt.id=m.trip_id AND NOT tt.is_sandbox AND tt.season_scoring WHERE m.user_id=auth.uid() $$;


--
-- Name: my_past_trips(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_past_trips() RETURNS TABLE(trip_id uuid, name text, start_date date, end_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT t.id, t.name, t.start_date, t.end_date FROM trip_private.trip_removals r JOIN public.trips t ON t.id=r.trip_id
  WHERE r.user_id=auth.uid() AND NOT t.is_sandbox AND NOT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=r.trip_id AND m.user_id=auth.uid()) ORDER BY t.start_date DESC $$;


--
-- Name: my_preview_shared(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_preview_shared(p_trip uuid DEFAULT NULL::uuid, p_exp uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN p_trip IS NOT NULL THEN trip_private.is_captain(p_trip) AND EXISTS (SELECT 1 FROM public.experience_previews WHERE trip_id=p_trip)
    ELSE EXISTS (SELECT 1 FROM public.experience_previews p JOIN public.culture_experiences e ON e.id=p.culture_exp_id WHERE p.culture_exp_id=p_exp AND e.creator_id=auth.uid()) END $$;


--
-- Name: my_trip_feedback_done(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_trip_feedback_done(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.trip_feedback WHERE trip_id=p_trip AND user_id=auth.uid()) $$;


--
-- Name: my_unlocked_trips(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_unlocked_trips() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
SELECT count(*)::int FROM public.trips WHERE unlocked_by = auth.uid() AND unlocked_at IS NOT NULL AND NOT is_sandbox AND season_scoring $$;


--
-- Name: my_waiting_trips(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.my_waiting_trips() RETURNS TABLE(trip_id uuid, name text, destination text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT t.id, t.name, t.destination FROM public.trip_members m JOIN public.trips t ON t.id=m.trip_id WHERE m.user_id=auth.uid() AND m.status='pending' $$;


--
-- Name: new_beta_code(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.new_beta_code() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE b bytea := decode(replace(gen_random_uuid()::text,'-',''),'hex'); a text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; c text := ''; i int;
BEGIN FOR i IN 0..7 LOOP c := c || substr(a, get_byte(b,i) % 31 + 1, 1); END LOOP; RETURN c; END $$;


--
-- Name: next_game_turn(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.next_game_turn(p_trip uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT trip_private.next_room_turn(p_trip,'all') $$;


--
-- Name: next_room_turn(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.next_room_turn(p_trip uuid, p_room text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v public.game_night_turns; BEGIN
SELECT * INTO v FROM public.game_night_turns WHERE trip_id=p_trip AND room=coalesce(p_room,'all') FOR UPDATE;
IF NOT FOUND OR NOT v.active THEN RAISE EXCEPTION 'No active round'; END IF;
IF NOT (trip_private.can_run_turns(p_trip,v.week_number) OR EXISTS (SELECT 1 FROM public.trip_teams WHERE trip_id=p_trip AND id::text=v.room AND host_id=auth.uid())) THEN RAISE EXCEPTION 'Host or leader only'; END IF;
IF NOT trip_private.night_open(p_trip,v.week_number) THEN RAISE EXCEPTION 'Turns run only while the game night is live'; END IF;
IF v.turn_index+1 >= cardinality(v.player_order) THEN
  IF v.card_number>=v.cards_per_person THEN UPDATE public.game_night_turns SET active=false WHERE trip_id=p_trip AND room=v.room;
  ELSE UPDATE public.game_night_turns SET turn_index=0,card_number=card_number+1 WHERE trip_id=p_trip AND room=v.room; END IF;
ELSE UPDATE public.game_night_turns SET turn_index=turn_index+1 WHERE trip_id=p_trip AND room=v.room; END IF; END $$;


--
-- Name: night_checkin_tasks(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.night_checkin_tasks(p_trip uuid, p_week integer) RETURNS TABLE(id uuid, user_id uuid, title text, mission_text text, presented_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) OR NOT EXISTS (SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=p_week AND NOT n.skipped AND now() BETWEEN n.starts_at-interval '12 hours' AND n.starts_at+interval '3 hours 30 minutes') THEN RAISE EXCEPTION 'Join this game night first'; END IF; RETURN QUERY SELECT c.id,c.user_id,c.title,c.mission_text,c.presented_at FROM public.mission_claims c WHERE c.trip_id=p_trip AND c.phase='checkin' AND c.status='pending' ORDER BY c.created_at; END $$;


--
-- Name: night_flow_action(uuid, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.night_flow_action(p_trip uuid, p_week integer, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_flow public.game_night_flow; v_first uuid; v_category text; v_order uuid[]; v_cards int; tm record; BEGIN
IF NOT trip_private.can_run_turns(p_trip,p_week) THEN RAISE EXCEPTION 'Only the host or a trip leader can run this night'; END IF;
IF NOT EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week AND game_number IS NOT NULL AND (trip_private.is_leader(p_trip) OR starts_at BETWEEN clock_timestamp()-interval '12 hours' AND clock_timestamp()+interval '12 hours')) THEN RAISE EXCEPTION 'This night can start near its scheduled call time'; END IF;
IF EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week AND (skipped OR clock_timestamp() > starts_at + interval '3 hours 30 minutes')) THEN RAISE EXCEPTION 'This game night is over'; END IF;
IF p_action<>'warmup' AND NOT trip_private.night_open(p_trip,p_week) THEN RAISE EXCEPTION 'This only works while the game night is live'; END IF;
UPDATE public.game_nights SET host_checked_in_at=coalesce(host_checked_in_at,now()) WHERE trip_id=p_trip AND week_number=p_week AND host_id=auth.uid();
IF p_week > 1 AND NOT trip_private.is_unlocked(p_trip) THEN RAISE EXCEPTION 'Your Captain can unlock the full trip'; END IF;
IF p_action='warmup' THEN
 PERFORM trip_private.night_no_show_check(p_trip,p_week);
 IF EXISTS (SELECT 1 FROM public.game_night_flow WHERE trip_id=p_trip AND week_number=p_week AND first_player IS NOT NULL) THEN RAISE EXCEPTION 'Warm-up already spun'; END IF;
 SELECT user_id INTO v_first FROM public.trip_members WHERE status='approved' AND trip_id=p_trip ORDER BY random() LIMIT 1;
 v_category := (ARRAY['travel','food','childhood','deep']::text[])[(p_week-1) % 4+1];
 IF (SELECT enabled FROM public.trip_adult_settings WHERE trip_id=p_trip) AND NOT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.status='approved' AND m.trip_id=p_trip AND NOT trip_private.is_approved_adult(p_trip,m.user_id)) AND random()<0.2 THEN v_category:='spicy'; END IF;
 INSERT INTO public.game_night_flow(trip_id,week_number,phase,first_player,category) VALUES(p_trip,p_week,'warmup',v_first,v_category) ON CONFLICT(trip_id,week_number) DO UPDATE SET first_player=excluded.first_player,category=excluded.category;
ELSIF p_action='cards' THEN
 SELECT * INTO v_flow FROM public.game_night_flow WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
 IF NOT FOUND OR v_flow.phase<>'warmup' OR v_flow.first_player IS NULL THEN RAISE EXCEPTION 'Spin the warm-up first'; END IF;
 v_cards := trip_private.room_rounds(p_trip);
 DELETE FROM public.game_night_turns WHERE trip_id=p_trip;
 IF (SELECT count(*) FROM public.trip_members WHERE status='approved' AND trip_id=p_trip) > 12 AND EXISTS (SELECT 1 FROM public.trip_teams WHERE trip_id=p_trip) THEN
   FOR tm IN SELECT id FROM public.trip_teams WHERE trip_id=p_trip LOOP
     SELECT array_agg(x.user_id ORDER BY CASE WHEN x.user_id=v_flow.first_player THEN 0 ELSE 1 END, m.joined_at, x.user_id) INTO v_order FROM public.trip_team_members x JOIN public.trip_members m ON m.trip_id=x.trip_id AND m.user_id=x.user_id AND m.status='approved' WHERE x.trip_id=p_trip AND x.team_id=tm.id;
     IF coalesce(cardinality(v_order),0) > 0 THEN INSERT INTO public.game_night_turns(trip_id,room,week_number,cards_per_person,player_order,turn_index,card_number,active) VALUES(p_trip,tm.id::text,p_week,v_cards,v_order,0,1,true); END IF;
   END LOOP;
   SELECT array_agg(m.user_id ORDER BY m.joined_at) INTO v_order FROM public.trip_members m WHERE m.status='approved' AND m.trip_id=p_trip AND NOT EXISTS (SELECT 1 FROM public.trip_team_members x WHERE x.trip_id=p_trip AND x.user_id=m.user_id);
   IF coalesce(cardinality(v_order),0) > 0 THEN INSERT INTO public.game_night_turns(trip_id,room,week_number,cards_per_person,player_order,turn_index,card_number,active) VALUES(p_trip,'all',p_week,v_cards,v_order,0,1,true); END IF;
 ELSE
   SELECT array_agg(user_id ORDER BY CASE WHEN user_id=v_flow.first_player THEN 0 ELSE 1 END,joined_at,user_id) INTO v_order FROM public.trip_members WHERE status='approved' AND trip_id=p_trip;
   INSERT INTO public.game_night_turns(trip_id,room,week_number,cards_per_person,player_order,turn_index,card_number,active) VALUES(p_trip,'all',p_week,v_cards,v_order,0,1,true);
 END IF;
 UPDATE public.game_night_flow SET phase='cards',rounds_target=v_cards WHERE trip_id=p_trip AND week_number=p_week;
ELSIF p_action='add_round' THEN
 SELECT * INTO v_flow FROM public.game_night_flow WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
 IF NOT FOUND OR v_flow.phase<>'cards' OR v_flow.rounds_target>=5 THEN RAISE EXCEPTION 'No more rounds can be added'; END IF;
 UPDATE public.game_night_turns SET cards_per_person=cards_per_person+1,active=true WHERE trip_id=p_trip AND week_number=p_week;
 UPDATE public.game_night_flow SET rounds_target=rounds_target+1 WHERE trip_id=p_trip AND week_number=p_week;
ELSIF p_action='quests' THEN
  IF NOT trip_private.night_open(p_trip,p_week) THEN RAISE EXCEPTION 'Present quests while the night is live'; END IF;
  UPDATE public.game_night_flow SET quest_step_at=coalesce(quest_step_at,clock_timestamp()) WHERE trip_id=p_trip AND week_number=p_week AND phase='finale';
  IF NOT FOUND THEN RAISE EXCEPTION 'Finish the game first'; END IF;
ELSIF p_action='finale' THEN
 UPDATE public.game_night_flow SET phase='finale' WHERE trip_id=p_trip AND week_number=p_week AND phase='cards';
 IF NOT FOUND THEN RAISE EXCEPTION 'Start the card rounds first'; END IF;
 UPDATE public.game_night_turns SET active=false WHERE trip_id=p_trip AND week_number=p_week;
ELSE RAISE EXCEPTION 'Unknown game-night action'; END IF;
END $$;


--
-- Name: night_format_action(uuid, integer, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.night_format_action(p_trip uuid, p_week integer, p_action text, p_value text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n public.game_nights; f public.game_night_flow; picked public.game_format_prompts; v_count integer; v_actor uuid; v_theme text; v_id bigint; v_card public.game_cards; v_vote uuid; v_category text; v_next public.game_nights;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND status='approved') THEN RAISE EXCEPTION 'Approved trip members only'; END IF;
 SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
 IF NOT FOUND OR n.skipped OR NOT trip_private.night_open(p_trip,p_week) THEN RAISE EXCEPTION 'This game night is not open'; END IF;
 SELECT * INTO f FROM public.game_night_flow WHERE trip_id=p_trip AND week_number=p_week;
 IF p_action='react' THEN
  IF f.phase<>'cards' OR p_value NOT IN ('❤️','😂','🔥','👏','✨') THEN RAISE EXCEPTION 'Card reactions open during cards only'; END IF;
  SELECT draw_card_id INTO v_id FROM public.trip_play_state WHERE trip_id=p_trip;
  IF v_id IS NULL THEN RAISE EXCEPTION 'Draw a card first'; END IF;
  INSERT INTO public.game_night_reactions(trip_id,week_number,card_id,user_id,emoji) VALUES(p_trip,p_week,v_id,auth.uid(),p_value) ON CONFLICT(trip_id,week_number,card_id,user_id) DO UPDATE SET emoji=excluded.emoji;
  RETURN jsonb_build_object('ok',true);
 ELSIF p_action='skip' THEN
  IF f.phase<>'cards' THEN RAISE EXCEPTION 'Skips open during cards only'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.game_night_turns WHERE trip_id=p_trip AND week_number=p_week AND active AND player_order[turn_index+1]=auth.uid()) THEN RAISE EXCEPTION 'Wait for your turn'; END IF;
  SELECT c.* INTO v_card FROM public.trip_play_state s JOIN public.game_cards c ON c.id=s.draw_card_id WHERE s.trip_id=p_trip FOR UPDATE OF s;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draw a card first'; END IF;
  v_category := coalesce(f.category,'travel');
  IF v_category='spicy' AND NOT trip_private.is_approved_adult(p_trip,auth.uid()) THEN RAISE EXCEPTION '21+ approval required'; END IF;
  INSERT INTO public.game_night_card_skips(trip_id,week_number,user_id,used) VALUES(p_trip,p_week,auth.uid(),1) ON CONFLICT(trip_id,week_number,user_id) DO UPDATE SET used=public.game_night_card_skips.used+1 WHERE public.game_night_card_skips.used<2 RETURNING used INTO v_count;
  IF v_count IS NULL THEN RAISE EXCEPTION 'You have used both skips tonight'; END IF;
  SELECT c.id INTO v_id FROM public.game_cards c WHERE ((c.category=v_category AND c.game_number=n.game_number AND (c.trip_id IS NULL OR c.trip_id=p_trip)) OR (c.game_number IS NULL AND c.trip_id IS NULL AND c.category IN (v_category, CASE WHEN v_category='spicy' THEN 'spicy' ELSE 'get-to-know' END))) AND c.id<>v_card.id ORDER BY EXISTS (SELECT 1 FROM public.content_seen s WHERE s.trip_id=p_trip AND s.kind='card' AND s.item_key=c.id::text), random() LIMIT 1;
  IF v_id IS NULL THEN RAISE EXCEPTION 'No replacement cards available'; END IF;
  INSERT INTO public.content_seen(trip_id,kind,item_key) VALUES(p_trip,'card',v_id::text) ON CONFLICT DO NOTHING;
  UPDATE public.trip_play_state SET draw_card_id=v_id,draw_category=v_category,draw_at=clock_timestamp() WHERE trip_id=p_trip;
  RETURN jsonb_build_object('used',v_count,'card_id',v_id);
 ELSIF p_action='warmup' THEN
  IF f.first_player IS NULL THEN RAISE EXCEPTION 'Spin the warm-up first'; END IF;
  SELECT * INTO picked FROM public.game_format_prompts WHERE format='wheel' ORDER BY EXISTS (SELECT 1 FROM public.game_night_moments m WHERE m.trip_id=p_trip AND m.prompt_id=game_format_prompts.id), md5(p_trip::text||p_week::text||id::text) LIMIT 1;
  INSERT INTO public.game_night_moments(trip_id,week_number,stage,prompt_id,actor_id) VALUES(p_trip,p_week,'warmup',picked.id,f.first_player) ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('ok',true);
 ELSIF p_action IN ('showdown','final') THEN
  IF NOT (trip_private.is_leader(p_trip) OR n.host_id=auth.uid()) THEN RAISE EXCEPTION 'Host or leader only'; END IF;
  IF f.phase<>'finale' THEN RAISE EXCEPTION 'Finish the cards first'; END IF;
  IF p_action='showdown' THEN
    SELECT count(*) INTO v_count FROM public.game_night_moments WHERE trip_id=p_trip AND week_number=p_week AND stage='showdown';
    IF v_count>=2 THEN RAISE EXCEPTION 'Both showdowns are already open'; END IF;
    IF v_count>0 AND EXISTS (SELECT 1 FROM public.live_votes WHERE trip_id=p_trip AND week_number=p_week AND status='open') THEN RAISE EXCEPTION 'Reveal the current vote first'; END IF;
    SELECT * INTO picked FROM public.game_format_prompts WHERE format='vote' ORDER BY EXISTS (SELECT 1 FROM public.game_night_moments m WHERE m.trip_id=p_trip AND m.prompt_id=game_format_prompts.id), md5(p_trip::text||p_week::text||v_count::text||id::text) LIMIT 1;
    v_vote := trip_private.post_live_vote(p_trip,'most_likely',picked.prompt,'[]'::jsonb,p_week);
    INSERT INTO public.game_night_moments(trip_id,week_number,stage,round_number,prompt_id) VALUES(p_trip,p_week,'showdown',v_count+1,picked.id);
    RETURN jsonb_build_object('round',v_count+1,'vote_id',v_vote);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.game_night_moments WHERE trip_id=p_trip AND week_number=p_week AND stage='showdown' AND round_number=2) THEN RAISE EXCEPTION 'Play both showdowns first'; END IF;
  IF EXISTS (SELECT 1 FROM public.live_votes WHERE trip_id=p_trip AND week_number=p_week AND status='open') THEN RAISE EXCEPTION 'Reveal the showdown votes first'; END IF;
  SELECT * INTO v_next FROM public.game_nights WHERE trip_id=p_trip AND starts_at>n.starts_at AND NOT skipped ORDER BY starts_at LIMIT 1;
  v_actor := v_next.host_id;
  SELECT x INTO v_theme FROM unnest(ARRAY['Wear your funniest shirt','Bring a snack from your culture','Dress like the destination','Bring a baby photo you are comfortable sharing','Wear your brightest color','Show your favorite travel keepsake','Share a favorite color','Bring an object with a story','Wear a pattern you love','Show a doodle you made','Share your favorite snack wrapper','Bring a postcard or drawing','Wear your comfiest socks','Show a favorite book cover','Bring an object in the trip colors','Share a made-up team cheer','Bring your favorite mug','Show an imaginary souvenir sketch','Wear your brightest accessory','Bring an everyday object with a funny name','Draw a mascot for the squad','Show a photo you took and are happy to share','Bring an item that makes you smile','Wear a color inspired by the destination','Share a three-word story','Bring a drawing of a view you love']) AS x WHERE NOT EXISTS (SELECT 1 FROM public.game_night_moments m WHERE m.trip_id=p_trip AND m.stage='final' AND m.theme=x) ORDER BY random() LIMIT 1;
  IF v_theme IS NULL THEN v_theme := 'Bring an object with a story'; END IF; INSERT INTO public.game_night_moments(trip_id,week_number,stage,actor_id,theme) VALUES(p_trip,p_week,'final',v_actor,v_theme) ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('host',v_actor,'theme',v_theme);
 ELSE RAISE EXCEPTION 'Unknown game action'; END IF;
END $$;


--
-- Name: night_live(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.night_live(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped AND starts_at BETWEEN now()-interval '4 hours' AND now()+interval '2 hours') $$;


--
-- Name: night_no_show_check(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.night_no_show_check(p_trip uuid, p_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n public.game_nights; BEGIN
 SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week;
 IF n.host_id IS NULL OR n.host_id=auth.uid() OR n.host_checked_in_at IS NOT NULL OR n.skipped THEN RETURN; END IF;
 IF EXISTS (SELECT 1 FROM public.skip_passes WHERE trip_id=p_trip AND user_id=n.host_id AND kind='captain' AND ref=p_week::text) THEN RETURN; END IF;
 IF clock_timestamp() < n.starts_at + interval '15 minutes' THEN
   IF trip_private.is_leader(p_trip) THEN RETURN; END IF;
   RAISE EXCEPTION 'Give the host until 15 minutes after start, then you can take over';
 END IF;
 INSERT INTO public.host_penalties(trip_id,week_number,user_id,stamps) VALUES(p_trip,p_week,n.host_id, CASE WHEN n.host_id=trip_private.captain_of(p_trip) THEN 8 ELSE 5 END) ON CONFLICT DO NOTHING;
END $$;


--
-- Name: night_open(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.night_open(p_trip uuid, p_week integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT trip_private.lab_bypass(p_trip) OR EXISTS (SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=p_week AND NOT n.skipped
   AND clock_timestamp() <= n.starts_at + interval '3 hours 30 minutes'
   AND (clock_timestamp() >= n.starts_at - interval '15 minutes'
        OR EXISTS (SELECT 1 FROM public.game_night_flow f WHERE f.trip_id=p_trip AND f.week_number=p_week AND f.first_player IS NOT NULL))) $$;


--
-- Name: on_member_changed(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.on_member_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF EXISTS (SELECT 1 FROM public.trips WHERE id=coalesce(NEW.trip_id, OLD.trip_id)) THEN PERFORM trip_private.resplit_even_costs(coalesce(NEW.trip_id, OLD.trip_id)); END IF;
 RETURN coalesce(NEW, OLD); END $$;


--
-- Name: on_member_joined(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.on_member_joined() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.resplit_even_costs(NEW.trip_id); RETURN NEW; END $$;


--
-- Name: order_quote(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.order_quote(p_trip uuid) RETURNS TABLE(kind text, label text, tier text, headcount integer, list_cents integer, discount_cents integer, discount_source text, amount_due_cents integer, paid boolean, upgrade_cents integer, order_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; ret int := 0; code int := 0; pr record; rp record; o public.orders; BEGIN
  IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can check out'; END IF;
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  SELECT count(*)::int INTO headcount FROM public.trip_members m WHERE m.trip_id=p_trip AND m.status='approved';
  SELECT * INTO o FROM public.orders x WHERE x.trip_id=p_trip AND x.kind IN ('at_home','trip_unlock') ORDER BY x.created_at LIMIT 1;
  SELECT * INTO rp FROM trip_private.room_pricing(p_trip);
  IF o.id IS NOT NULL THEN
    kind:=o.kind; label:=o.label; tier:=o.tier; list_cents:=o.list_cents; discount_cents:=o.discount_cents; discount_source:=o.discount_source; amount_due_cents:=o.amount_due_cents; order_id:=o.id; paid:=true;
    upgrade_cents := CASE WHEN rp.is_new THEN rp.addon_cents WHEN t.kind='at_home' AND EXISTS (SELECT 1 FROM public.orders x WHERE x.trip_id=p_trip AND x.kind='tier_upgrade') THEN 300 ELSE 0 END;
    RETURN NEXT; RETURN;
  END IF;
  IF rp.is_new THEN
    kind := CASE WHEN t.kind='at_home' THEN 'at_home' ELSE 'trip_unlock' END;
    tier := rp.base_key; list_cents := rp.base_cents + rp.addon_cents;
    label := t.name || CASE WHEN rp.base_key LIKE 'trip_%' THEN ' · ' || rp.days || '-day trip' ELSE '' END;
    upgrade_cents := rp.addon_cents;
    IF t.kind='at_home' AND EXISTS (SELECT 1 FROM public.orders x WHERE x.captain_id=auth.uid() AND x.kind='at_home' AND x.trip_id IS DISTINCT FROM p_trip) THEN ret := trip_private.price('legacy_home_returning'); END IF;
  ELSIF t.kind='at_home' THEN
    kind := 'at_home'; tier := CASE WHEN headcount <= 6 THEN '1-6' ELSE '7-12' END; list_cents := trip_private.price(CASE WHEN headcount <= 6 THEN 'legacy_home_6' ELSE 'legacy_home_12' END);
    label := (SELECT name FROM public.at_home_packs WHERE key=t.at_home_pack) || ' at Home · ' || CASE t.at_home_length WHEN 'weekend' THEN 'Weekend' WHEN 'week' THEN '1 week' ELSE '2 weeks' END;
    IF EXISTS (SELECT 1 FROM public.orders x WHERE x.captain_id=auth.uid() AND x.kind='at_home' AND x.trip_id IS DISTINCT FROM p_trip) THEN ret := trip_private.price('legacy_home_returning'); END IF;
    upgrade_cents := CASE WHEN EXISTS (SELECT 1 FROM public.orders x WHERE x.trip_id=p_trip AND x.kind='tier_upgrade') THEN 300 ELSE 0 END;
  ELSE
    SELECT * INTO pr FROM trip_private.trip_price(p_trip, NULL);
    kind := 'trip_unlock'; tier := CASE WHEN pr.addon_cents > 0 THEN 'big_group' ELSE 'base' END; list_cents := pr.total_cents; label := t.name || ' · ' || pr.days || '-day trip';
    upgrade_cents := 0;
  END IF;
  SELECT r.cents INTO code FROM public.reward_codes r WHERE r.user_id=auth.uid() AND r.used_at IS NULL AND r.expires_at > now() ORDER BY r.created_at LIMIT 1;
  code := coalesce(code, 0);
  IF code > 0 AND code >= ret THEN discount_cents := least(code, list_cents); discount_source := 'captain_code';
  ELSIF ret > 0 THEN discount_cents := least(ret, list_cents); discount_source := 'returning';
  ELSE discount_cents := 0; discount_source := NULL; END IF;
  amount_due_cents := list_cents - discount_cents;
  order_id := NULL; paid := t.unlocked_at IS NOT NULL;
  RETURN NEXT;
END $$;


--
-- Name: ordered_answers(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ordered_answers(p_trip uuid, p_week integer) RETURNS TABLE(idx integer, user_id uuid, answer text, emoji text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT (row_number() OVER (ORDER BY md5(q.shuffle_salt::text || a.user_id::text)) - 1)::int, a.user_id, a.answer, a.emoji
 FROM public.weekly_answers a JOIN public.weekly_questions q ON q.trip_id=a.trip_id AND q.week_number=a.week_number
 WHERE a.trip_id=p_trip AND a.week_number=p_week $$;


--
-- Name: passport_collection(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.passport_collection() RETURNS TABLE(trip_id uuid, kind text, country text, state text, city text, stamped_on date, trip_name text, destination text, start_date date, squad_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 PERFORM trip_private.sync_passport(auth.uid());
 RETURN QUERY SELECT s.trip_id,s.kind,s.country,s.state,s.city,s.stamped_on,t.name,t.destination,t.start_date,(SELECT count(*)::integer FROM public.trip_members m WHERE m.trip_id=s.trip_id AND m.status='approved') FROM public.passport_stamps s JOIN public.trips t ON t.id=s.trip_id WHERE s.user_id=auth.uid() ORDER BY s.stamped_on DESC;
END $$;


--
-- Name: pending_count(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.pending_count(p_trip uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_leader(p_trip) THEN RETURN 0; END IF;
 RETURN (SELECT count(*) FROM public.trip_members WHERE trip_id=p_trip AND status='pending'); END $$;


--
-- Name: pending_members(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.pending_members(p_trip uuid) RETURNS TABLE(user_id uuid, name text, avatar_style text, avatar_seed text, age_range text, joined_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 RETURN QUERY SELECT m.user_id, coalesce(c.game_name, p.game_name, 'New traveler'), coalesce(c.avatar_style, p.avatar_style, 'street'), coalesce(c.avatar_seed, p.avatar_seed, m.user_id::text), trip_private.age_range(trip_private.age_of(m.user_id)), m.joined_at
  FROM public.trip_members m LEFT JOIN public.trip_player_cards c ON c.trip_id=m.trip_id AND c.user_id=m.user_id LEFT JOIN public.player_profiles p ON p.user_id=m.user_id
  WHERE m.trip_id=p_trip AND m.status='pending' ORDER BY m.joined_at; END $$;


--
-- Name: photo_quota_ok(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.photo_quota_ok(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $$
 SELECT (SELECT count(*) FROM storage.objects o WHERE o.bucket_id='trip-photos' AND o.owner_id=auth.uid()::text
   AND split_part(o.name,'/',1)=split_part(p_name,'/',1) AND o.created_at >= date_trunc('day', now())) < 15 $$;


--
-- Name: pick_at_home_song(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.pick_at_home_song(p_activity uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE a public.at_home_activities; BEGIN
 a:=trip_private.at_home_released(p_activity);
 IF a.kind NOT IN ('call_night','cook','build','passport') THEN RAISE EXCEPTION 'Pick a disc on an activity day'; END IF;
 IF NOT (trip_private.is_leader(a.trip_id) OR EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=a.trip_id AND host_id=auth.uid() AND starts_at::date=a.day_date)) THEN RAISE EXCEPTION 'Captain or host only'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.song_discs WHERE trip_id=a.trip_id AND user_id=p_user) THEN RAISE EXCEPTION 'That disc is no longer here'; END IF;
 INSERT INTO public.at_home_song_winners(activity_id,user_id,picked_by) VALUES(p_activity,p_user,auth.uid()) ON CONFLICT(activity_id) DO UPDATE SET user_id=excluded.user_id,picked_by=excluded.picked_by,updated_at=now();
END $$;


--
-- Name: pick_night_game(uuid, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.pick_night_game(p_trip uuid, p_week integer, p_game integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_night public.game_nights; v_used integer[];
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF;
 IF NOT trip_private.trip_open(p_trip) THEN RAISE EXCEPTION 'This trip has ended'; END IF;
 PERFORM trip_private.require_feature(p_trip,'spin_wheel');
 SELECT * INTO v_night FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
 IF NOT FOUND OR v_night.skipped OR v_night.starts_at <= now() OR v_night.game_locked OR (v_night.game_number IS NOT NULL AND v_night.game_revealed) THEN RAISE EXCEPTION 'Choose an upcoming, unassigned or unrevealed night'; END IF;
 IF NOT (trip_private.is_leader(p_trip) OR v_night.host_id=auth.uid()) THEN RAISE EXCEPTION 'Only a leader or this night''s host can choose'; END IF;
 IF p_game IS NULL OR NOT EXISTS(SELECT 1 FROM public.game_catalog WHERE number=p_game) THEN RAISE EXCEPTION 'Choose a catalog game'; END IF;
 IF p_game IS NOT DISTINCT FROM v_night.game_number THEN RETURN; END IF;
 INSERT INTO public.trip_play_state(trip_id) VALUES(p_trip) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.trip_play_state WHERE trip_id=p_trip FOR UPDATE;
 SELECT coalesce(array_agg(DISTINCT game_number),'{}'::integer[]) INTO v_used FROM public.game_nights WHERE trip_id=p_trip AND week_number<>p_week AND game_number IS NOT NULL;
 IF p_game=ANY(v_used) AND EXISTS(SELECT 1 FROM public.game_catalog WHERE NOT(number=ANY(v_used))) THEN RAISE EXCEPTION 'Pick a game this Trip has not played yet'; END IF;
 UPDATE public.game_nights SET game_number=p_game WHERE trip_id=p_trip AND week_number=p_week;
 UPDATE public.trip_play_state SET used_games=array_append(v_used,p_game), spin_game=CASE WHEN spin_week=p_week THEN p_game ELSE spin_game END WHERE trip_id=p_trip;
 INSERT INTO public.game_pick_log(trip_id,week_number,game_number,actor,method) VALUES(p_trip,p_week,p_game,auth.uid(),'picked');
END $$;


--
-- Name: pick_team(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.pick_team(p_trip uuid, p_team uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t public.trips; cap int; taken int; BEGIN PERFORM trip_private.require_feature(p_trip, 'teams');
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Not a trip member'; END IF;
 IF t.team_mode<>'pick' AND NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Your Captain is assigning teams'; END IF;
 IF EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped AND starts_at <= now()) AND NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Teams are locked now that game nights have started — ask your Captain'; END IF;
 PERFORM 1 FROM public.trip_teams WHERE id=p_team AND trip_id=p_trip FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'That team no longer exists'; END IF;
 cap := trip_private.team_capacity(p_team);
 SELECT count(*) INTO taken FROM public.trip_team_members WHERE team_id=p_team AND user_id<>auth.uid();
 IF taken >= cap THEN RAISE EXCEPTION 'That team is full'; END IF;
 INSERT INTO public.trip_team_members(trip_id,user_id,team_id) VALUES (p_trip,auth.uid(),p_team) ON CONFLICT (trip_id,user_id) DO UPDATE SET team_id=EXCLUDED.team_id;
END $$;


--
-- Name: pick_weekly_prompt(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.pick_weekly_prompt(p_trip uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v text; v_spicy_ok boolean; BEGIN
v_spicy_ok := (SELECT vibe FROM public.trips WHERE id=p_trip)='party'
  AND NOT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.status='approved' AND coalesce(trip_private.age_of(m.user_id),0) < 21);
SELECT x.prompt INTO v FROM (
  SELECT p.prompt FROM public.weekly_question_pool p WHERE NOT p.spicy OR v_spicy_ok
  UNION SELECT cv.text FROM public.content_variants cv WHERE cv.trip_id=p_trip AND cv.kind='qotw'
) x
ORDER BY NOT trip_private.in_slice(p_trip, md5(x.prompt)), (EXISTS(SELECT 1 FROM public.content_seen s WHERE s.trip_id=p_trip AND s.kind='qotw' AND s.item_key=md5(x.prompt))
          OR x.prompt IN (SELECT prompt FROM public.weekly_questions WHERE trip_id=p_trip)),
         EXISTS(SELECT 1 FROM public.content_seen s WHERE s.trip_id IN (SELECT trip_private.captain_trip_ids(p_trip)) AND s.kind='qotw' AND s.item_key=md5(x.prompt)),
         random() LIMIT 1;
IF v IS NOT NULL THEN INSERT INTO public.content_seen(trip_id,kind,item_key) VALUES (p_trip,'qotw',md5(v)) ON CONFLICT DO NOTHING; END IF;
RETURN v; END $$;


--
-- Name: plan_at_home(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.plan_at_home(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; len int; d int; v_day date; dow int; wk int; drops int[] := ARRAY[0,0,0]; last_d int := 0; cyc int := 0; cooks int := 0; v_cap int; total int; drop_max int; v_cat text;
  kinds text[] := ARRAY['question','phrase','culture','snack','starter']; BEGIN
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  DELETE FROM public.at_home_activities WHERE trip_id=p_trip;
  len := t.end_date - t.start_date + 1;
  PERFORM trip_private.at_home_add(p_trip, t.start_date, 'takeoff', 'playlist', NULL, true);
  IF t.at_home_length = 'weekend' THEN
    PERFORM trip_private.at_home_add(p_trip, t.start_date, 'call_night', 'trivia', 'dress_up', true);
    PERFORM trip_private.at_home_add(p_trip, t.start_date+1, 'cook', 'dish');
    PERFORM trip_private.at_home_add(p_trip, t.start_date+1, 'question', 'question');
    PERFORM trip_private.at_home_add(p_trip, t.start_date+2, 'build', 'build');
  ELSE
    IF t.at_home_length='week' THEN v_cap := 7; drop_max := 2; ELSE v_cap := 9; drop_max := 1; END IF;
    FOR d IN 1..len-2 LOOP
      v_day := t.start_date + d; dow := extract(isodow FROM v_day)::int; wk := d / 7 + 1;
      total := (SELECT count(*) FROM public.at_home_activities WHERE trip_id=p_trip) + 1;
      IF total >= v_cap THEN EXIT; END IF;
      IF dow = 5 THEN PERFORM trip_private.at_home_add(p_trip, v_day, 'call_night', 'trivia', 'dress_up', true); last_d := d;
      ELSIF dow = 6 THEN
        IF cooks % 2 = 0 THEN v_cat := 'dish'; ELSE v_cat := 'order_in'; END IF;
        PERFORM trip_private.at_home_add(p_trip, v_day, 'cook', v_cat); cooks := cooks + 1;
        PERFORM trip_private.at_home_add(p_trip, v_day, 'question', 'question'); last_d := d;
      ELSIF dow = 7 THEN PERFORM trip_private.at_home_add(p_trip, v_day, 'build', 'build'); last_d := d;
      ELSIF d - last_d >= 2 AND drops[wk] < drop_max THEN
        v_cat := kinds[cyc % 5 + 1];
        IF v_cat = 'question' THEN PERFORM trip_private.at_home_add(p_trip, v_day, 'question', 'question');
        ELSE PERFORM trip_private.at_home_add(p_trip, v_day, 'drop', v_cat); END IF;
        cyc := cyc + 1; drops[wk] := drops[wk] + 1; last_d := d;
      END IF;
    END LOOP;
  END IF;
  PERFORM trip_private.at_home_add(p_trip, t.end_date, 'passport', 'movie', 'trivia', true);
END;
$$;


--
-- Name: plan_game_nights(uuid, text, integer, time without time zone, date, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.plan_game_nights(p_trip uuid, p_plan text, p_weekday integer, p_time time without time zone, p_start date, p_every integer, p_count integer DEFAULT NULL::integer) RETURNS TABLE(week_number integer, starts_at timestamp with time zone, kept boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; tz text; v_today date; v_next timestamptz; v_last date; v_from date; v_final date; v_cap int; v_kept int; i int; d date; v_dates date[] := '{}'; BEGIN
 IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only trip leaders can plan game nights'; END IF;
 IF p_plan NOT IN ('recommended','short','custom') OR p_weekday IS NULL OR p_weekday NOT BETWEEN 0 AND 6 OR p_time IS NULL THEN RAISE EXCEPTION 'Pick a game plan, day and time'; END IF;
 p_every := CASE WHEN p_plan='custom' AND p_every=2 THEN 2 ELSE 1 END;
 SELECT * INTO t FROM public.trips WHERE id=p_trip; tz := t.home_timezone; v_today := (now() AT TIME ZONE tz)::date;
 SELECT min(n.starts_at) INTO v_next FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at > now() AND NOT n.skipped;
 RETURN QUERY SELECT n.week_number,n.starts_at,true FROM public.game_nights n WHERE n.trip_id=p_trip AND (n.starts_at<=now() OR n.skipped OR n.starts_at=v_next) ORDER BY n.week_number;
 SELECT count(*), max((n.starts_at AT TIME ZONE tz)::date), coalesce(max(n.week_number),0) INTO v_kept,v_last,i FROM public.game_nights n WHERE n.trip_id=p_trip AND (n.starts_at<=now() OR n.skipped OR n.starts_at=v_next);
 v_from := greatest(coalesce(p_start,t.game_start,greatest(v_today,t.start_date-84)),v_today);
 IF v_from>t.start_date-2 THEN RAISE EXCEPTION 'Choose a start date before departure'; END IF;
 v_cap := 12-v_kept;
 IF p_plan='short' THEN v_cap := least(v_cap,4); END IF;
 IF p_plan='custom' AND p_count IS NOT NULL THEN v_cap := least(12-v_kept, least(greatest(p_count,1),12)); END IF;
 v_final := t.start_date-1;
 d := v_from+((p_weekday-extract(dow FROM v_from)::int+7)%7);
 WHILE d<v_final AND cardinality(v_dates)<greatest(v_cap-1,0) LOOP
   IF v_last IS NULL OR d>v_last THEN v_dates:=array_append(v_dates,d); END IF;
   d:=d+7*p_every;
 END LOOP;
 IF v_cap>0 AND (v_last IS NULL OR v_final>v_last) AND NOT v_final=ANY(v_dates) THEN v_dates:=array_append(v_dates,v_final); END IF;
 FOREACH d IN ARRAY v_dates LOOP
   IF ((d+p_time) AT TIME ZONE tz)>now() THEN i:=i+1; week_number:=i; starts_at:=(d+p_time) AT TIME ZONE tz; kept:=false; RETURN NEXT; END IF;
 END LOOP;
END $$;


--
-- Name: plan_nights(uuid, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.plan_nights(p_trip uuid, p_first timestamp with time zone, p_every integer, p_count integer) RETURNS TABLE(n integer, starts_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; v_local timestamp; v_days int; v_max int; v_gap interval; i int := 0; BEGIN
SELECT * INTO t FROM public.trips WHERE id=p_trip;
v_local := p_first AT TIME ZONE t.home_timezone;
WHILE v_local::date < t.start_date - 84 LOOP v_local := v_local + interval '7 days'; END LOOP;
v_days := t.start_date - v_local::date;
p_every := greatest(1, least(2, coalesce(p_every,1)));
IF v_days < 7 THEN v_max := 1; v_gap := interval '7 days';
ELSIF v_days < 14 THEN v_max := 2; v_gap := make_interval(days => greatest(2, v_days/2));
ELSE v_max := 12; v_gap := make_interval(days => 7*p_every); END IF;
IF p_count IS NOT NULL THEN v_max := greatest(0, least(v_max, p_count)); END IF;
WHILE i < v_max AND v_local::date < t.start_date LOOP
  i := i+1; n := i; starts_at := v_local AT TIME ZONE t.home_timezone; RETURN NEXT; v_local := v_local + v_gap;
END LOOP; END $$;


--
-- Name: trip_day_games; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trip_day_games (
    trip_id uuid NOT NULL,
    day_date date NOT NULL,
    tag text NOT NULL,
    city text DEFAULT ''::text NOT NULL,
    bingo jsonb DEFAULT '[]'::jsonb NOT NULL,
    bingo_mode text DEFAULT 'explorer'::text NOT NULL,
    quests jsonb DEFAULT '[]'::jsonb NOT NULL,
    trivia jsonb DEFAULT '[]'::jsonb NOT NULL,
    photo_theme text DEFAULT ''::text NOT NULL,
    airport jsonb DEFAULT '[]'::jsonb NOT NULL,
    wheels_up text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone,
    CONSTRAINT trip_day_games_tag_check CHECK ((tag = ANY (ARRAY['Party'::text, 'Explore'::text, 'Chill'::text, 'Travel'::text])))
);


--
-- Name: play_day(uuid, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.play_day(p_trip uuid, p_date date) RETURNS public.trip_day_games
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE g public.trip_day_games; bypass boolean := trip_private.lab_bypass(p_trip); BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
IF NOT bypass AND p_date IS DISTINCT FROM trip_private.trip_today(p_trip) THEN RAISE EXCEPTION 'That day''s games are closed'; END IF;
SELECT * INTO g FROM public.trip_day_games WHERE trip_id=p_trip AND day_date=p_date;
IF NOT FOUND OR (g.released_at IS NULL AND NOT bypass) THEN RAISE EXCEPTION 'Today''s games aren''t ready yet'; END IF; RETURN g; END $$;


--
-- Name: player_card_read(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.player_card_read(p_trip uuid, p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_trip public.trips%ROWTYPE;
  v_card public.trip_player_cards%ROWTYPE;
  v_role text;
  v_age int;
  v_teen boolean;
  v_points int := 0;
  v_place int := 0;
  v_total int := 0;
  v_stamps int := 0;
  v_crowns int := 0;
  v_rank jsonb := NULL;
  v_culture_badge text := NULL;
  v_founding boolean := false;
  v_season text;
BEGIN
  IF auth.uid() IS NULL
     OR NOT trip_private.is_trip_member(p_trip, auth.uid())
     OR NOT trip_private.is_trip_member(p_trip, p_user) THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_trip FROM public.trips WHERE id = p_trip;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT * INTO v_card
  FROM public.trip_player_cards
  WHERE trip_id = p_trip AND user_id = p_user;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT role INTO v_role
  FROM public.trip_members
  WHERE trip_id = p_trip AND user_id = p_user AND status = 'approved';

  v_age := trip_private.age_of(p_user);
  v_teen := coalesce(v_age < 18, false);
  v_season := CASE
    WHEN v_trip.kind <> 'trip' THEN 'home'
    WHEN current_date >= v_trip.start_date THEN 'trip'
    ELSE 'preflight'
  END;

  IF v_trip.season_rule = 'a2c' THEN
    WITH board AS (
      SELECT sp.user_id, sp.total::int AS points
      FROM trip_private.season_points(p_trip, v_season) sp
    ), ranked AS (
      SELECT b.user_id, b.points,
             row_number() OVER (ORDER BY b.points DESC, b.user_id)::int AS place,
             count(*) OVER ()::int AS total_people
      FROM board b
    )
    SELECT points, place, total_people
      INTO v_points, v_place, v_total
    FROM ranked WHERE user_id = p_user;
  ELSIF current_date >= v_trip.start_date THEN
    WITH board AS (
      SELECT ts.user_id, ts.score::int AS points
      FROM trip_private.trip_season_score(p_trip) ts
    ), ranked AS (
      SELECT b.user_id, b.points,
             row_number() OVER (ORDER BY b.points DESC, b.user_id)::int AS place,
             count(*) OVER ()::int AS total_people
      FROM board b
    )
    SELECT points, place, total_people
      INTO v_points, v_place, v_total
    FROM ranked WHERE user_id = p_user;
  ELSE
    WITH board AS (
      SELECT gb.user_id, gb.score::int AS points
      FROM trip_private.game_board(p_trip) gb
    ), ranked AS (
      SELECT b.user_id, b.points,
             row_number() OVER (ORDER BY b.points DESC, b.user_id)::int AS place,
             count(*) OVER ()::int AS total_people
      FROM board b
    )
    SELECT points, place, total_people
      INTO v_points, v_place, v_total
    FROM ranked WHERE user_id = p_user;
  END IF;

  IF v_total = 0 THEN
    SELECT count(*)::int INTO v_total
    FROM public.trip_members
    WHERE trip_id = p_trip AND status = 'approved';
    v_place := CASE WHEN v_total > 0 THEN 1 ELSE 0 END;
  END IF;

  IF v_teen THEN
    RETURN jsonb_build_object(
      'game_name', v_card.game_name,
      'avatar_style', v_card.avatar_style,
      'avatar_seed', v_card.avatar_seed,
      'points', coalesce(v_points, 0)
    );
  END IF;

  PERFORM trip_private.sync_passport(p_user);
  SELECT count(*)::int INTO v_stamps
  FROM public.passport_stamps
  WHERE user_id = p_user;

  SELECT count(*)::int INTO v_crowns
  FROM public.season_champions
  WHERE user_id = p_user;

  SELECT to_jsonb(r) INTO v_rank
  FROM trip_private.junkie_rank(p_user) r
  LIMIT 1;

  v_culture_badge := trip_private.culture_creator_badge(p_user);
  v_founding := trip_private.founding_member(p_user);

  RETURN jsonb_build_object(
    'game_name', v_card.game_name,
    'avatar_style', v_card.avatar_style,
    'avatar_seed', v_card.avatar_seed,
    'points', coalesce(v_points, 0),
    'place', coalesce(v_place, 0),
    'total_people', coalesce(v_total, 0),
    'role', v_role,
    'passport', jsonb_build_object(
      'stamps', v_stamps,
      'crowns', v_crowns,
      'rank', v_rank,
      'badges', jsonb_strip_nulls(jsonb_build_object(
        'founding_member', CASE WHEN v_founding THEN true ELSE NULL END,
        'culture_creator', v_culture_badge
      )),
      'trip_postcards', jsonb_build_object('available', false, 'items', '[]'::jsonb)
    ),
    'facts', jsonb_strip_nulls(jsonb_build_object(
      'hometown', v_card.hometown,
      'occupation', v_card.occupation,
      'fun_fact', v_card.fun_fact,
      'most_excited', v_card.most_excited,
      'trip_persona', v_card.trip_persona,
      'next_year_goal', v_card.next_year_goal
    ))
  );
END
$$;


--
-- Name: post_game_night_poll(uuid, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.post_game_night_poll(p_trip uuid, p_options jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can post times'; END IF; IF jsonb_typeof(p_options)<>'array' OR jsonb_array_length(p_options) NOT BETWEEN 3 AND 5 OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_options) AS o(v) WHERE (v::timestamptz <= now() OR v::timestamptz >= (SELECT start_date FROM public.trips WHERE id=p_trip) OR length(v)>40)) THEN RAISE EXCEPTION 'Add 3 to 5 future times before the trip'; END IF; DELETE FROM public.game_nights WHERE trip_id=p_trip; DELETE FROM public.game_night_polls WHERE trip_id=p_trip; DELETE FROM public.trip_play_state WHERE trip_id=p_trip; INSERT INTO public.game_night_polls(trip_id,options) VALUES(p_trip,p_options); END $$;


--
-- Name: post_live_vote(uuid, text, text, jsonb, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.post_live_vote(p_trip uuid, p_kind text, p_prompt text, p_options jsonb, p_week integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_week integer := coalesce(p_week, trip_private.current_week(p_trip)); v_opts jsonb; v_id uuid; BEGIN
IF NOT trip_private.can_run_night(p_trip, v_week) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can post a vote'; END IF;
IF v_week IS NOT NULL AND EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND week_number=v_week) AND NOT trip_private.night_open(p_trip, v_week) THEN RAISE EXCEPTION 'Votes open only while the game night is live'; END IF;
IF length(trim(coalesce(p_prompt,''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Add a prompt'; END IF;
IF p_kind IN ('most_likely','best_answer') THEN
  SELECT jsonb_agg(jsonb_build_object('label', coalesce(c.game_name, nullif(p.display_name,''), 'Player'), 'user_id', m.user_id) ORDER BY m.joined_at) INTO v_opts FROM public.trip_members m LEFT JOIN public.trip_player_cards c ON c.trip_id=m.trip_id AND c.user_id=m.user_id LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved';
  IF coalesce(jsonb_array_length(v_opts),0) < 2 THEN RAISE EXCEPTION 'You need at least 2 members to vote'; END IF;
ELSIF p_kind IN ('would_you_rather','custom') THEN
  IF jsonb_typeof(p_options)<>'array' OR (p_kind='would_you_rather' AND jsonb_array_length(p_options)<>2) OR jsonb_array_length(p_options) NOT BETWEEN 2 AND 4 OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_options) o(v) WHERE length(trim(v)) NOT BETWEEN 1 AND 80) THEN RAISE EXCEPTION 'Add 2 to 4 short options'; END IF;
  SELECT jsonb_agg(jsonb_build_object('label', trim(v))) INTO v_opts FROM jsonb_array_elements_text(p_options) o(v);
ELSE RAISE EXCEPTION 'Unknown vote type'; END IF;
INSERT INTO public.live_votes(trip_id,kind,prompt,options,week_number,created_by) VALUES (p_trip,p_kind,trim(p_prompt),v_opts,v_week,auth.uid()) RETURNING id INTO v_id; RETURN v_id; END $$;


--
-- Name: post_photo(uuid, date, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.post_photo(p_trip uuid, p_date date, p_photo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.require_feature(p_trip, 'photo_wall'); PERFORM trip_private.play_day(p_trip,p_date);
IF p_photo IS NULL OR NOT trip_private.valid_photo(p_trip,p_photo) THEN RAISE EXCEPTION 'Add a photo'; END IF;
INSERT INTO public.photo_posts(trip_id,day_date,user_id,photo_path) VALUES (p_trip,p_date,auth.uid(),p_photo) ON CONFLICT (trip_id,day_date,user_id) DO UPDATE SET photo_path=excluded.photo_path; END $$;


--
-- Name: post_quest(uuid, date, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.post_quest(p_trip uuid, p_date date, p_quest integer, p_photo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE g public.trip_day_games := trip_private.play_day(p_trip,p_date); BEGIN
 IF g.tag NOT IN ('Explore','Party') OR p_quest NOT BETWEEN 0 AND 2 THEN RAISE EXCEPTION 'No quests today'; END IF;
 IF p_photo IS NOT NULL AND NOT trip_private.valid_photo(p_trip,p_photo) THEN RAISE EXCEPTION 'Photo upload failed'; END IF;
 INSERT INTO public.quest_posts(trip_id,day_date,user_id,quest,photo_path) VALUES(p_trip,p_date,auth.uid(),p_quest,p_photo) ON CONFLICT(trip_id,day_date,user_id,quest) DO UPDATE SET photo_path=coalesce(excluded.photo_path,public.quest_posts.photo_path);
END $$;


--
-- Name: present_checkin(uuid, integer, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.present_checkin(p_trip uuid, p_week integer, p_claim uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE n public.game_nights; BEGIN SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week; IF n.trip_id IS NULL OR n.skipped OR (n.host_id<>auth.uid() AND NOT trip_private.is_leader(p_trip)) THEN RAISE EXCEPTION 'Only tonight''s host or a leader can mark a presentation'; END IF; IF now() < n.starts_at - interval '12 hours' OR now() > n.starts_at + interval '3 hours 30 minutes' THEN RAISE EXCEPTION 'Present during game night'; END IF; UPDATE public.mission_claims SET presented_at=now(),updated_at=now() WHERE id=p_claim AND trip_id=p_trip AND phase='checkin' AND status='pending' AND presented_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Pending Check-In task not found'; END IF; END $$;


--
-- Name: prevent_opt_in_quick_start(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.prevent_opt_in_quick_start() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.play_arrangement IS NOT NULL AND NEW.game_plan='quick_start' THEN
  RAISE EXCEPTION 'This room starts automatically from its dates; Quick Start is not available';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: preview_action(uuid, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.preview_action(p_preview uuid, p_action text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.experience_previews WHERE id=p_preview) THEN RAISE EXCEPTION 'Preview not found'; END IF;
  IF p_action='hide' THEN
    INSERT INTO public.preview_hidden(user_id,preview_id) VALUES (auth.uid(),p_preview) ON CONFLICT DO NOTHING;
  ELSIF p_action='unhide' THEN
    DELETE FROM public.preview_hidden WHERE user_id=auth.uid() AND preview_id=p_preview;
  ELSIF p_action='report' THEN
    IF (SELECT count(*) FROM public.bug_reports WHERE user_id=auth.uid() AND kind='preview_report' AND created_at > now() - interval '1 day') >= 10 THEN RAISE EXCEPTION 'Too many reports today'; END IF;
    INSERT INTO public.bug_reports(user_id,page,description,kind) VALUES (auth.uid(),'preview:'||p_preview::text,left(coalesce(nullif(btrim(p_reason),''),'Reported preview'),2000),'preview_report');
    INSERT INTO public.preview_hidden(user_id,preview_id) VALUES (auth.uid(),p_preview) ON CONFLICT DO NOTHING;
  ELSIF p_action IN ('unlist','relist') THEN
    IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
    UPDATE public.experience_previews SET unlisted_at = CASE WHEN p_action='unlist' THEN now() END, updated_at=now() WHERE id=p_preview;
  ELSE RAISE EXCEPTION 'Unknown action'; END IF;
END $$;


--
-- Name: preview_culture_link(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.preview_culture_link(p_preview uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.culture_exp_id FROM public.experience_previews p WHERE p.id=p_preview AND p.culture_public AND p.unlisted_at IS NULL AND trip_private.can_view_culture(p.culture_exp_id) $$;


--
-- Name: preview_ten_day_drops(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.preview_ten_day_drops(p_trip uuid) RETURNS TABLE(drop_no integer, drop_at timestamp with time zone, cutoff timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; first_day date; v_cut timestamptz; v_base timestamptz; v_window interval; n integer; i integer;
BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF t.kind <> 'trip' THEN RETURN; END IF;
 first_day:=greatest(coalesce(t.game_start,t.start_date-10),t.start_date-10);
 n:=CASE WHEN t.start_date-first_day<7 THEN 2 ELSE 3 END;
 v_cut:=((t.start_date-1)::timestamp AT TIME ZONE t.home_timezone);
 v_base:=(first_day+time '09:00') AT TIME ZONE t.home_timezone;
 v_window:=v_cut-v_base;
 IF v_window<=interval '1 hour' THEN RETURN; END IF;
 FOR i IN 1..n LOOP
   drop_no:=i; drop_at:=v_base+(v_window*(i-1)::double precision/n); cutoff:=v_cut; RETURN NEXT;
 END LOOP;
END $$;


--
-- Name: price(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.price(p_key text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT cents FROM public.price_rules WHERE key=p_key $$;


--
-- Name: proof_read_ok(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.proof_read_ok(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
 SELECT p_name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[^/]+$' AND (EXISTS (
 SELECT 1 FROM public.sealed_quests q WHERE q.id::text=split_part(p_name,'/',3) AND q.trip_id::text=split_part(p_name,'/',1) AND q.user_id::text=split_part(p_name,'/',2)
 AND trip_private.is_trip_member(q.trip_id,auth.uid()) AND (q.user_id=auth.uid() OR trip_private.is_leader(q.trip_id) OR (NOT trip_private.a2c_minor_trip(q.trip_id) AND q.proof_shared AND q.proof_path=p_name)))
 OR EXISTS (SELECT 1 FROM public.trip_season_games g WHERE g.id::text=split_part(p_name,'/',3) AND g.trip_id::text=split_part(p_name,'/',1)
 AND trip_private.is_trip_member(g.trip_id,auth.uid()) AND (split_part(p_name,'/',2)=auth.uid()::text OR trip_private.is_leader(g.trip_id)))) $_$;


--
-- Name: proof_upload_ok(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.proof_upload_ok(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
 SELECT p_name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[^/]+$' AND (EXISTS (
  SELECT 1 FROM public.sealed_quests q
  WHERE q.id::text=split_part(p_name,'/',3) AND q.trip_id::text=split_part(p_name,'/',1) AND q.user_id::text=split_part(p_name,'/',2)
   AND q.user_id=auth.uid() AND q.kind='sealed' AND q.opened_at IS NOT NULL AND q.submitted_at IS NULL
   AND now() < least(q.opened_at+interval '24 hours', trip_private.quest_cutoff(q.trip_id))
   AND trip_private.is_trip_member(q.trip_id, auth.uid()))
 OR EXISTS (SELECT 1 FROM public.trip_season_games g
  WHERE g.id::text=split_part(p_name,'/',3) AND g.trip_id::text=split_part(p_name,'/',1) AND split_part(p_name,'/',2)=auth.uid()::text
   AND trip_private.is_trip_member(g.trip_id, auth.uid()) AND g.day_date=trip_private.trip_today(g.trip_id))) $_$;


--
-- Name: public_inspiration_queue(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.public_inspiration_queue() RETURNS TABLE(id uuid, title text, category text, country text, region text, city text, approved boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
RETURN QUERY SELECT c.id,c.title,c.category,c.country,c.region,c.city,c.public_approved_at IS NOT NULL,c.created_at FROM public.cultural_inspirations c JOIN public.trips t ON t.id=c.trip_id WHERE c.feature_later AND c.hidden_at IS NULL AND NOT coalesce(t.is_sandbox,false) ORDER BY (c.public_approved_at IS NOT NULL), c.created_at DESC; END $$;


--
-- Name: public_launch(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.public_launch() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT coalesce((SELECT public_launch FROM public.app_settings LIMIT 1), false) $$;


--
-- Name: qotw_action(uuid, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.qotw_action(p_trip uuid, p_week integer, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE q public.weekly_questions; v_n integer; BEGIN PERFORM trip_private.require_feature(p_trip, 'qotw');
IF NOT trip_private.can_run_turns(p_trip, p_week) THEN RAISE EXCEPTION 'Only the host or a trip leader can run this'; END IF;
IF (SELECT starts_at FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week) > now() + interval '30 minutes' THEN RAISE EXCEPTION 'This happens at the start of game night'; END IF;
SELECT * INTO q FROM public.weekly_questions WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'No question this week'; END IF;
SELECT count(*) INTO v_n FROM public.weekly_answers WHERE trip_id=p_trip AND week_number=p_week;
IF p_action='read' THEN
  IF q.phase<>'hidden' OR q.drops_at > now() THEN RETURN; END IF;
  IF v_n=0 THEN UPDATE public.weekly_questions SET phase='revealed', revealed_at=now() WHERE trip_id=p_trip AND week_number=p_week;
  ELSE UPDATE public.weekly_questions SET phase='reading', read_index=0 WHERE trip_id=p_trip AND week_number=p_week; END IF;
ELSIF p_action='next' THEN
  IF q.phase<>'reading' THEN RETURN; END IF;
  IF q.read_index+1 >= v_n THEN UPDATE public.weekly_questions SET phase='voting' WHERE trip_id=p_trip AND week_number=p_week;
  ELSE UPDATE public.weekly_questions SET read_index=q.read_index+1 WHERE trip_id=p_trip AND week_number=p_week; END IF;
ELSIF p_action='end_voting' THEN
  IF q.phase<>'voting' THEN RETURN; END IF;
  PERFORM trip_private.qotw_finalize(p_trip, p_week);
ELSIF p_action='break_tie' THEN
  IF q.phase<>'tie' THEN RETURN; END IF;
  UPDATE public.weekly_questions SET phase='revealed', winner_id=q.tie_ids[1 + floor(random()*cardinality(q.tie_ids))::int], tie_spin_at=now() WHERE trip_id=p_trip AND week_number=p_week;
ELSE RAISE EXCEPTION 'Unknown action'; END IF; END $$;


--
-- Name: qotw_answers(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.qotw_answers(p_trip uuid, p_week integer) RETURNS TABLE(idx integer, answer text, emoji text, mine boolean, user_id uuid, votes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE q public.weekly_questions; BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
SELECT * INTO q FROM public.weekly_questions w WHERE w.trip_id=p_trip AND w.week_number=p_week;
IF NOT FOUND OR q.phase='hidden' THEN RETURN; END IF;
RETURN QUERY SELECT o.idx, o.answer, o.emoji, o.user_id=auth.uid(),
  CASE WHEN q.revealed_at IS NOT NULL THEN o.user_id ELSE NULL END,
  CASE WHEN q.revealed_at IS NOT NULL THEN (SELECT count(*)::int FROM public.weekly_answer_votes v WHERE v.trip_id=p_trip AND v.week_number=p_week AND v.target_id=o.user_id) ELSE NULL END
  FROM trip_private.ordered_answers(p_trip, p_week) o
  WHERE q.phase <> 'reading' OR o.idx <= q.read_index ORDER BY o.idx; END $$;


--
-- Name: qotw_finalize(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.qotw_finalize(p_trip uuid, p_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_max integer; v_ids uuid[]; BEGIN
WITH c AS (SELECT o.user_id, (SELECT count(*) FROM public.weekly_answer_votes v WHERE v.trip_id=p_trip AND v.week_number=p_week AND v.target_id=o.user_id)::int n FROM trip_private.ordered_answers(p_trip,p_week) o)
SELECT max(n) INTO v_max FROM c;
SELECT array_agg(o.user_id) INTO v_ids FROM trip_private.ordered_answers(p_trip,p_week) o
  WHERE (SELECT count(*) FROM public.weekly_answer_votes v WHERE v.trip_id=p_trip AND v.week_number=p_week AND v.target_id=o.user_id) = coalesce(v_max,0);
IF v_ids IS NULL OR cardinality(v_ids)=0 THEN
  UPDATE public.weekly_questions SET phase='revealed', revealed_at=coalesce(revealed_at,now()) WHERE trip_id=p_trip AND week_number=p_week;
ELSIF cardinality(v_ids)=1 THEN
  UPDATE public.weekly_questions SET phase='revealed', winner_id=v_ids[1], revealed_at=coalesce(revealed_at,now()) WHERE trip_id=p_trip AND week_number=p_week;
ELSE
  UPDATE public.weekly_questions SET phase='tie', tie_ids=v_ids, revealed_at=coalesce(revealed_at,now()) WHERE trip_id=p_trip AND week_number=p_week;
END IF; END $$;


--
-- Name: quest_access(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.quest_access(p_card uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user IS NOT NULL AND (
    EXISTS (SELECT 1 FROM public.cultural_inspirations c
            WHERE c.id = p_card AND c.hidden_at IS NULL AND c.reveal_on <= CURRENT_DATE
              AND trip_private.is_trip_member(c.trip_id, p_user))
    OR trip_private.inspiration_public(p_card))
$$;


--
-- Name: quest_cutoff(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.quest_cutoff(p_trip uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT CASE WHEN t.season_rule='a2c' AND t.kind='trip' AND t.game_plan='quick_start' THEN (t.start_date::timestamp AT TIME ZONE t.home_timezone)
 WHEN t.season_rule='a2c' AND t.kind='at_home' THEN t.finale_at
 WHEN t.kind='trip' THEN ((t.start_date-1)::timestamp AT TIME ZONE t.home_timezone)
 ELSE coalesce((SELECT max(n.starts_at) FROM public.game_nights n WHERE n.trip_id=t.id AND NOT n.skipped), ((t.end_date+time '18:00') AT TIME ZONE t.home_timezone)) END
 FROM public.trips t WHERE t.id=p_trip $$;


--
-- Name: quest_item_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.quest_item_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.card_id<>OLD.card_id THEN RAISE EXCEPTION 'Quest ownership cannot change'; END IF; IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.culture_quest_sessions s WHERE s.card_id=OLD.card_id AND s.finished_at IS NOT NULL) AND (NEW.answer IS DISTINCT FROM OLD.answer OR NEW.options IS DISTINCT FROM OLD.options OR NEW.prompt IS DISTINCT FROM OLD.prompt) THEN RAISE EXCEPTION 'Finished questions cannot change'; END IF; IF jsonb_typeof(NEW.options)<>'array' OR jsonb_array_length(NEW.options)<>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.options) x WHERE jsonb_typeof(x)<>'string' OR length(x #>> '{}')>150) THEN RAISE EXCEPTION 'Add four short choices'; END IF; IF NEW.round_number=2 AND (NEW.photo_path IS NULL OR NOT EXISTS(SELECT 1 FROM public.cultural_inspirations c WHERE c.id=NEW.card_id AND c.photo_path=NEW.photo_path)) THEN RAISE EXCEPTION 'Picture It uses your uploaded photo'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;


--
-- Name: quest_review(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.quest_review(p_post uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE q public.quest_posts; BEGIN
 SELECT * INTO q FROM public.quest_posts WHERE id=p_post FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Quest not found'; END IF;
 IF p_action='challenge' THEN
  PERFORM trip_private.play_day(q.trip_id,q.day_date);
  IF q.user_id=auth.uid() THEN RAISE EXCEPTION 'You cannot challenge your own item'; END IF;
  INSERT INTO public.quest_challenges(post_id,trip_id,challenged_by) VALUES(p_post,q.trip_id,auth.uid()) ON CONFLICT DO NOTHING;
 ELSIF p_action IN ('approve','reject') THEN
  IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=q.trip_id AND user_id=auth.uid() AND status='approved' AND role='captain') THEN RAISE EXCEPTION 'Captain only'; END IF;
  UPDATE public.quest_challenges SET decision=(p_action='approve'),decided_by=auth.uid(),updated_at=now() WHERE post_id=p_post AND decision IS NULL;
 ELSE RAISE EXCEPTION 'Unknown review action'; END IF;
END $$;


--
-- Name: quest_unlocked(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.quest_unlocked(p_trip uuid, p_week integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=p_week AND NOT n.skipped AND now()>=(trip_private.season_start(p_trip)::timestamp AT TIME ZONE (SELECT t.home_timezone FROM public.trips t WHERE t.id=p_trip)) AND (n.week_number=(SELECT min(x.week_number) FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped) OR EXISTS(SELECT 1 FROM public.game_nights prev WHERE prev.trip_id=p_trip AND NOT prev.skipped AND prev.week_number<n.week_number AND prev.starts_at+interval '3 hours 30 minutes'<=now() AND NOT EXISTS(SELECT 1 FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped AND x.week_number>prev.week_number AND x.week_number<n.week_number)))) $$;


--
-- Name: quick_vote_action(uuid, text, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.quick_vote_action(p_trip uuid, p_action text, p_vote uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v public.live_votes; v_id uuid; v_week integer; v_counts jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Trip not found'; END IF;
 SELECT week_number INTO v_week FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped AND starts_at BETWEEN now()-interval '3 hours' AND now()+interval '15 minutes' ORDER BY starts_at DESC LIMIT 1;
 IF NOT (trip_private.is_leader(p_trip) OR (v_week IS NOT NULL AND EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND week_number=v_week AND host_id=auth.uid()))) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can run a vote'; END IF;
 IF p_action='start' THEN
   IF EXISTS(SELECT 1 FROM public.live_votes WHERE trip_id=p_trip AND kind='custom' AND prompt='Quick vote' AND status IN ('open','locked')) THEN RAISE EXCEPTION 'Finish the current Quick Vote first'; END IF;
   INSERT INTO public.live_votes(trip_id,kind,prompt,options,week_number,created_by) VALUES(p_trip,'custom','Quick vote','[{"label":"Cleared for Takeoff"},{"label":"Grounded"}]'::jsonb,NULL,auth.uid()) RETURNING id INTO v_id;
   RETURN v_id;
 END IF;
 SELECT * INTO v FROM public.live_votes WHERE id=p_vote AND trip_id=p_trip AND kind='custom' AND prompt='Quick vote' AND options='[{"label":"Cleared for Takeoff"},{"label":"Grounded"}]'::jsonb FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Quick Vote not found'; END IF;
 IF p_action='lock' THEN
   IF v.status <> 'open' THEN RAISE EXCEPTION 'Vote is not open'; END IF;
   UPDATE public.live_votes SET status='locked' WHERE id=v.id;
 ELSIF p_action='reveal' THEN
   IF v.status <> 'locked' THEN RAISE EXCEPTION 'Lock the vote first'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.live_vote_ballots WHERE vote_id=v.id) THEN RAISE EXCEPTION 'Waiting for votes'; END IF;
   SELECT jsonb_agg((SELECT count(*) FROM public.live_vote_ballots b WHERE b.vote_id=v.id AND b.option_index=i) ORDER BY i) INTO v_counts FROM generate_series(0,1) i;
   UPDATE public.live_votes SET status='revealed',results=v_counts,revealed_at=now() WHERE id=v.id;
 ELSE RAISE EXCEPTION 'Unknown action'; END IF;
 RETURN v.id;
END $$;


--
-- Name: quick_vote_totals(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.quick_vote_totals(p_vote uuid) RETURNS TABLE(cleared bigint, grounded bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v public.live_votes; v_week integer;
BEGIN
 SELECT * INTO v FROM public.live_votes WHERE id=p_vote AND kind='custom' AND prompt='Quick vote' AND options='[{"label":"Cleared for Takeoff"},{"label":"Grounded"}]'::jsonb;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT trip_private.is_trip_member(v.trip_id,auth.uid()) THEN RAISE EXCEPTION 'Quick Vote not found'; END IF;
 SELECT week_number INTO v_week FROM public.game_nights WHERE trip_id=v.trip_id AND NOT skipped AND starts_at BETWEEN now()-interval '3 hours' AND now()+interval '15 minutes' ORDER BY starts_at DESC LIMIT 1;
 IF NOT (trip_private.is_leader(v.trip_id) OR (v_week IS NOT NULL AND EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=v.trip_id AND week_number=v_week AND host_id=auth.uid()))) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can see totals before reveal'; END IF;
 RETURN QUERY SELECT count(*) FILTER(WHERE b.option_index=0),count(*) FILTER(WHERE b.option_index=1) FROM public.live_vote_ballots b WHERE b.vote_id=p_vote;
END $$;


--
-- Name: rate_content(uuid, text, text, text, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.rate_content(p_trip uuid, p_kind text, p_key text, p_text text, p_vote integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF;
IF p_vote NOT IN (-1,1) OR p_kind NOT IN ('card','qotw','bingo','quest','mission') THEN RAISE EXCEPTION 'Invalid rating'; END IF;
INSERT INTO public.content_feedback(kind,item_key,item_text,vote) VALUES (p_kind,left(p_key,64),left(p_text,300),p_vote);
END $$;


--
-- Name: reclaim_captain(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.reclaim_captain(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t public.trip_role_changes; cap uuid; BEGIN
 IF coalesce(trip_private.age_of(auth.uid()),0) < 21 THEN RAISE EXCEPTION 'Captains are 21+.'; END IF;
 PERFORM 1 FROM public.trips WHERE id=p_trip FOR UPDATE;
 SELECT * INTO t FROM public.trip_role_changes WHERE trip_id=p_trip AND role='captain' AND reason='takeover' ORDER BY created_at DESC LIMIT 1;
 SELECT user_id INTO cap FROM public.trip_members WHERE trip_id=p_trip AND role='captain';
 IF t.id IS NULL OR t.from_user<>auth.uid() OR t.to_user IS DISTINCT FROM cap OR t.created_at < now()-interval '7 days' OR NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'The 7-day reclaim window has passed'; END IF;
 UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND (role='co_captain' OR user_id=auth.uid());
 UPDATE public.trip_members SET role='co_captain' WHERE trip_id=p_trip AND user_id=cap;
 UPDATE public.trip_members SET role='captain' WHERE trip_id=p_trip AND user_id=auth.uid();
 PERFORM trip_private.log_role(p_trip, cap, auth.uid(), 'captain', 'reclaimed');
END $$;


--
-- Name: record_speed_finish(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.record_speed_finish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_rel timestamptz;
BEGIN
 SELECT g.released_at INTO v_rel FROM public.trip_day_games g JOIN public.trips t ON t.id=g.trip_id
  WHERE g.trip_id=NEW.trip_id AND g.day_date=NEW.day_date AND t.season_rule='a2c' AND t.kind='trip' AND coalesce(g.tag,'')<>'Travel' AND g.released_at IS NOT NULL AND g.released_at <= now();
 IF v_rel IS NOT NULL THEN
   INSERT INTO trip_private.trip_speed_finishes(trip_id,day_date,user_id,source,revealed_at,finished_at)
   VALUES (NEW.trip_id,NEW.day_date,NEW.user_id,TG_TABLE_NAME,v_rel,now()) ON CONFLICT DO NOTHING;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: redeem_beta_code(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.redeem_beta_code(p_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b public.beta_codes%ROWTYPE; v text := upper(regexp_replace(coalesce(p_code,''),'[^A-Za-z0-9]','','g')); BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  IF EXISTS (SELECT 1 FROM public.beta_access WHERE user_id=auth.uid()) OR trip_private.has_beta_access() THEN RETURN 'has_access'; END IF;
  IF EXISTS (SELECT 1 FROM public.beta_codes WHERE used_by=auth.uid()) THEN RAISE EXCEPTION 'You''ve already used a beta code'; END IF;
  PERFORM trip_private.code_rate_check();
  SELECT * INTO b FROM public.beta_codes WHERE code=v FOR UPDATE;
  IF NOT FOUND THEN INSERT INTO trip_private.code_attempts(user_id) VALUES (auth.uid()); RETURN 'invalid'; END IF;
  IF b.used_at IS NOT NULL THEN RAISE EXCEPTION 'That code was already used'; END IF;
  IF b.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'That code was turned off — ask Ty for a new one'; END IF;
  IF b.expires_at <= now() THEN RAISE EXCEPTION 'That code expired — ask Ty for a new one'; END IF;
  UPDATE public.beta_codes SET used_by=auth.uid(), used_at=now() WHERE id=b.id;
  INSERT INTO public.beta_access(user_id, source) VALUES (auth.uid(), 'beta_code') ON CONFLICT DO NOTHING;
  RETURN 'ok'; END $$;


--
-- Name: refund_failed_ai(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.refund_failed_ai(p_usage uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v public.ai_usage%ROWTYPE; BEGIN SELECT * INTO v FROM public.ai_usage WHERE id=p_usage AND user_id=auth.uid() AND kind IN ('custom_game','regen_set','mission_topup') AND created_at>now()-interval '20 minutes' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'AI usage unavailable'; END IF; IF v.kind LIKE 'failed_%' THEN RETURN false; END IF; UPDATE public.ai_usage SET kind='failed_'||v.kind,credits=0 WHERE id=v.id; RETURN true; END $$;


--
-- Name: refund_failed_ai(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.refund_failed_ai(p_usage uuid, p_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v public.ai_usage%ROWTYPE; BEGIN SELECT * INTO v FROM public.ai_usage WHERE id=p_usage AND user_id=p_user AND kind IN ('custom_game','regen_set','mission_topup') AND created_at>now()-interval '20 minutes' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'AI usage unavailable'; END IF; UPDATE public.ai_usage SET kind='failed_'||v.kind,credits=0 WHERE id=v.id; RETURN true; END $$;


--
-- Name: release_trip_day(uuid, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.release_trip_day(p_trip uuid, p_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_unlocked(p_trip) THEN RAISE EXCEPTION 'Unlock the full trip to release trip-day games'; END IF;
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can release games'; END IF;
UPDATE public.trip_day_games SET released_at = coalesce(released_at, now()) WHERE trip_id=p_trip AND day_date=p_date;
IF NOT FOUND THEN RAISE EXCEPTION 'Today''s games are still being prepared — try again in a moment'; END IF; END $$;


--
-- Name: remove_photo(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.remove_photo(p_trip uuid, p_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.require_feature(p_trip, 'photo_wall');
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can delete photos'; END IF;
IF split_part(p_path,'/',1) <> p_trip::text THEN RAISE EXCEPTION 'That photo isn''t from this trip'; END IF;
INSERT INTO public.photo_removed(trip_id, photo_path, removed_by) VALUES (p_trip, p_path, auth.uid()) ON CONFLICT DO NOTHING;
DELETE FROM public.photo_reactions WHERE photo_path=p_path; END $$;


--
-- Name: render_card(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.render_card(p_trip uuid, p_prompt text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_destination text; v_city text; BEGIN
 SELECT nullif(btrim(split_part(t.destination,',',1)),''), (SELECT nullif(btrim(d->>'city'),'') FROM public.trip_itineraries i CROSS JOIN LATERAL jsonb_array_elements(i.days::jsonb) d WHERE i.trip_id=p_trip AND nullif(btrim(d->>'city'),'') IS NOT NULL ORDER BY CASE WHEN d->>'date'=to_char(now() AT TIME ZONE coalesce(t.trip_timezone,t.home_timezone),'YYYY-MM-DD') THEN 0 ELSE 1 END, d->>'date' LIMIT 1) INTO v_destination,v_city FROM public.trips t WHERE t.id=p_trip;
 RETURN replace(replace(p_prompt,'{destination}',coalesce(v_destination,v_city,'your destination')),'{city}',coalesce(v_city,v_destination,'your city'));
END $$;


--
-- Name: report_cost_payment(uuid, bigint, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.report_cost_payment(p_item uuid, p_amount_cents bigint, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE s public.cost_shares; v bigint; BEGIN
  SELECT * INTO s FROM public.cost_shares WHERE item_id=p_item AND user_id=auth.uid();
  IF NOT FOUND OR NOT trip_private.is_trip_member(s.trip_id, auth.uid()) THEN RAISE EXCEPTION 'You don''t have a share in this cost'; END IF;
  IF p_amount_cents IS NOT NULL AND p_amount_cents <= 0 THEN RAISE EXCEPTION 'Enter an amount above zero'; END IF;
  v := coalesce(p_amount_cents, greatest(s.share_cents - s.paid_cents, 1));
  UPDATE public.cost_shares SET reported_cents=v, report_note=nullif(left(trim(coalesce(p_note,'')),120),''), reported_at=now()
    WHERE item_id=p_item AND user_id=auth.uid();
  PERFORM trip_private.log_cost(s.trip_id, p_item, auth.uid(), 'reported payment', v, NULL);
END $$;


--
-- Name: request_host_swap(uuid, integer, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.request_host_swap(p_trip uuid, p_week integer, p_to uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE n public.game_nights; v_id uuid; BEGIN
SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week;
IF NOT FOUND OR n.host_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only this night''s host can swap it'; END IF;
IF n.starts_at - interval '2 hours' <= now() THEN RAISE EXCEPTION 'Swaps close 2 hours before game night'; END IF;
IF p_to IS NOT NULL AND (p_to=auth.uid() OR NOT trip_private.is_trip_member(p_trip,p_to)) THEN RAISE EXCEPTION 'Pick another player in this trip'; END IF;
UPDATE public.host_swaps SET status='cancelled', updated_at=now() WHERE trip_id=p_trip AND week_number=p_week AND status='open';
INSERT INTO public.host_swaps(trip_id,week_number,from_user,to_user) VALUES(p_trip,p_week,auth.uid(),p_to) RETURNING id INTO v_id;
RETURN v_id; END $$;


--
-- Name: request_room(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.request_room(p_trip uuid, p_interest text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t trips%ROWTYPE; v_age int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  v_age := trip_private.age_of(auth.uid());
  IF v_age IS NULL THEN RAISE EXCEPTION 'Add your date of birth first'; END IF;
  IF v_age < 21 THEN RAISE EXCEPTION 'Game Room requests are for players 21 and older'; END IF;
  SELECT * INTO t FROM trips WHERE id=p_trip AND room_listed AND NOT is_sandbox;
  IF NOT FOUND THEN RAISE EXCEPTION 'This room isn''t taking requests'; END IF;
  IF t.ended_at IS NOT NULL OR t.end_date < current_date THEN RAISE EXCEPTION 'This trip has ended'; END IF;
  IF EXISTS (SELECT 1 FROM trip_members WHERE trip_id=p_trip AND user_id=auth.uid()) THEN RAISE EXCEPTION 'You''re already in this room'; END IF;
  IF EXISTS (SELECT 1 FROM room_blocks WHERE trip_id=p_trip AND user_id=auth.uid()) THEN RAISE EXCEPTION 'This room isn''t taking requests'; END IF;
  IF EXISTS (SELECT 1 FROM room_requests WHERE trip_id=p_trip AND user_id=auth.uid() AND created_at > now() - interval '7 days') THEN RAISE EXCEPTION 'You can ask this room once every 7 days'; END IF;
  IF (SELECT count(*) FROM room_requests WHERE user_id=auth.uid() AND status='pending' AND expires_at > now()) >= 3 THEN RAISE EXCEPTION 'You have 3 open requests. Wait for an answer first.'; END IF;
  INSERT INTO room_requests(trip_id, user_id, interest, expires_at)
  VALUES (p_trip, auth.uid(), left(nullif(trim(coalesce(p_interest,'')),''), 80), least(now() + interval '3 days', (t.end_date + 1)::timestamptz));
END $$;


--
-- Name: require_feature(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.require_feature(p_trip uuid, p_feature text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$ BEGIN RETURN; END $$;


--
-- Name: FUNCTION require_feature(p_trip uuid, p_feature text); Type: COMMENT; Schema: trip_private; Owner: -
--

COMMENT ON FUNCTION trip_private.require_feature(p_trip uuid, p_feature text) IS 'M1-10: no-op. Kept only for older callers; do not use in new code.';


--
-- Name: require_legal(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.require_legal() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF auth.uid() IS NULL OR NOT trip_private.legal_current(auth.uid()) THEN RAISE EXCEPTION 'Please agree to the current Terms before continuing'; END IF; END $$;


--
-- Name: reschedule_preview(uuid, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.reschedule_preview(p_trip uuid, p_every integer, p_count integer) RETURNS TABLE(week_number integer, starts_at timestamp with time zone, played boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_played int; v_anchor timestamptz; v_last timestamptz; BEGIN
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only trip leaders can change the schedule'; END IF;
SELECT count(*), max(n.starts_at) INTO v_played, v_last FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at <= now();
RETURN QUERY SELECT n.week_number, n.starts_at, true FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at <= now() ORDER BY n.week_number;
SELECT min(n.starts_at) INTO v_anchor FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at > now();
IF v_anchor IS NULL AND v_last IS NOT NULL THEN v_anchor := ((v_last AT TIME ZONE (SELECT home_timezone FROM public.trips WHERE id=p_trip)) + make_interval(days => 7*greatest(1,least(2,coalesce(p_every,1))))) AT TIME ZONE (SELECT home_timezone FROM public.trips WHERE id=p_trip); END IF;
IF v_anchor IS NULL THEN RETURN; END IF;
RETURN QUERY SELECT (v_played + p.n)::int, p.starts_at, false FROM trip_private.plan_nights(p_trip, v_anchor, p_every, greatest(0, least(12, coalesce(p_count,12)) - v_played)) p;
END $$;


--
-- Name: reset_trip_code(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.reset_trip_code(p_trip uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE new_code text; attempt int; BEGIN
 PERFORM 1 FROM public.trips WHERE id=p_trip FOR UPDATE;
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can reset the join code'; END IF;
 FOR attempt IN 1..15 LOOP
  BEGIN
   new_code := public.new_trip_code();
   UPDATE public.trips SET join_code=new_code WHERE id=p_trip AND join_code<>new_code;
   IF FOUND THEN
     INSERT INTO public.trip_role_changes(trip_id, role, reason, actor) VALUES (p_trip, 'join_settings', 'Join code reset', auth.uid());
     RETURN new_code; END IF;
  EXCEPTION WHEN unique_violation THEN IF attempt=15 THEN RAISE; END IF;
  END;
 END LOOP;
 RAISE EXCEPTION 'Could not reset the code';
END $$;


--
-- Name: resolve_age_guesses(uuid, integer, numeric); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.resolve_age_guesses(p_trip uuid, p_week integer, p_answer numeric) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_best numeric; v_n integer; BEGIN
IF NOT trip_private.can_run_night(p_trip, p_week) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can pick the winner'; END IF;
SELECT min(abs(guess-p_answer)) INTO v_best FROM public.age_guesses WHERE trip_id=p_trip AND week_number=p_week;
IF v_best IS NULL THEN RAISE EXCEPTION 'No guesses yet'; END IF;
INSERT INTO public.game_scores(trip_id,week_number,user_id,here,won) SELECT p_trip,p_week,user_id,true,true FROM public.age_guesses WHERE trip_id=p_trip AND week_number=p_week AND abs(guess-p_answer)=v_best ON CONFLICT (trip_id,week_number,user_id) DO UPDATE SET won=true, here=true;
GET DIAGNOSTICS v_n = ROW_COUNT; RETURN v_n; END $$;


--
-- Name: respin_game(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.respin_game(p_trip uuid) RETURNS TABLE(game_number integer, week_number integer, spin_time timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_week int; v_host uuid; v_game int; tr public.trips; used int; BEGIN
IF NOT trip_private.trip_open(p_trip) THEN RAISE EXCEPTION 'This trip has ended — it''s read-only now'; END IF;
SELECT n.week_number, n.host_id INTO v_week, v_host FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at<=clock_timestamp() ORDER BY n.starts_at DESC LIMIT 1;
IF v_week IS NULL OR v_host IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only this week''s host can use a pass to re-spin'; END IF;
SELECT * INTO tr FROM public.trips WHERE id=p_trip;
IF (now() AT TIME ZONE tr.home_timezone)::date >= tr.start_date THEN RAISE EXCEPTION 'Game nights are over'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(p_trip::text || auth.uid()::text));
SELECT count(*) INTO used FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND season='game';
IF used >= 3 THEN RAISE EXCEPTION 'No skip passes left this season'; END IF;
IF EXISTS (SELECT 1 FROM public.skip_passes WHERE trip_id=p_trip AND kind='respin' AND ref=v_week::text) THEN RAISE EXCEPTION 'This week already had its re-spin'; END IF;
SELECT n.game_number INTO v_game FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_week+1;
IF v_game IS NULL THEN RAISE EXCEPTION 'Spin the wheel first'; END IF;
UPDATE public.game_nights n SET game_number=NULL WHERE n.trip_id=p_trip AND n.week_number=v_week+1;
UPDATE public.trip_play_state s SET used_games=array_remove(s.used_games, v_game) WHERE s.trip_id=p_trip;
INSERT INTO public.skip_passes(trip_id, user_id, season, kind, ref) VALUES (p_trip, auth.uid(), 'game', 'respin', v_week::text);
RETURN QUERY SELECT * FROM trip_private.spin_next_game(p_trip); END $$;


--
-- Name: resplit_even_costs(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.resplit_even_costs(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE it record; r record; v_n int; v_base bigint; v_rem bigint; i int; v_gone int; BEGIN PERFORM trip_private.require_feature(p_trip, 'trip_pot');
  DELETE FROM public.cost_shares cs WHERE cs.trip_id=p_trip AND NOT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=cs.user_id AND m.status='approved');
  GET DIAGNOSTICS v_gone = ROW_COUNT;
  SELECT count(*) INTO v_n FROM public.trip_members WHERE trip_id=p_trip AND status='approved';
  IF v_n = 0 THEN RETURN; END IF;
  FOR it IN SELECT id, total_cents FROM public.cost_items WHERE trip_id=p_trip AND split='even' LOOP
    v_base := it.total_cents / v_n; v_rem := it.total_cents - v_base*v_n; i := 0;
    FOR r IN SELECT user_id FROM public.trip_members WHERE trip_id=p_trip AND status='approved' ORDER BY joined_at, user_id LOOP
      INSERT INTO public.cost_shares(item_id,trip_id,user_id,share_cents) VALUES (it.id,p_trip,r.user_id,v_base + CASE WHEN i < v_rem THEN 1 ELSE 0 END)
      ON CONFLICT (item_id,user_id) DO UPDATE SET share_cents=EXCLUDED.share_cents; i := i+1;
    END LOOP;
  END LOOP;
  UPDATE public.cost_items SET needs_review=true WHERE trip_id=p_trip AND split='custom';
END $$;


--
-- Name: respond_host_swap(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.respond_host_swap(p_swap uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE s public.host_swaps; n public.game_nights; v_other int; BEGIN
SELECT * INTO s FROM public.host_swaps WHERE id=p_swap FOR UPDATE;
IF NOT FOUND OR s.status<>'open' THEN RAISE EXCEPTION 'This swap is no longer open'; END IF;
IF p_action='cancel' THEN
  IF s.from_user<>auth.uid() AND NOT trip_private.is_leader(s.trip_id) THEN RAISE EXCEPTION 'Only the host can cancel'; END IF;
  UPDATE public.host_swaps SET status='cancelled', updated_at=now() WHERE id=p_swap; RETURN;
END IF;
IF p_action<>'accept' THEN RAISE EXCEPTION 'Unknown action'; END IF;
IF auth.uid()=s.from_user OR NOT trip_private.is_trip_member(s.trip_id,auth.uid()) OR (s.to_user IS NOT NULL AND s.to_user<>auth.uid()) THEN RAISE EXCEPTION 'This swap isn''t for you'; END IF;
SELECT * INTO n FROM public.game_nights WHERE trip_id=s.trip_id AND week_number=s.week_number FOR UPDATE;
IF n.host_id IS DISTINCT FROM s.from_user THEN RAISE EXCEPTION 'The host already changed'; END IF;
IF n.starts_at - interval '2 hours' <= now() THEN RAISE EXCEPTION 'Swaps close 2 hours before game night'; END IF;
SELECT week_number INTO v_other FROM public.game_nights WHERE trip_id=s.trip_id AND host_id=auth.uid() AND starts_at > now() AND week_number<>s.week_number AND NOT skipped ORDER BY starts_at LIMIT 1;
UPDATE public.game_nights SET host_id=auth.uid() WHERE trip_id=s.trip_id AND week_number=s.week_number;
IF v_other IS NOT NULL THEN UPDATE public.game_nights SET host_id=s.from_user WHERE trip_id=s.trip_id AND week_number=v_other; END IF;
UPDATE public.host_swaps SET status='accepted', accepted_by=auth.uid(), updated_at=now() WHERE id=p_swap;
END $$;


--
-- Name: reveal_inspiration_votes(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.reveal_inspiration_votes(p_card uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.cultural_inspirations SET votes_revealed_at = now()
  WHERE id = p_card AND creator_id = auth.uid() AND mode = 'challenge' AND hidden_at IS NULL
    AND reveal_on <= CURRENT_DATE AND votes_revealed_at IS NULL
    AND trip_private.is_trip_member(trip_id, auth.uid());
  IF NOT FOUND THEN RAISE EXCEPTION 'Only the approved creator can reveal votes on a displayed challenge'; END IF;
END $$;


--
-- Name: reveal_live_vote(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.reveal_live_vote(p_vote uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v public.live_votes; v_counts jsonb; v_max integer; v_finale boolean; BEGIN
SELECT * INTO v FROM public.live_votes WHERE id=p_vote FOR UPDATE;
IF v.id IS NULL OR NOT trip_private.can_run_night(v.trip_id,v.week_number) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can reveal'; END IF;
IF v.status='revealed' THEN RETURN; END IF;
IF NOT EXISTS (SELECT 1 FROM public.live_vote_ballots b WHERE b.vote_id=p_vote) THEN RAISE EXCEPTION 'Waiting for votes — at least one vote is needed before the reveal'; END IF;
SELECT jsonb_agg((SELECT count(*) FROM public.live_vote_ballots b WHERE b.vote_id=p_vote AND b.option_index=i) ORDER BY i) INTO v_counts FROM generate_series(0,jsonb_array_length(v.options)-1) i;
UPDATE public.live_votes SET status='revealed',results=v_counts,revealed_at=now() WHERE id=p_vote;
SELECT EXISTS(SELECT 1 FROM public.game_night_flow f WHERE f.trip_id=v.trip_id AND f.week_number=v.week_number AND f.phase='finale') INTO v_finale;
IF (v.kind='best_answer' OR (v.kind='most_likely' AND v_finale)) AND v.week_number IS NOT NULL AND trip_private.night_open(v.trip_id, v.week_number) THEN
 SELECT max(x::int) INTO v_max FROM jsonb_array_elements_text(v_counts) x;
 IF v_max>0 THEN
 INSERT INTO public.game_scores(trip_id,week_number,user_id,here,won) SELECT v.trip_id,v.week_number,(v.options->(i::int-1)->>'user_id')::uuid,true,true FROM jsonb_array_elements_text(v_counts) WITH ORDINALITY t(c,i) WHERE c::int=v_max ON CONFLICT(trip_id,week_number,user_id) DO UPDATE SET won=true,here=true;
 END IF;
END IF; END $$;


--
-- Name: reveal_mission(uuid, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.reveal_mission(p_trip uuid, p_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.play_day(p_trip,p_date);
UPDATE public.secret_missions SET revealed_at=now() WHERE trip_id=p_trip AND day_date=p_date AND user_id=auth.uid() AND revealed_at IS NULL;
IF NOT FOUND THEN RAISE EXCEPTION 'Nothing to reveal'; END IF; END $$;


