-- Name: reveal_weekly_question(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.reveal_weekly_question(p_trip uuid, p_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.qotw_action(p_trip,p_week,'read'); END $$;


--
-- Name: revoke_beta_code(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.revoke_beta_code(p_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
 UPDATE public.beta_codes SET revoked_at=now() WHERE code=upper(trim(p_code)) AND used_at IS NULL AND revoked_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'That code can''t be revoked (already used, revoked or not found)'; END IF; END $$;


--
-- Name: revoke_changed_birthday_approvals(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.revoke_changed_birthday_approvals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND NEW.birthday IS DISTINCT FROM OLD.birthday) THEN DELETE FROM public.trip_adult_approvals WHERE user_id=OLD.user_id; END IF; RETURN COALESCE(NEW,OLD); END $$;


--
-- Name: room_pricing(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.room_pricing(p_trip uuid) RETURNS TABLE(is_new boolean, base_key text, addon_key text, base_cents integer, addon_cents integer, days integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips;
BEGIN
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  days := t.end_date - t.start_date + 1;
  is_new := t.play_arrangement IS NOT NULL OR (t.kind='at_home' AND t.season_rule='a2c');
  IF NOT is_new THEN RETURN NEXT; RETURN; END IF;
  IF trip_private.is_window_room(p_trip) THEN
    base_key := CASE WHEN t.play_arrangement='solo' THEN 'window_solo' ELSE 'window_crew' END; addon_key := NULL;
  ELSIF t.kind='at_home' OR t.a2e_room THEN
    base_key := 'culture_base'; addon_key := 'culture_addon';
  ELSE
    base_key := CASE WHEN days<=5 THEN 'trip_d5' WHEN days<=10 THEN 'trip_d10' WHEN days<=15 THEN 'trip_d15' ELSE 'trip_d16' END; addon_key := 'trip_addon';
  END IF;
  base_cents := trip_private.price(base_key);
  addon_cents := CASE WHEN addon_key IS NOT NULL AND t.extra_seats THEN trip_private.price(addon_key) ELSE 0 END;
  RETURN NEXT;
END $$;


--
-- Name: room_requests_for(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.room_requests_for(p_trip uuid) RETURNS TABLE(id uuid, name text, home_city text, interest text, level integer, stamps integer, founding boolean, created_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_leader(p_trip) THEN RETURN; END IF;
  RETURN QUERY SELECT r.id, coalesce(nullif(pp.game_name,''), nullif(pr.display_name,''), 'Traveler'), pp.hometown, r.interest,
    (SELECT count(DISTINCT m.trip_id)::int FROM trip_members m JOIN trips tt ON tt.id=m.trip_id AND NOT tt.is_sandbox AND tt.kind <> 'at_home' WHERE m.user_id=r.user_id AND m.status='approved'),
    (SELECT count(*)::int FROM passport_stamps ps WHERE ps.user_id=r.user_id),
    coalesce(trip_private.founding_member(r.user_id), false), r.created_at, r.expires_at
  FROM room_requests r LEFT JOIN player_profiles pp ON pp.user_id=r.user_id LEFT JOIN profiles pr ON pr.id=r.user_id
  WHERE r.trip_id=p_trip AND r.status='pending' AND r.expires_at > now() ORDER BY r.created_at;
END $$;


--
-- Name: room_rounds(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.room_rounds(p_trip uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
SELECT CASE WHEN ceil((SELECT count(*) FROM public.trip_members WHERE status='approved' AND trip_id=p_trip)::numeric / greatest(1,(SELECT count(*) FROM public.trip_teams WHERE trip_id=p_trip AND (SELECT count(*) FROM public.trip_members WHERE status='approved' AND trip_id=p_trip) > 12))) <= 6 THEN 2 ELSE 1 END $$;


--
-- Name: save_cost_item(uuid, uuid, text, text, bigint, text, jsonb, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.save_cost_item(p_trip uuid, p_item uuid, p_title text, p_category text, p_total_cents bigint, p_split text, p_shares jsonb, p_due date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_n int; v_base bigint; v_rem bigint; v_sum bigint; r record; i int := 0;
BEGIN PERFORM trip_private.require_feature(p_trip, 'trip_pot');
  IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can edit trip costs'; END IF;
  IF EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND ended_at IS NOT NULL) THEN RAISE EXCEPTION 'This trip has ended'; END IF;
  IF p_total_cents IS NULL OR p_total_cents <= 0 THEN RAISE EXCEPTION 'Enter a total above zero'; END IF;
  IF p_item IS NULL THEN
    INSERT INTO public.cost_items(trip_id,title,category,total_cents,split,due_date) VALUES (p_trip,trim(p_title),p_category,p_total_cents,p_split,p_due) RETURNING id INTO v_id;
  ELSE
    UPDATE public.cost_items SET title=trim(p_title),category=p_category,total_cents=p_total_cents,split=p_split,due_date=p_due WHERE id=p_item AND trip_id=p_trip RETURNING id INTO v_id;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Cost item not found'; END IF;
  END IF;
  CREATE TEMP TABLE IF NOT EXISTS _shares(user_id uuid PRIMARY KEY, share_cents bigint) ON COMMIT DROP;
  TRUNCATE _shares;
  IF p_split = 'even' THEN
    SELECT count(*) INTO v_n FROM public.trip_members WHERE status='approved' AND trip_id=p_trip;
    v_base := p_total_cents / v_n; v_rem := p_total_cents - v_base * v_n;
    FOR r IN SELECT user_id FROM public.trip_members WHERE status='approved' AND trip_id=p_trip ORDER BY joined_at, user_id LOOP
      INSERT INTO _shares VALUES (r.user_id, v_base + CASE WHEN i < v_rem THEN 1 ELSE 0 END); i := i + 1;
    END LOOP;
  ELSE
    INSERT INTO _shares SELECT (e->>'user_id')::uuid, (e->>'share_cents')::bigint FROM jsonb_array_elements(coalesce(p_shares,'[]'::jsonb)) e WHERE coalesce((e->>'share_cents')::bigint,0) > 0;
    IF EXISTS (SELECT 1 FROM _shares s WHERE NOT trip_private.is_trip_member(p_trip, s.user_id)) THEN RAISE EXCEPTION 'Everyone in a split must be in this trip'; END IF;
    SELECT coalesce(sum(share_cents),0) INTO v_sum FROM _shares;
    IF v_sum <> p_total_cents THEN RAISE EXCEPTION 'Custom shares must add up to the total'; END IF;
  END IF;
  DELETE FROM public.cost_shares c WHERE c.item_id=v_id AND NOT EXISTS (SELECT 1 FROM _shares s WHERE s.user_id=c.user_id);
  INSERT INTO public.cost_shares(item_id,trip_id,user_id,share_cents) SELECT v_id,p_trip,s.user_id,s.share_cents FROM _shares s
    ON CONFLICT (item_id,user_id) DO UPDATE SET share_cents=EXCLUDED.share_cents;
  RETURN v_id;
END $$;


--
-- Name: save_cost_item_v2(uuid, uuid, text, text, text, boolean, bigint, text, jsonb, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.save_cost_item_v2(p_trip uuid, p_item uuid, p_title text, p_category text, p_custom text, p_estimate boolean, p_total_cents bigint, p_split text, p_shares jsonb, p_due date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v uuid; BEGIN PERFORM trip_private.require_feature(p_trip, 'trip_pot');
  v := trip_private.save_cost_item(p_trip,p_item,p_title,p_category,p_total_cents,p_split,p_shares,p_due);
  UPDATE public.cost_items SET needs_review=false, is_estimate=coalesce(p_estimate,false),
    custom_category=CASE WHEN p_category='other' THEN nullif(left(trim(coalesce(p_custom,'')),40),'') END WHERE id=v;
  PERFORM trip_private.log_cost(p_trip, v, NULL, CASE WHEN p_item IS NULL THEN 'added cost' ELSE 'edited cost' END, p_total_cents, trim(p_title));
  RETURN v; END $$;


--
-- Name: save_cost_item_wrap(uuid, uuid, text, text, bigint, text, jsonb, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.save_cost_item_wrap(p_trip uuid, p_item uuid, p_title text, p_category text, p_total_cents bigint, p_split text, p_shares jsonb, p_due date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v uuid; BEGIN v := trip_private.save_cost_item(p_trip,p_item,p_title,p_category,p_total_cents,p_split,p_shares,p_due); UPDATE public.cost_items SET needs_review=false WHERE id=v; RETURN v; END $$;


--
-- Name: save_game_scores(uuid, integer, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.save_game_scores(p_trip uuid, p_week integer, p_rows jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_host uuid; BEGIN
IF NOT trip_private.can_run_night(p_trip, p_week) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can score'; END IF;
SELECT host_id INTO v_host FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week;
IF NOT FOUND THEN RAISE EXCEPTION 'No game night that week'; END IF;
IF NOT trip_private.night_open(p_trip, p_week) THEN RAISE EXCEPTION 'Scores only count while the game night is live'; END IF;
IF jsonb_typeof(p_rows)<>'array' THEN RAISE EXCEPTION 'Bad scores'; END IF;
IF v_host = auth.uid() AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_rows) r WHERE (r->>'user_id')::uuid=auth.uid() AND coalesce((r->>'won')::boolean,false))
   AND NOT EXISTS (SELECT 1 FROM public.game_scores s WHERE s.trip_id=p_trip AND s.week_number=p_week AND s.user_id=auth.uid() AND s.won) THEN
  RAISE EXCEPTION 'Hosts can''t mark their own win — ask another leader to do it';
END IF;
INSERT INTO public.game_scores(trip_id,week_number,user_id,here,won,correct_guesses)
SELECT p_trip, p_week, (r->>'user_id')::uuid, coalesce((r->>'here')::boolean,false), coalesce((r->>'won')::boolean,false), nullif(r->>'correct_guesses','')::int
FROM jsonb_array_elements(p_rows) r WHERE EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=(r->>'user_id')::uuid AND m.status='approved')
ON CONFLICT (trip_id,week_number,user_id) DO UPDATE SET here=EXCLUDED.here,
  won=CASE WHEN v_host=auth.uid() AND EXCLUDED.user_id=auth.uid() THEN public.game_scores.won ELSE EXCLUDED.won END,
  correct_guesses=EXCLUDED.correct_guesses; END $$;


--
-- Name: save_teams(uuid, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.save_teams(p_trip uuid, p_teams jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t jsonb; tid uuid; u text; BEGIN PERFORM trip_private.require_feature(p_trip, 'teams');
IF NOT trip_private.can_manage_teams(p_trip) THEN RAISE EXCEPTION 'Only the Captain can set teams (Co-Captain during a game night)'; END IF;
IF jsonb_typeof(coalesce(p_teams,'[]'::jsonb)) <> 'array' OR jsonb_array_length(coalesce(p_teams,'[]'::jsonb)) > 4 THEN RAISE EXCEPTION 'Up to 4 teams'; END IF;
DELETE FROM public.trip_teams WHERE trip_id=p_trip;
FOR t IN SELECT * FROM jsonb_array_elements(coalesce(p_teams,'[]'::jsonb)) LOOP
  INSERT INTO public.trip_teams(trip_id, name, color, capacity) VALUES (p_trip, left(trim(t->>'name'),40), t->>'color', nullif(t->>'capacity','')::int) RETURNING id INTO tid;
  FOR u IN SELECT jsonb_array_elements_text(coalesce(t->'members','[]'::jsonb)) LOOP
    IF EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=u::uuid) THEN
      INSERT INTO public.trip_team_members(trip_id, user_id, team_id) VALUES (p_trip, u::uuid, tid) ON CONFLICT (trip_id, user_id) DO UPDATE SET team_id=EXCLUDED.team_id; END IF;
  END LOOP; END LOOP; END $$;


--
-- Name: sealed_quests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sealed_quests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    trip_id uuid NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    drop_no integer NOT NULL,
    drop_at timestamp with time zone NOT NULL,
    value integer NOT NULL,
    title text NOT NULL,
    mission_text text DEFAULT ''::text NOT NULL,
    backstory text DEFAULT ''::text NOT NULL,
    keywords text[] DEFAULT '{}'::text[] NOT NULL,
    opened_at timestamp with time zone,
    submitted_at timestamp with time zone,
    proof_mode text,
    proof_path text,
    proof_shared boolean DEFAULT false NOT NULL,
    declined_at timestamp with time zone,
    declined_by uuid,
    approved_at timestamp with time zone,
    approved_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    presentation_tag text,
    insight text,
    CONSTRAINT sealed_quests_check CHECK (((kind = 'showcase'::text) = (drop_no = 0))),
    CONSTRAINT sealed_quests_check1 CHECK (((submitted_at IS NULL) OR (proof_mode IS NOT NULL))),
    CONSTRAINT sealed_quests_check2 CHECK (((proof_mode IS DISTINCT FROM 'upload'::text) OR (proof_path IS NOT NULL))),
    CONSTRAINT sealed_quests_drop_no_check CHECK ((drop_no >= 0)),
    CONSTRAINT sealed_quests_kind_check CHECK ((kind = ANY (ARRAY['sealed'::text, 'showcase'::text]))),
    CONSTRAINT sealed_quests_presentation_tag_check CHECK ((presentation_tag = ANY (ARRAY['video_call'::text, 'trip_meetup'::text, 'at_home_finale'::text, 'solo_guide'::text]))),
    CONSTRAINT sealed_quests_proof_mode_check CHECK ((proof_mode = ANY (ARRAY['upload'::text, 'show'::text]))),
    CONSTRAINT sealed_quests_value_check CHECK ((value = ANY (ARRAY[5, 10, 20])))
);


--
-- Name: sealed_award(public.sealed_quests); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sealed_award(q public.sealed_quests) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
 SELECT CASE
  WHEN q.kind='showcase' THEN CASE WHEN q.approved_at IS NOT NULL AND q.declined_at IS NULL THEN q.value ELSE 0 END
  WHEN q.submitted_at IS NOT NULL AND q.declined_at IS NULL AND (q.proof_mode='upload' OR q.approved_at IS NOT NULL)
   THEN q.value + CASE WHEN q.submitted_at <= q.opened_at + interval '3 hours' THEN 5 ELSE 0 END
  ELSE 0 END $$;


--
-- Name: sealed_drops(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sealed_drops(p_trip uuid) RETURNS TABLE(drop_no integer, drop_at timestamp with time zone, value integer, cutoff timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; v_cut timestamptz; v_cutd date; v_start date; v_days int; v_n int; v_base timestamptz; v_window interval; i int;
BEGIN
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF NOT FOUND OR t.kind NOT IN ('trip','at_home') THEN RETURN; END IF;
 v_cut:=trip_private.quest_cutoff(p_trip); v_cutd:=(v_cut AT TIME ZONE t.home_timezone)::date;
 IF t.season_rule='a2c' THEN
   IF t.kind='trip' AND t.start_date <= (t.created_at AT TIME ZONE t.home_timezone)::date THEN RETURN; END IF;
   IF t.kind='trip' AND t.game_plan='quick_start' THEN
     drop_no:=1; drop_at:=t.created_at-interval '1 minute'; value:=10; cutoff:=v_cut; RETURN NEXT; RETURN;
   END IF;
   IF t.kind='trip' THEN
     v_start:=greatest(coalesce(t.game_start,(t.created_at AT TIME ZONE t.home_timezone)::date),t.start_date-10);
     v_n:=CASE WHEN t.start_date-v_start<7 THEN 2 ELSE 3 END;
     v_base:=greatest(t.created_at,(v_start+time '09:00') AT TIME ZONE t.home_timezone);
   ELSE
     v_n:=CASE WHEN t.end_date-t.start_date<6 THEN 2 ELSE 3 END;
     v_base:=(t.start_date+time '09:00') AT TIME ZONE t.home_timezone;
   END IF;
   v_window:=v_cut-v_base;
   IF v_window<=interval '1 hour' THEN RETURN; END IF;
   FOR i IN 1..v_n LOOP
     drop_no:=i; drop_at:=v_base+(v_window*(i-1)::double precision/v_n); cutoff:=v_cut;
     value:=CASE WHEN hashtext(p_trip::text||i::text)::bigint%2=0 THEN 5 ELSE 10 END;
     RETURN NEXT;
   END LOOP;
   RETURN;
 END IF;
 v_start:=CASE WHEN t.kind='trip' THEN greatest(coalesce(t.game_start,(t.created_at AT TIME ZONE t.home_timezone)::date),v_cutd-14) ELSE t.start_date END;
 v_days:=v_cutd-v_start;
 v_n:=CASE WHEN t.kind='trip' THEN CASE WHEN v_days<7 THEN 2 WHEN v_days<11 THEN 3 ELSE 4 END ELSE CASE WHEN v_days<=3 THEN 1 WHEN v_days<=5 THEN 2 ELSE 3 END END;
 RETURN QUERY WITH d AS (SELECT gs::date AS day FROM generate_series(v_start,v_cutd,interval '1 day') gs
 WHERE ((gs::date+time '10:00') AT TIME ZONE t.home_timezone)+interval '27 hours'<=v_cut
 ORDER BY md5(p_trip::text||gs::date::text) LIMIT v_n),o AS (SELECT d.day,(row_number() OVER (ORDER BY d.day))::int rn FROM d)
 SELECT o.rn,((o.day+time '10:00') AT TIME ZONE t.home_timezone),CASE WHEN abs(hashtext(p_trip::text||o.rn::text))%2=0 THEN 5 ELSE 10 END,v_cut FROM o ORDER BY o.rn;
END $$;


--
-- Name: sealed_proof_feed(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sealed_proof_feed(p_trip uuid) RETURNS TABLE(id uuid, user_id uuid, kind text, drop_no integer, value integer, title text, proof_mode text, proof_path text, submitted_at timestamp with time zone, speed boolean, state text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cut timestamptz;
BEGIN
 IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can review quests'; END IF;
 v_cut := trip_private.quest_cutoff(p_trip);
 RETURN QUERY SELECT * FROM (
  SELECT q.id,q.user_id,q.kind,q.drop_no,q.value,q.title,q.proof_mode,q.proof_path,q.submitted_at,
   (q.submitted_at IS NOT NULL AND q.submitted_at <= q.opened_at+interval '3 hours'), trip_private.sealed_state(q, v_cut)
  FROM public.sealed_quests q
  WHERE q.trip_id=p_trip AND q.user_id<>auth.uid() AND q.declined_at IS NULL AND trip_private.is_trip_member(p_trip,q.user_id)
   AND ((q.kind='sealed' AND q.submitted_at IS NOT NULL) OR (q.kind='showcase' AND q.approved_at IS NULL))
  UNION ALL
  SELECT f.id,f.user_id,'season_'||g.game,0,CASE g.game WHEN 'bingo' THEN 2 WHEN 'scavenger' THEN 4 ELSE 10 END,
   coalesce(g.tasks->>f.slot,'Trip Season task'),'upload',f.proof_path,f.submitted_at,false,'counted'
  FROM public.trip_season_finds f JOIN public.trip_season_games g ON g.id=f.game_id
  WHERE f.trip_id=p_trip AND f.user_id<>auth.uid() AND f.declined_at IS NULL AND trip_private.is_trip_member(p_trip,f.user_id)
 ) x ORDER BY x.submitted_at NULLS LAST, x.user_id;
END $$;


--
-- Name: sealed_quest_action(uuid, text, text, text, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sealed_quest_action(p_quest uuid, p_action text, p_mode text DEFAULT NULL::text, p_path text DEFAULT NULL::text, p_shared boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE q public.sealed_quests; v_cut timestamptz; v_kind text; v_meet timestamptz; v_me uuid:=auth.uid();
BEGIN
 SELECT * INTO q FROM public.sealed_quests WHERE id=p_quest FOR UPDATE;
 IF NOT FOUND OR v_me IS NULL OR NOT trip_private.is_trip_member(q.trip_id,v_me) THEN RAISE EXCEPTION 'Quest not found'; END IF;
 v_cut:=trip_private.quest_cutoff(q.trip_id);
 IF p_action='open' THEN
  IF q.user_id<>v_me OR q.kind<>'sealed' THEN RAISE EXCEPTION 'Quest not found'; END IF;
  IF q.opened_at IS NOT NULL THEN RETURN; END IF;
  IF now()>=least(q.drop_at+interval '3 days',v_cut) THEN RAISE EXCEPTION 'This quest expired'; END IF;
  UPDATE public.sealed_quests SET opened_at=now() WHERE id=q.id;
 ELSIF p_action='submit' THEN
  IF q.user_id<>v_me OR q.kind<>'sealed' THEN RAISE EXCEPTION 'Quest not found'; END IF;
  IF q.opened_at IS NULL OR q.submitted_at IS NOT NULL THEN RAISE EXCEPTION 'This quest can''t take proof'; END IF;
  IF now()>=least(q.opened_at+interval '24 hours',v_cut) THEN RAISE EXCEPTION 'Boarding closed — this quest self-destructed'; END IF;
  IF p_mode NOT IN ('upload','show') THEN RAISE EXCEPTION 'Choose a photo or show it at game night'; END IF;
  IF p_mode='upload' AND (p_path IS NULL OR split_part(p_path,'/',1)<>q.trip_id::text OR split_part(p_path,'/',2)<>q.user_id::text OR split_part(p_path,'/',3)<>q.id::text OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='quest-proofs' AND o.name=p_path)) THEN RAISE EXCEPTION 'Upload your photo first'; END IF;
  IF p_shared AND trip_private.a2c_minor_trip(q.trip_id) THEN RAISE EXCEPTION 'Quest proof cannot be shared with the squad'; END IF;
  UPDATE public.sealed_quests SET submitted_at=now(),proof_mode=p_mode,proof_path=CASE WHEN p_mode='upload' THEN p_path END,proof_shared=coalesce(p_shared,false) WHERE id=q.id;
 ELSIF p_action='share' THEN
  IF q.user_id<>v_me THEN RAISE EXCEPTION 'Quest not found'; END IF;
  IF p_shared AND trip_private.a2c_minor_trip(q.trip_id) THEN RAISE EXCEPTION 'Quest proof cannot be shared with the squad'; END IF;
  UPDATE public.sealed_quests SET proof_shared=coalesce(p_shared,false) WHERE id=q.id;
 ELSIF p_action IN ('decline','approve') THEN
  IF NOT trip_private.is_leader(q.trip_id) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can review quests'; END IF;
  IF q.user_id=v_me THEN RAISE EXCEPTION 'You can''t review your own quest'; END IF;
  IF q.declined_at IS NOT NULL OR q.approved_at IS NOT NULL AND p_action='approve' THEN RETURN; END IF;
  IF q.kind='sealed' THEN
   IF q.submitted_at IS NULL THEN RAISE EXCEPTION 'Nothing submitted yet'; END IF;
   IF p_action='decline' AND now()>=v_cut THEN RAISE EXCEPTION 'Reviews closed at the cutoff'; END IF;
   IF p_action='approve' AND (q.proof_mode<>'show' OR now()>=v_cut+interval '6 hours') THEN RAISE EXCEPTION 'Only game-night presentations need approval'; END IF;
  ELSIF p_action='approve' THEN
   SELECT kind INTO v_kind FROM public.trips WHERE id=q.trip_id;
   IF v_kind='trip' THEN
    SELECT ss.carry_on_meetup_at INTO v_meet FROM public.season_settings ss WHERE ss.trip_id=q.trip_id AND ss.season='trip';
    IF v_meet IS NULL OR now()<v_meet-interval '15 minutes' THEN RAISE EXCEPTION 'Showcases are approved at the crowning meet-up'; END IF;
   ELSIF now()<v_cut-interval '15 minutes' THEN RAISE EXCEPTION 'Showcases are approved at the finale'; END IF;
  END IF;
  IF p_action='decline' THEN UPDATE public.sealed_quests SET declined_at=now(),declined_by=v_me WHERE id=q.id;
  ELSE UPDATE public.sealed_quests SET approved_at=now(),approved_by=v_me WHERE id=q.id; END IF;
 ELSE RAISE EXCEPTION 'Unknown action'; END IF;
END $$;


--
-- Name: sealed_quest_state(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sealed_quest_state(p_trip uuid) RETURNS TABLE(id uuid, kind text, drop_no integer, value integer, drop_at timestamp with time zone, open_by timestamp with time zone, opened_at timestamp with time zone, destroy_at timestamp with time zone, cutoff timestamp with time zone, state text, title text, mission_text text, backstory text, keywords text[], proof_mode text, proof_shared boolean, submitted_at timestamp with time zone, points integer, meetup_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cut timestamptz; v_meet timestamptz;
BEGIN
 PERFORM trip_private.ensure_sealed(p_trip,auth.uid());
 v_cut:=trip_private.quest_cutoff(p_trip);
 SELECT ss.carry_on_meetup_at INTO v_meet FROM public.season_settings ss WHERE ss.trip_id=p_trip AND ss.season='trip';
 RETURN QUERY SELECT q.id,q.kind,q.drop_no,q.value,q.drop_at,least(q.drop_at+interval '3 days',v_cut),q.opened_at,
 CASE WHEN q.opened_at IS NULL THEN NULL ELSE least(q.opened_at+interval '24 hours',v_cut) END,v_cut,s.st,
 CASE WHEN s.vis THEN q.title END,CASE WHEN s.vis THEN q.mission_text END,CASE WHEN s.vis THEN q.backstory END,CASE WHEN s.vis THEN q.keywords END,
 q.proof_mode,CASE WHEN trip_private.a2c_minor_trip(p_trip) THEN false ELSE q.proof_shared END,q.submitted_at,trip_private.sealed_award(q),v_meet
 FROM public.sealed_quests q CROSS JOIN LATERAL (SELECT trip_private.sealed_state(q,v_cut) st) s0
 CROSS JOIN LATERAL (SELECT s0.st,(q.kind='showcase' OR (q.opened_at IS NOT NULL AND now()<least(q.opened_at+interval '24 hours',v_cut) AND s0.st IN ('open','counted','show_pending'))) vis) s
 WHERE q.trip_id=p_trip AND q.user_id=auth.uid() ORDER BY q.kind DESC,q.drop_no;
END $$;


--
-- Name: sealed_state(public.sealed_quests, timestamp with time zone); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sealed_state(q public.sealed_quests, p_cut timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
 SELECT CASE
  WHEN q.kind='showcase' THEN CASE WHEN q.approved_at IS NOT NULL THEN 'approved' WHEN q.declined_at IS NOT NULL THEN 'declined' ELSE 'showcase' END
  WHEN q.declined_at IS NOT NULL THEN 'declined'
  WHEN q.submitted_at IS NOT NULL AND (q.proof_mode='upload' OR q.approved_at IS NOT NULL) THEN 'counted'
  WHEN q.submitted_at IS NOT NULL THEN 'show_pending'
  WHEN q.opened_at IS NULL AND now() < least(q.drop_at + interval '3 days', p_cut) THEN 'sealed'
  WHEN q.opened_at IS NULL THEN 'expired'
  WHEN now() < least(q.opened_at + interval '24 hours', p_cut) THEN 'open'
  ELSE 'destroyed' END $$;


--
-- Name: season_game_decline(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_game_decline(p_find uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE f public.trip_season_finds;
BEGIN
 SELECT * INTO f FROM public.trip_season_finds WHERE id=p_find FOR UPDATE;
 IF NOT FOUND OR NOT trip_private.is_leader(f.trip_id) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can review proof'; END IF;
 IF f.user_id = auth.uid() THEN RAISE EXCEPTION 'You can''t review your own proof'; END IF;
 UPDATE public.trip_season_finds SET declined_at=now() WHERE id=f.id AND declined_at IS NULL;
 DELETE FROM trip_private.trip_speed_finishes WHERE trip_id=f.trip_id AND day_date=f.day_date AND user_id=f.user_id AND source='trip_season_finds';
END $$;


--
-- Name: season_game_points(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_game_points(p_trip uuid) RETURNS TABLE(user_id uuid, pts integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 WITH f AS (SELECT f.user_id, f.day_date, g.game, array_agg(f.slot) slots, count(*)::int n
   FROM public.trip_season_finds f JOIN public.trip_season_games g ON g.id=f.game_id
   WHERE f.trip_id=p_trip AND f.declined_at IS NULL GROUP BY f.user_id, f.day_date, g.game),
 d AS (SELECT f.user_id, CASE f.game
   WHEN 'bingo' THEN 2*f.n
     + CASE WHEN EXISTS (SELECT 1 FROM (VALUES (ARRAY[0,1,2]),(ARRAY[3,4,5]),(ARRAY[6,7,8]),(ARRAY[0,3,6]),(ARRAY[1,4,7]),(ARRAY[2,5,8]),(ARRAY[0,4,8]),(ARRAY[2,4,6])) l(s) WHERE l.s <@ f.slots) THEN 5 ELSE 0 END
     + CASE WHEN f.n >= 9 THEN 10 ELSE 0 END
   WHEN 'scavenger' THEN 4*least(f.n,5)
   ELSE 10 END p FROM f)
 SELECT d.user_id, sum(d.p)::int FROM d GROUP BY d.user_id $$;


--
-- Name: season_game_reveal(uuid, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_game_reveal(p_trip uuid, p_date date) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_at timestamptz;
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 IF NOT trip_private.season_games_ok(p_trip) THEN RAISE EXCEPTION 'Trip Season games are not part of this room'; END IF;
 IF p_date <> trip_private.trip_today(p_trip) THEN RAISE EXCEPTION 'This game opens on its day'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.trip_season_games WHERE trip_id=p_trip AND day_date=p_date) THEN RAISE EXCEPTION 'No game for today yet'; END IF;
 INSERT INTO public.trip_season_reveals(trip_id,day_date,user_id) VALUES (p_trip,p_date,auth.uid()) ON CONFLICT DO NOTHING;
 SELECT revealed_at INTO v_at FROM public.trip_season_reveals WHERE trip_id=p_trip AND day_date=p_date AND user_id=auth.uid();
 RETURN v_at;
END $$;


--
-- Name: season_game_submit(uuid, date, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_game_submit(p_trip uuid, p_date date, p_slot integer, p_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE g public.trip_season_games; v_me uuid := auth.uid(); v_rev timestamptz; v_n int; v_total int;
BEGIN
 IF v_me IS NULL OR NOT trip_private.is_trip_member(p_trip, v_me) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 IF NOT trip_private.season_games_ok(p_trip) THEN RAISE EXCEPTION 'Trip Season games are not part of this room'; END IF;
 IF p_date <> trip_private.trip_today(p_trip) THEN RAISE EXCEPTION 'This game closed at the end of its day'; END IF;
 SELECT * INTO g FROM public.trip_season_games WHERE trip_id=p_trip AND day_date=p_date;
 IF NOT FOUND THEN RAISE EXCEPTION 'No game for today yet'; END IF;
 v_total := jsonb_array_length(g.tasks);
 IF p_slot < 0 OR p_slot >= v_total THEN RAISE EXCEPTION 'Unknown task'; END IF;
 IF p_path IS NULL OR split_part(p_path,'/',1)<>p_trip::text OR split_part(p_path,'/',2)<>v_me::text OR split_part(p_path,'/',3)<>g.id::text
   OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id='quest-proofs' AND o.name=p_path) THEN RAISE EXCEPTION 'Upload your photo first'; END IF;
 SELECT revealed_at INTO v_rev FROM public.trip_season_reveals WHERE trip_id=p_trip AND day_date=p_date AND user_id=v_me;
 IF g.game IN ('scavenger','speed') AND v_rev IS NULL THEN RAISE EXCEPTION 'Reveal the task first'; END IF;
 INSERT INTO public.trip_season_finds(trip_id,game_id,day_date,user_id,slot,proof_path) VALUES (p_trip,g.id,p_date,v_me,p_slot,p_path)
  ON CONFLICT (trip_id,day_date,user_id,slot) DO NOTHING;
 IF NOT FOUND THEN RAISE EXCEPTION 'Already stamped'; END IF;
 SELECT count(*) INTO v_n FROM public.trip_season_finds WHERE trip_id=p_trip AND day_date=p_date AND user_id=v_me AND declined_at IS NULL;
 -- Reuse the existing speed-finish record: scavenger is judged by speed_bonus_ok (3h); speed only records when its own clock is beaten.
 IF g.game='scavenger' AND v_n >= v_total THEN
   INSERT INTO trip_private.trip_speed_finishes(trip_id,day_date,user_id,source,revealed_at,finished_at) VALUES (p_trip,p_date,v_me,'trip_season_finds',v_rev,now()) ON CONFLICT DO NOTHING;
 ELSIF g.game='speed' AND now() <= v_rev + make_interval(mins => coalesce(g.speed_minutes,60)) THEN
   INSERT INTO trip_private.trip_speed_finishes(trip_id,day_date,user_id,source,revealed_at,finished_at) VALUES (p_trip,p_date,v_me,'trip_season_finds',v_rev,now()) ON CONFLICT DO NOTHING;
 END IF;
END $$;


--
-- Name: season_games_ok(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_games_ok(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT EXISTS (SELECT 1 FROM public.trips t WHERE t.id=p_trip AND t.kind='trip' AND coalesce(t.season_scoring,true) AND coalesce(t.play_arrangement,'group')<>'offline') $$;


--
-- Name: season_info(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_info(p_trip uuid) RETURNS TABLE(season text, winners integer, prize text, crowning_at timestamp with time zone, crowning_label text, revealed boolean, crowning_mode text, prize_note text, takeoff_week integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
RETURN QUERY SELECT s.season, s.winners,
  CASE WHEN trip_private.is_leader(p_trip) OR coalesce(e.at <= now(), false) THEN s.prize ELSE NULL END,
  e.at, s.crowning_label, coalesce(e.at <= now(), false), s.crowning_mode,
  CASE WHEN trip_private.is_leader(p_trip) OR coalesce(e.at <= now(), false) THEN s.prize_note ELSE NULL END,
  trip_private.takeoff_week(p_trip)
FROM public.season_settings s CROSS JOIN LATERAL (SELECT trip_private.effective_crowning(p_trip, s.season) at) e WHERE s.trip_id = p_trip; END $$;


--
-- Name: season_points(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_points(p_trip uuid, p_season text) RETURNS TABLE(user_id uuid, games integer, quests integer, showcase integer, legacy integer, other integer, total integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_kind text;
BEGIN
 IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 IF p_season NOT IN ('preflight','trip','home') THEN RAISE EXCEPTION 'Unknown season'; END IF;
 SELECT t.kind INTO v_kind FROM public.trips t WHERE t.id=p_trip;
 RETURN QUERY
 WITH m AS (SELECT tm.user_id, tm.start_stamps FROM public.trip_members tm WHERE tm.trip_id=p_trip AND tm.status='approved'),
 sq AS (SELECT q.user_id, coalesce(sum(trip_private.sealed_award(q)) FILTER (WHERE q.kind='sealed'),0)::int qp, coalesce(sum(trip_private.sealed_award(q)) FILTER (WHERE q.kind='showcase'),0)::int sp FROM public.sealed_quests q WHERE q.trip_id=p_trip GROUP BY q.user_id),
 gn AS (SELECT s.user_id, sum(CASE WHEN s.here THEN 10 ELSE 0 END + CASE WHEN s.won THEN 15 WHEN s.here THEN 5 ELSE 0 END + CASE WHEN s.here AND n.host_id=s.user_id THEN 5 ELSE 0 END)::int pts
   FROM public.game_scores s JOIN public.game_nights n ON n.trip_id=s.trip_id AND n.week_number=s.week_number AND NOT n.skipped AND n.starts_at <= now()
   WHERE s.trip_id=p_trip GROUP BY s.user_id),
 qa AS (SELECT a.user_id, (2*count(*) + 4*count(*) FILTER (WHERE q.winner_id=a.user_id))::int pts FROM public.weekly_answers a JOIN public.weekly_questions q ON q.trip_id=a.trip_id AND q.week_number=a.week_number AND q.revealed_at IS NOT NULL WHERE a.trip_id=p_trip GROUP BY a.user_id),
 pen AS (SELECT hp.user_id, 5*sum(hp.stamps)::int pts FROM public.host_penalties hp WHERE hp.trip_id=p_trip GROUP BY hp.user_id),
 lg AS (SELECT x.user_id, sum(x.p)::int pts FROM (
   SELECT mc.user_id, mc.points p FROM public.mission_claims mc WHERE mc.trip_id=p_trip AND mc.phase='checkin' AND mc.status='released'
   UNION ALL SELECT sq2.user_id, sq2.awarded_points FROM public.season_quests sq2 WHERE sq2.trip_id=p_trip AND sq2.quest_kind='preflight' AND sq2.status='approved') x GROUP BY x.user_id),
 ts AS (SELECT r.user_id, r.stamps::int pts FROM trip_private.trip_season(p_trip) r WHERE p_season='trip'),
 sb AS (SELECT f.user_id, (5*count(*))::int pts FROM trip_private.trip_speed_finishes f WHERE f.trip_id=p_trip AND p_season='trip' AND trip_private.speed_bonus_ok(f.revealed_at,f.finished_at) GROUP BY f.user_id),
 sg AS (SELECT r.user_id, r.pts FROM trip_private.season_game_points(p_trip) r WHERE p_season='trip' AND trip_private.season_games_ok(p_trip)),
 tk AS (SELECT c.user_id, least(12, sum(c.points))::int pts FROM public.mission_claims c WHERE c.trip_id=p_trip AND c.phase='takeoff' AND c.status='released' AND p_season='trip' GROUP BY c.user_id),
 hs AS (SELECT r.user_id, r.points::int pts FROM trip_private.home_day_scores(p_trip) r WHERE p_season='home'),
 parts AS (
 SELECT m.user_id,
  CASE WHEN p_season='preflight' THEN coalesce(gn.pts,0)+coalesce(qa.pts,0)+5*coalesce(m.start_stamps,0)-coalesce(pen.pts,0) ELSE 0 END g,
  CASE WHEN p_season IN ('preflight','home') THEN coalesce(sq.qp,0) ELSE 0 END q,
  CASE WHEN (p_season='trip' AND v_kind='trip') OR (p_season='home' AND v_kind<>'trip') THEN coalesce(sq.sp,0) ELSE 0 END s,
  CASE WHEN p_season='preflight' THEN coalesce(lg.pts,0) ELSE 0 END l,
  coalesce(ts.pts,0)+coalesce(hs.pts,0)+coalesce(sb.pts,0)+coalesce(sg.pts,0)+coalesce(tk.pts,0) o
 FROM m LEFT JOIN sq ON sq.user_id=m.user_id LEFT JOIN gn ON gn.user_id=m.user_id LEFT JOIN qa ON qa.user_id=m.user_id
  LEFT JOIN pen ON pen.user_id=m.user_id LEFT JOIN lg ON lg.user_id=m.user_id LEFT JOIN ts ON ts.user_id=m.user_id LEFT JOIN hs ON hs.user_id=m.user_id LEFT JOIN sb ON sb.user_id=m.user_id LEFT JOIN sg ON sg.user_id=m.user_id LEFT JOIN tk ON tk.user_id=m.user_id)
 SELECT p.user_id, p.g::int, p.q::int, p.s::int, p.l::int, p.o::int, greatest(p.g+p.q+p.s+p.l+p.o,0)::int FROM parts p;
END $$;


--
-- Name: season_quest_action(uuid, uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_quest_action(p_trip uuid, p_quest uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE q public.season_quests; n public.game_nights; t public.trips; ss public.season_settings; BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 SELECT * INTO q FROM public.season_quests WHERE id=p_quest AND trip_id=p_trip FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Quest not found'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF q.quest_kind='preflight' THEN SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=q.night_week AND NOT skipped; IF NOT FOUND OR NOT trip_private.quest_unlocked(p_trip,q.night_week) THEN RAISE EXCEPTION 'This quest is not unlocked'; END IF; IF p_action IN ('approve','decline') AND NOT (trip_private.night_open(p_trip,q.night_week) OR now()>=n.starts_at) THEN RAISE EXCEPTION 'Present this quest on game night'; END IF;
 ELSE SELECT * INTO ss FROM public.season_settings WHERE trip_id=p_trip AND season='trip'; IF NOT trip_private.carry_quest_unlocked(p_trip) OR ss.carry_on_meetup_at IS NULL OR now()<ss.carry_on_meetup_at OR (now() AT TIME ZONE t.trip_timezone)::date NOT BETWEEN t.start_date AND t.end_date THEN RAISE EXCEPTION 'The Carry-On meet-up must happen during the Trip'; END IF; END IF;
 IF p_action='complete' THEN IF q.user_id<>auth.uid() OR q.status NOT IN ('new','declined') THEN RAISE EXCEPTION 'Only your open quest can be marked done'; END IF; UPDATE public.season_quests SET status='pending',presented_at=now() WHERE id=p_quest AND trip_id=p_trip;
 ELSIF p_action IN ('approve','decline') THEN IF NOT trip_private.is_leader(p_trip) OR q.user_id=auth.uid() THEN RAISE EXCEPTION 'Another Captain or Co-Captain must review this quest'; END IF; IF q.status<>'pending' THEN RAISE EXCEPTION 'Quest is not waiting for review'; END IF; IF p_action='approve' THEN IF q.quest_kind='preflight' AND EXISTS(SELECT 1 FROM public.season_champions WHERE trip_id=p_trip AND season='game') THEN RAISE EXCEPTION 'The Pre-Flight crown is already final'; END IF; UPDATE public.season_quests SET status='approved',approved_at=now(),approved_by=auth.uid(),awarded_points=points WHERE id=p_quest AND trip_id=p_trip; ELSE UPDATE public.season_quests SET status='declined',presented_at=NULL WHERE id=p_quest AND trip_id=p_trip; END IF;
 ELSE RAISE EXCEPTION 'Unknown quest action'; END IF; END $$;


--
-- Name: season_quest_approve_all(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_quest_approve_all(p_trip uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE r record; v_count integer:=0; BEGIN IF NOT trip_private.is_leader(p_trip) OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Only leaders can approve quests'; END IF; FOR r IN SELECT id FROM public.season_quests WHERE trip_id=p_trip AND status='pending' AND user_id<>auth.uid() ORDER BY presented_at FOR UPDATE LOOP PERFORM trip_private.season_quest_action(p_trip,r.id,'approve'); v_count:=v_count+1; END LOOP; RETURN v_count; END $$;


--
-- Name: season_quest_bonus(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_quest_bonus(p_trip uuid, p_kind text) RETURNS TABLE(user_id uuid, points integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF coalesce(current_setting('trip_private.crowning', true), '') <> 'on' AND NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF; IF p_kind NOT IN ('preflight','carry_on') THEN RAISE EXCEPTION 'Unknown quest kind'; END IF; RETURN QUERY SELECT m.user_id,CASE WHEN p_kind='carry_on' THEN least(5,coalesce(sum(q.awarded_points),0))::int ELSE least(least(12,greatest(10,(SELECT count(*)::int FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped))),coalesce(sum(q.awarded_points),0)+(SELECT coalesce(sum(c.points),0) FROM public.mission_claims c WHERE c.trip_id=p_trip AND c.user_id=m.user_id AND c.phase='checkin' AND c.status='released'))::int END FROM public.trip_members m LEFT JOIN public.season_quests q ON q.trip_id=m.trip_id AND q.user_id=m.user_id AND q.quest_kind=p_kind AND q.status='approved' WHERE m.trip_id=p_trip AND m.status='approved' GROUP BY m.user_id; END $$;


--
-- Name: season_quest_current(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_quest_current(p_trip uuid) RETURNS TABLE(id uuid, user_id uuid, kind text, night_week integer, title text, mission_text text, backstory text, keywords text[], points integer, status text, starts_at timestamp with time zone, place text, total integer, completed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 PERFORM trip_private.ensure_season_quests(p_trip,auth.uid());
 RETURN QUERY SELECT q.id,q.user_id,q.quest_kind,q.night_week,q.title,q.mission_text,q.backstory,q.keywords,q.points,q.status,CASE WHEN q.quest_kind='carry_on' THEN ss.carry_on_meetup_at ELSE n.starts_at END,CASE WHEN q.quest_kind='carry_on' THEN ss.carry_on_meetup_place ELSE coalesce(n.place,'Video call') END,(SELECT count(*)::int FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped),(SELECT count(*)::int FROM public.season_quests x WHERE x.trip_id=p_trip AND x.user_id=auth.uid() AND x.quest_kind='preflight' AND x.status='approved') FROM public.season_quests q LEFT JOIN public.game_nights n ON n.trip_id=q.trip_id AND n.week_number=q.night_week LEFT JOIN public.season_settings ss ON ss.trip_id=q.trip_id AND ss.season='trip' WHERE q.trip_id=p_trip AND q.user_id=auth.uid() AND ((q.quest_kind='carry_on' AND trip_private.carry_quest_unlocked(p_trip)) OR (q.quest_kind='preflight' AND trip_private.quest_unlocked(p_trip,q.night_week))) ORDER BY CASE WHEN q.status IN ('new','declined','pending') THEN 0 ELSE 1 END,CASE WHEN q.quest_kind='preflight' THEN 0 ELSE 1 END,q.night_week ASC NULLS LAST LIMIT 1;
 END $$;


--
-- Name: season_quest_review(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_quest_review(p_trip uuid) RETURNS TABLE(id uuid, user_id uuid, kind text, title text, points integer, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT trip_private.is_leader(p_trip) OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Only leaders can review quests'; END IF; RETURN QUERY SELECT q.id,q.user_id,q.quest_kind,q.title,q.points,q.status FROM public.season_quests q WHERE q.trip_id=p_trip AND q.status='pending' ORDER BY q.presented_at; END $$;


--
-- Name: season_start(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_start(p_trip uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT coalesce(t.game_start, greatest((now() AT TIME ZONE t.home_timezone)::date, t.start_date - 84)) FROM public.trips t WHERE t.id=p_trip $$;


--
-- Name: season_timing(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.season_timing(p_trip uuid) RETURNS TABLE(mode text, preflight_start date, cutoff timestamp with time zone, reveal_at timestamp with time zone, drop_count integer, finale_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; local_today date; days_total integer;
BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF t.season_rule<>'a2c' THEN RAISE EXCEPTION 'This room uses its original season'; END IF;
 local_today:=trip_private.trip_today(p_trip);
 days_total:=t.start_date-coalesce(t.game_start,(t.created_at AT TIME ZONE t.home_timezone)::date);
 IF t.kind='trip' THEN
   mode:=CASE WHEN t.start_date<=local_today THEN 'trip_season' WHEN t.game_plan='quick_start' THEN 'quick_start' ELSE 'preflight' END;
   preflight_start:=greatest(coalesce(t.game_start,local_today),t.start_date-10);
   cutoff:=trip_private.quest_cutoff(p_trip);
   reveal_at:=((t.start_date - 1 + time '23:59') AT TIME ZONE t.home_timezone);
   drop_count:=CASE WHEN t.start_date<=(t.created_at AT TIME ZONE t.home_timezone)::date THEN 0 WHEN t.game_plan='quick_start' THEN 1 WHEN days_total<7 THEN 2 ELSE 3 END;
   finale_at:=reveal_at;
 ELSE
   mode:='at_home';preflight_start:=t.game_start;finale_at:=t.finale_at;cutoff:=t.finale_at;reveal_at:=t.finale_at;
   drop_count:=CASE WHEN t.end_date-t.start_date<6 THEN 2 ELSE 3 END;
 END IF;
 RETURN NEXT;
END $$;


--
-- Name: seat_cap(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.seat_cap(p_trip uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN t.play_arrangement IS NULL THEN NULL WHEN trip_private.is_window_room(t.id) THEN 4 WHEN t.extra_seats THEN 12 ELSE 6 END FROM public.trips t WHERE t.id=p_trip $$;


--
-- Name: seed_adult_activities(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.seed_adult_activities() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NEW.tag<>'Travel' THEN INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative) VALUES(NEW.trip_id,NEW.day_date,'bingo',0,'Sip or skip: find a local drink in '||left(NEW.city,80)||' and share a toast with your squad (any drink counts).','Find a local soda, mocktail, tea, or street-food snack and share it with your squad.') ON CONFLICT(trip_id,day_date,kind) DO UPDATE SET prompt=excluded.prompt,alternative=excluded.alternative; END IF; IF NEW.tag IN ('Explore','Party') THEN INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative) VALUES(NEW.trip_id,NEW.day_date,'quest',0,'Sip or skip: discover a local beverage and take a squad photo with it (any drink counts).','Discover a local nonalcoholic drink or street-food snack and take a squad photo with it.') ON CONFLICT(trip_id,day_date,kind) DO UPDATE SET prompt=excluded.prompt,alternative=excluded.alternative; END IF; IF NEW.tag='Chill' THEN INSERT INTO public.trip_adult_activities(trip_id,day_date,kind,item_index,prompt,alternative,options) VALUES(NEW.trip_id,NEW.day_date,'trivia',0,'Sip or skip: which of these is always a nonalcoholic choice?','Which drink can everyone enjoy without alcohol?', '["Beer","Sparkling water","Wine","Cocktail"]'::jsonb) ON CONFLICT(trip_id,day_date,kind) DO UPDATE SET prompt=excluded.prompt,alternative=excluded.alternative,options=excluded.options; END IF; RETURN NEW; END $$;


--
-- Name: set_activity_timer(uuid, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_activity_timer(p_trip uuid, p_secs integer, p_label text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.require_feature(p_trip, 'host_timer');
  IF NOT (trip_private.is_leader(p_trip) OR trip_private.lab_bypass(p_trip) OR EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND host_id=auth.uid() AND NOT skipped AND starts_at BETWEEN now()-interval '4 hours' AND now()+interval '2 hours')) THEN RAISE EXCEPTION 'Only the host, Captain or Co-Captain can run the timer'; END IF;
  IF p_secs IS NOT NULL AND (p_secs < 5 OR p_secs > 3600) THEN RAISE EXCEPTION 'Pick 5 seconds to 60 minutes'; END IF;
  INSERT INTO public.trip_play_state(trip_id, timer_ends_at, timer_secs, timer_label) VALUES (p_trip, CASE WHEN p_secs IS NULL THEN NULL ELSE now() + make_interval(secs => p_secs) END, p_secs, left(nullif(trim(p_label),''),60))
  ON CONFLICT (trip_id) DO UPDATE SET timer_ends_at=excluded.timer_ends_at, timer_secs=excluded.timer_secs, timer_label=excluded.timer_label, updated_at=now();
END $$;


--
-- Name: set_adult_cards(uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_adult_cards(p_trip uuid, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Captain only'; END IF;
 INSERT INTO public.trip_adult_settings(trip_id,enabled) VALUES(p_trip,p_enabled) ON CONFLICT(trip_id) DO UPDATE SET enabled=excluded.enabled;
 UPDATE public.trips SET vibe = CASE WHEN p_enabled THEN 'party' WHEN vibe='party' THEN 'chill' ELSE vibe END WHERE id=p_trip; END $$;


--
-- Name: set_ai_guard(boolean, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_ai_guard(p_enabled boolean, p_global_cap integer, p_user_cap integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE o jsonb;
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  IF p_global_cap IS NOT NULL AND (p_global_cap < 0 OR p_global_cap > 100000) THEN RAISE EXCEPTION 'Daily cap must be 0–100000'; END IF;
  IF p_user_cap IS NOT NULL AND (p_user_cap < 0 OR p_user_cap > 1000) THEN RAISE EXCEPTION 'Per-person cap must be 0–1000'; END IF;
  SELECT jsonb_build_object('enabled', ai_enabled, 'global', ai_daily_global_cap, 'user', ai_daily_user_cap) INTO o FROM public.app_settings LIMIT 1;
  UPDATE public.app_settings SET ai_enabled = coalesce(p_enabled, ai_enabled),
    ai_daily_global_cap = coalesce(p_global_cap, ai_daily_global_cap),
    ai_daily_user_cap = coalesce(p_user_cap, ai_daily_user_cap), ai_updated_at = now()
  WHERE id;
  INSERT INTO trip_private.ai_guard_log(actor, old_value, new_value)
  SELECT auth.uid(), o, jsonb_build_object('enabled', ai_enabled, 'global', ai_daily_global_cap, 'user', ai_daily_user_cap) FROM public.app_settings LIMIT 1;
END $$;


--
-- Name: set_bingo_needs_photo(uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_bingo_needs_photo(p_trip uuid, p_required boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Captain only'; END IF;
 UPDATE public.trips SET bingo_needs_photo=coalesce(p_required,true) WHERE id=p_trip;
END $$;


--
-- Name: set_boarding_tile(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_boarding_tile(p_tile text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  IF p_tile NOT IN ('current','a','b') THEN RAISE EXCEPTION 'Pick A, B or current'; END IF;
  UPDATE public.app_settings SET boarding_tile=p_tile WHERE id;
END $$;


--
-- Name: set_carry_on_meetup(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_carry_on_meetup(p_trip uuid, p_at timestamp with time zone, p_place text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t public.trips; BEGIN IF NOT trip_private.is_captain(p_trip) OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Only the Captain can schedule the meet-up'; END IF; SELECT * INTO t FROM public.trips WHERE id=p_trip; IF t.kind='at_home' OR p_at IS NULL OR p_place IS NULL OR length(trim(p_place)) NOT BETWEEN 2 AND 160 OR (p_at AT TIME ZONE t.trip_timezone)::date NOT BETWEEN t.start_date AND t.end_date THEN RAISE EXCEPTION 'Choose a time and place during the Trip'; END IF; IF NOT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped HAVING p_at>max(n.starts_at)+interval '3 hours 30 minutes') THEN RAISE EXCEPTION 'Schedule the meet-up after Final Call Night'; END IF; INSERT INTO public.season_settings(trip_id,season,carry_on_meetup_at,carry_on_meetup_place) VALUES(p_trip,'trip',p_at,trim(p_place)) ON CONFLICT(trip_id,season) DO UPDATE SET carry_on_meetup_at=excluded.carry_on_meetup_at,carry_on_meetup_place=excluded.carry_on_meetup_place WHERE season_settings.trip_id=p_trip AND season_settings.season='trip'; END $$;


--
-- Name: set_culture_finale(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_culture_finale(p_exp uuid, p_format text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences;
BEGIN
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp FOR UPDATE;
 IF NOT FOUND OR e.creator_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Not your experience'; END IF;
 IF e.started_at IS NOT NULL THEN RAISE EXCEPTION 'This experience has already started'; END IF;
 IF e.track='home' AND (e.days < 2 OR e.days > 7) THEN RAISE EXCEPTION 'Pick 2–7 days'; END IF;
 IF coalesce(e.play_mode,'group')='solo' THEN
   UPDATE public.culture_experiences SET finale_format=NULL WHERE id=p_exp; RETURN;
 END IF;
 IF p_format NOT IN ('two_nights','finale_only') THEN RAISE EXCEPTION 'Pick a finale format'; END IF;
 IF p_format='two_nights' AND e.days < 4 THEN RAISE EXCEPTION 'Two game nights need 4 or more days'; END IF;
 UPDATE public.culture_experiences SET finale_format=p_format WHERE id=p_exp;
END $$;


--
-- Name: set_culture_mode(uuid, text, text[], text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_culture_mode(p_exp uuid, p_mode text, p_types text[], p_vibe text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences; a int := coalesce(trip_private.age_of(auth.uid()),0); v_types text[];
BEGIN
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp FOR UPDATE;
 IF NOT FOUND OR e.creator_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Not your experience'; END IF;
 IF e.started_at IS NOT NULL OR EXISTS (SELECT 1 FROM public.solo_quests q WHERE q.experience_id=p_exp) THEN RAISE EXCEPTION 'This experience has already started'; END IF;
 IF p_mode NOT IN ('group','solo') THEN RAISE EXCEPTION 'Choose Solo or With others'; END IF;
 IF p_vibe IS NOT NULL AND p_vibe NOT IN ('family','chill','party') THEN RAISE EXCEPTION 'Pick a vibe'; END IF;
 IF p_vibe='party' AND a<21 THEN RAISE EXCEPTION 'Party vibe is 21+'; END IF;
 IF a<18 AND p_vibe IS DISTINCT FROM 'family' AND p_vibe IS NOT NULL THEN RAISE EXCEPTION 'Players under 18 use Family content'; END IF;
 v_types := ARRAY(SELECT DISTINCT x FROM unnest(coalesce(p_types,'{}')) x);
 IF cardinality(v_types) > 2 THEN RAISE EXCEPTION 'Pick up to 2 traveler types'; END IF;
 IF EXISTS (SELECT 1 FROM unnest(v_types) x WHERE x NOT IN ('foodie','explorer','culture','chill','photographer','night_owl','shopper')) THEN RAISE EXCEPTION 'Unknown traveler type'; END IF;
 IF 'night_owl' = ANY(v_types) AND a<21 THEN RAISE EXCEPTION 'Night owl is 21+'; END IF;
 UPDATE public.culture_experiences SET play_mode=p_mode, traveler_types=CASE WHEN p_mode='solo' THEN v_types ELSE '{}' END, vibe=coalesce(p_vibe, CASE WHEN a<18 THEN 'family' ELSE 'chill' END),
   trip_id=CASE WHEN p_mode='solo' THEN NULL ELSE trip_id END, visibility=CASE WHEN p_mode='solo' AND visibility='squad' THEN 'private' ELSE visibility END
 WHERE id=p_exp;
END $$;


--
-- Name: set_first_game(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_first_game(p_trip uuid, p_game integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can choose the first game'; END IF; IF p_game IS NULL OR NOT EXISTS(SELECT 1 FROM public.game_catalog WHERE number=p_game) THEN RAISE EXCEPTION 'Choose a game'; END IF; UPDATE public.game_nights SET game_number=p_game WHERE trip_id=p_trip AND week_number=1 AND game_number IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Week 1 already has a game or schedule is missing'; END IF; INSERT INTO public.trip_play_state(trip_id,used_games) VALUES(p_trip,ARRAY[p_game]) ON CONFLICT(trip_id) DO UPDATE SET used_games=array_append(array_remove(trip_play_state.used_games,p_game),p_game); END $$;


--
-- Name: set_founding_open(boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_founding_open(p_open boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF; IF p_open IS NULL THEN RAISE EXCEPTION 'Choose open or closed'; END IF; UPDATE public.app_settings SET founding_open=p_open,founding_closed_at=CASE WHEN p_open THEN NULL ELSE coalesce(founding_closed_at,now()) END WHERE id; END $$;


--
-- Name: set_game_days(uuid, integer, date[], boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_game_days(p_trip uuid, p_every integer, p_rest date[], p_surprise boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only trip leaders can change game days'; END IF;
IF p_every IS NOT NULL AND p_every NOT IN (1,2) THEN RAISE EXCEPTION 'Pick every day or every other day'; END IF;
UPDATE public.trips SET game_days_every=p_every, rest_days=coalesce((SELECT array_agg(DISTINCT d) FROM unnest(p_rest) d WHERE d BETWEEN start_date AND end_date),'{}'), surprise_mode=coalesce(p_surprise,false) WHERE id=p_trip; END $$;


--
-- Name: set_game_night_host(uuid, integer, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_game_night_host(p_trip uuid, p_week integer, p_host uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can change hosts'; END IF; IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_host) THEN RAISE EXCEPTION 'Choose a member of this trip'; END IF; UPDATE public.game_nights SET host_id=p_host WHERE trip_id=p_trip AND week_number=p_week; END $$;


--
-- Name: set_game_night_place(uuid, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_game_night_place(p_trip uuid, p_week integer, p_place text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only trip leaders can set the meeting place'; END IF;
 IF char_length(coalesce(p_place,'')) > 80 THEN RAISE EXCEPTION 'Place must be 80 characters or less'; END IF;
 UPDATE public.game_nights SET place = nullif(trim(p_place),'') WHERE trip_id=p_trip AND week_number=p_week AND starts_at>now() AND NOT skipped;
 IF NOT FOUND THEN RAISE EXCEPTION 'This game night can no longer be changed'; END IF;
END $$;


--
-- Name: set_home_day_place(uuid, date, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_home_day_place(p_trip uuid, p_day date, p_place text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can set the meeting place'; END IF;
 IF char_length(coalesce(p_place,'')) > 80 THEN RAISE EXCEPTION 'Place must be 80 characters or less'; END IF;
 UPDATE public.home_day_sessions SET place=nullif(trim(p_place),'') WHERE trip_id=p_trip AND day_date=p_day AND starts_at>now() AND step='card';
 IF NOT FOUND THEN RAISE EXCEPTION 'This Game Day can no longer be changed'; END IF;
END $$;


--
-- Name: set_home_ready_start(uuid, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_home_ready_start(p_trip uuid, p_start date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can set Get Ready'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip FOR UPDATE;
 IF NOT FOUND OR t.kind NOT IN ('at_home','cultural_inspiration') OR p_start IS NULL OR p_start < (now() AT TIME ZONE t.home_timezone)::date OR p_start > t.start_date-1 THEN RAISE EXCEPTION 'Choose a Get Ready date before Day 1'; END IF;
 UPDATE public.trips SET game_start=p_start WHERE id=p_trip;
END $$;


--
-- Name: set_join_controls(uuid, boolean, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_join_controls(p_trip uuid, p_locked boolean, p_max integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE o public.trips%ROWTYPE; BEGIN
  IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Captain only'; END IF;
  IF p_max IS NOT NULL AND (p_max < 2 OR p_max > 40) THEN RAISE EXCEPTION 'Max squad size must be 2 to 40'; END IF;
  SELECT * INTO o FROM public.trips WHERE id=p_trip FOR UPDATE;
  UPDATE public.trips SET join_locked=coalesce(p_locked,join_locked), max_squad=coalesce(p_max,max_squad) WHERE id=p_trip;
  IF p_locked IS NOT NULL AND p_locked <> o.join_locked THEN
    INSERT INTO public.trip_role_changes(trip_id, role, reason, actor) VALUES (p_trip, 'join_settings', CASE WHEN p_locked THEN 'Joining locked' ELSE 'Joining unlocked' END, auth.uid()); END IF;
  IF p_max IS NOT NULL AND p_max <> o.max_squad THEN
    INSERT INTO public.trip_role_changes(trip_id, role, reason, actor) VALUES (p_trip, 'join_settings', 'Max squad size '||o.max_squad||' → '||p_max, auth.uid()); END IF;
END $$;


--
-- Name: set_my_dob(date, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_my_dob(p_dob date, p_agree boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a int;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 IF NOT coalesce(p_agree,false) THEN RAISE EXCEPTION 'Please confirm your birthday and agree'; END IF;
 IF p_dob IS NULL OR p_dob > current_date OR p_dob < date '1900-01-01' THEN RAISE EXCEPTION 'Check your date of birth'; END IF;
 a := extract(year FROM age(current_date,p_dob))::int;
 IF a < 13 THEN RAISE EXCEPTION 'Family Mode is coming soon. TripJunkies accounts are for ages 13 and up.'; END IF;
 IF EXISTS (SELECT 1 FROM public.player_private WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Your birthday is already saved; contact support for corrections'; END IF;
 INSERT INTO public.player_private(user_id,dob) VALUES(auth.uid(),p_dob);
 IF a >= 18 AND (SELECT public_launch FROM public.app_settings LIMIT 1) THEN INSERT INTO public.beta_access(user_id,source) VALUES(auth.uid(),'launch') ON CONFLICT DO NOTHING; END IF;
 RETURN trip_private.age_range(a);
END $$;


