-- Name: set_night_skipped(uuid, integer, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_night_skipped(p_trip uuid, p_week integer, p_skipped boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
