-- Name: set_pay_note(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_pay_note(p_trip uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can change this'; END IF;
  UPDATE public.trips SET pay_note=nullif(left(trim(coalesce(p_note,'')),200),'') WHERE id=p_trip;
  PERFORM trip_private.log_cost(p_trip, NULL, NULL, 'updated how to pay', NULL, left(trim(coalesce(p_note,'')),200));
END $$;


--
-- Name: set_preflight_a2c(uuid, date, integer, time without time zone); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_preflight_a2c(p_trip uuid, p_start date, p_weekday integer, p_time time without time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; today_local date; final_day date; first_day date; first_at timestamptz; call_at timestamptz; total integer:=0;
BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can set Pre-Flight'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip FOR UPDATE;
 IF NOT FOUND OR t.season_rule<>'a2c' OR t.kind<>'trip' THEN RAISE EXCEPTION 'This room uses its original plan'; END IF;
 today_local:=(now() AT TIME ZONE t.home_timezone)::date;
 IF p_time IS NULL OR p_weekday NOT BETWEEN 0 AND 6 THEN RAISE EXCEPTION 'Choose a night and time'; END IF;
 IF t.start_date<=today_local THEN RETURN 0; END IF;
 IF EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip) THEN RAISE EXCEPTION 'This Trip already has game nights'; END IF;
 IF t.start_date=today_local+1 THEN
   call_at:=(today_local+p_time) AT TIME ZONE t.home_timezone;
   IF call_at<=now() THEN call_at:=now()+interval '10 minutes'; END IF;
   IF call_at >= (t.start_date::timestamp AT TIME ZONE t.home_timezone) THEN RAISE EXCEPTION 'No call time remains before departure'; END IF;
   UPDATE public.trips SET game_start=today_local,game_plan='quick_start' WHERE id=p_trip AND season_rule='a2c';
 ELSE
   IF p_start IS NULL OR p_start<greatest(today_local,t.start_date-10) OR p_start>t.start_date-2 THEN RAISE EXCEPTION 'Choose a date within ten days of departure'; END IF;
   final_day:=t.start_date-2;
   call_at:=(final_day+p_time) AT TIME ZONE t.home_timezone;
   IF call_at<=now() THEN call_at:=now()+interval '10 minutes'; END IF;
   IF final_day-p_start>=6 THEN
     first_day:=p_start+((p_weekday-extract(dow FROM p_start)::int+7)%7);
     IF first_day>=final_day THEN first_day:=p_start+greatest(1,(final_day-p_start)/2); END IF;
     first_at:=(first_day+p_time) AT TIME ZONE t.home_timezone;
     IF first_at<=now() THEN first_at:=now()+interval '10 minutes'; END IF;
     IF first_at<call_at THEN
       INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(p_trip,1,first_at,auth.uid());
       total:=1;
     END IF;
   END IF;
   UPDATE public.trips SET game_start=p_start,game_plan='recommended' WHERE id=p_trip AND season_rule='a2c';
 END IF;
 INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(p_trip,total+1,call_at,auth.uid());
 RETURN total+1;
END $$;


--
-- Name: set_preflight_start(uuid, date, text, integer, time without time zone, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_preflight_start(p_trip uuid, p_start date, p_plan text, p_weekday integer, p_time time without time zone, p_every integer, p_count integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; v_today date; v_count int;
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can set Pre-Flight'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip FOR UPDATE;
 IF NOT FOUND OR t.kind='at_home' THEN RAISE EXCEPTION 'Choose a real trip'; END IF;
 v_today := (now() AT TIME ZONE t.home_timezone)::date;
 IF p_start IS NULL OR p_start < v_today OR p_start > t.start_date-2 THEN RAISE EXCEPTION 'Choose a Pre-Flight date before departure'; END IF;
 IF p_plan NOT IN ('recommended','short','custom') OR p_weekday NOT BETWEEN 0 AND 6 OR p_time IS NULL THEN RAISE EXCEPTION 'Choose a game plan, day and time'; END IF;
 UPDATE public.trips SET game_start=p_start WHERE id=p_trip;
 SELECT trip_private.apply_game_plan(p_trip,p_plan,p_weekday,p_time,p_start,p_every,p_count) INTO v_count;
 UPDATE public.trips SET game_start=p_start WHERE id=p_trip;
 RETURN v_count;
END $$;


--
-- Name: set_public_launch(boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_public_launch(p_on boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
 UPDATE public.app_settings SET public_launch=coalesce(p_on,false), updated_at=now() WHERE id; END $$;


--
-- Name: set_public_leaderboard(boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_public_leaderboard(p_public boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE allowed boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; allowed := coalesce(p_public,false) AND coalesce(trip_private.age_of(auth.uid()),0) >= 18; UPDATE public.player_profiles SET public_leaderboard=allowed WHERE user_id=auth.uid(); RETURN allowed; END $$;


--
-- Name: set_room_listing(uuid, boolean, text, text, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_room_listing(p_trip uuid, p_listed boolean, p_nickname text, p_country text, p_region text, p_city text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can list this squad'; END IF;
  IF EXISTS (SELECT 1 FROM trips WHERE id=p_trip AND is_sandbox) AND p_listed THEN RAISE EXCEPTION 'Test Lab trips can''t be listed'; END IF;
  IF p_listed AND (length(trim(coalesce(p_nickname,''))) < 2 OR p_country IS NULL) THEN RAISE EXCEPTION 'Add a room nickname and country first'; END IF;
  IF length(coalesce(p_nickname,'')) > 40 OR (p_country IS NOT NULL AND p_country !~ '^[A-Z]{2}$') THEN RAISE EXCEPTION 'Check the nickname and place'; END IF;
  UPDATE trips SET room_listed=p_listed, room_nickname=nullif(trim(p_nickname),''), room_country=p_country,
    room_region=nullif(trim(coalesce(p_region,'')),''), room_city=nullif(trim(coalesce(p_city,'')),'') WHERE id=p_trip;
END $_$;


--
-- Name: set_season(uuid, text, integer, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_season(p_trip uuid, p_season text, p_winners integer, p_prize text, p_crowning_at timestamp with time zone, p_label text, p_mode text, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_mode text := coalesce(nullif(p_mode,''),'custom'); BEGIN
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can set prizes'; END IF;
IF EXISTS (SELECT 1 FROM public.season_champions WHERE trip_id=p_trip AND season=p_season) THEN RAISE EXCEPTION 'This season is already crowned'; END IF;
IF p_season='trip' THEN v_mode := 'custom'; END IF;
IF v_mode NOT IN ('takeoff','departure','custom') THEN RAISE EXCEPTION 'Unknown crowning option'; END IF;
IF v_mode='custom' AND p_crowning_at IS NULL THEN RAISE EXCEPTION 'Pick a crowning date and time'; END IF;
INSERT INTO public.season_settings(trip_id, season, winners, prize, crowning_at, crowning_label, crowning_mode, prize_note)
VALUES (p_trip, p_season, p_winners, trim(coalesce(p_prize,'')), CASE WHEN v_mode='custom' THEN p_crowning_at END, trim(coalesce(p_label,'')), v_mode, left(trim(coalesce(p_note,'')),300))
ON CONFLICT (trip_id, season) DO UPDATE SET winners=EXCLUDED.winners, prize=EXCLUDED.prize, crowning_at=EXCLUDED.crowning_at, crowning_label=EXCLUDED.crowning_label, crowning_mode=EXCLUDED.crowning_mode, prize_note=EXCLUDED.prize_note; END $$;


--
-- Name: set_song_disc(uuid, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_song_disc(p_trip uuid, p_title text, p_artist text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.require_feature(p_trip, 'sing_off');
  IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
  IF p_title IS NULL OR length(trim(p_title))=0 THEN DELETE FROM public.song_discs WHERE trip_id=p_trip AND user_id=auth.uid(); RETURN; END IF;
  IF length(trim(p_title)) > 80 OR length(trim(coalesce(p_artist,''))) NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'Add a song title and artist'; END IF;
  INSERT INTO public.song_discs(trip_id,user_id,title,artist) VALUES (p_trip,auth.uid(),trim(p_title),trim(p_artist))
  ON CONFLICT (trip_id,user_id) DO UPDATE SET title=excluded.title, artist=excluded.artist, created_at=now();
END $$;


--
-- Name: set_stamp_values(uuid, integer, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_stamp_values(p_trip uuid, p_here integer, p_win integer, p_host integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can change stamp values'; END IF;
INSERT INTO public.stamp_settings(trip_id,here_stamps,win_stamps,host_stamps) VALUES (p_trip,p_here,p_win,p_host) ON CONFLICT (trip_id) DO UPDATE SET here_stamps=EXCLUDED.here_stamps, win_stamps=EXCLUDED.win_stamps, host_stamps=EXCLUDED.host_stamps; END $$;


--
-- Name: set_team_mode(uuid, text, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_team_mode(p_trip uuid, p_mode text, p_caps jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE k text; BEGIN PERFORM trip_private.require_feature(p_trip, 'teams');
 IF NOT trip_private.can_manage_teams(p_trip) THEN RAISE EXCEPTION 'Only the Captain can change team settings'; END IF;
 IF p_mode NOT IN ('assign','pick') THEN RAISE EXCEPTION 'Pick a team mode'; END IF;
 UPDATE public.trips SET team_mode=p_mode WHERE id=p_trip;
 FOR k IN SELECT jsonb_object_keys(coalesce(p_caps,'{}'::jsonb)) LOOP
   UPDATE public.trip_teams SET capacity=nullif(p_caps->>k,'')::int WHERE id=k::uuid AND trip_id=p_trip;
 END LOOP;
END $$;


--
-- Name: set_team_room(uuid, uuid, text, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_team_room(p_trip uuid, p_team uuid, p_call text, p_host uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only trip leaders can set team rooms'; END IF;
IF p_call IS NOT NULL AND length(trim(p_call))>0 AND trim(p_call) !~ '^https://' THEN RAISE EXCEPTION 'Call links must start with https://'; END IF;
IF p_host IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.trip_team_members WHERE trip_id=p_trip AND team_id=p_team AND user_id=p_host) THEN RAISE EXCEPTION 'The host must be on that team'; END IF;
UPDATE public.trip_teams SET call_link=nullif(trim(p_call),''), host_id=p_host WHERE id=p_team AND trip_id=p_trip;
IF NOT FOUND THEN RAISE EXCEPTION 'Team not found'; END IF; END $$;


--
-- Name: set_teen_dob(date, boolean, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_teen_dob(p_dob date, p_agree boolean, p_invite text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a int; inv public.trip_invites%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 IF NOT coalesce(p_agree,false) THEN RAISE EXCEPTION 'Please confirm and agree'; END IF;
 IF p_dob IS NULL OR p_dob > current_date OR p_dob < date '1900-01-01' THEN RAISE EXCEPTION 'Check your date of birth'; END IF;
 a := extract(year FROM age(current_date,p_dob))::int;
 IF a < 13 THEN RAISE EXCEPTION 'Family Mode is coming soon. TripJunkies accounts are for ages 13 and up.'; END IF;
 IF a >= 18 THEN RETURN trip_private.set_my_dob(p_dob, p_agree); END IF;
 IF EXISTS (SELECT 1 FROM public.player_private WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Your birthday is already saved; contact support for corrections'; END IF;
 SELECT * INTO inv FROM public.trip_invites WHERE token=upper(trim(coalesce(p_invite,''))) FOR UPDATE;
 INSERT INTO public.player_private(user_id,dob) VALUES(auth.uid(),p_dob);
 IF FOUND AND inv.teen AND inv.guardian_confirmed_at IS NOT NULL AND inv.used_at IS NULL AND inv.cancelled_at IS NULL AND inv.expires_at > now() THEN
   INSERT INTO trip_private.teen_accounts(user_id,invite_id,trip_id) VALUES(auth.uid(),inv.id,inv.trip_id) ON CONFLICT DO NOTHING;
 END IF;
 RETURN trip_private.age_range(a);
END $$;


--
-- Name: set_trip_access(uuid, boolean, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_trip_access(p_trip uuid, p_code_enabled boolean, p_require_approval boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Captain only'; END IF;
 UPDATE public.trips SET join_code_enabled=coalesce(p_code_enabled,join_code_enabled), require_approval=coalesce(p_require_approval,require_approval) WHERE id=p_trip; END $$;


--
-- Name: set_trip_archived(uuid, boolean, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_trip_archived(p_trip uuid, p_archived boolean, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'App admins only'; END IF;
  UPDATE public.trips SET rules_version = CASE WHEN p_archived THEN 1 ELSE 2 END
  WHERE id = p_trip AND rules_version <> CASE WHEN p_archived THEN 1 ELSE 2 END;
  IF FOUND THEN
    INSERT INTO trip_private.trip_archive_log (trip_id, archived, changed_by, note)
    VALUES (p_trip, p_archived, auth.uid(), p_note);
  END IF;
END $$;


--
-- Name: set_trip_extras(uuid, text, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_trip_extras(p_trip uuid, p_motto text, p_call text, p_backup text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only trip leaders can edit details'; END IF;
  IF length(coalesce(p_motto,'')) > 60 THEN RAISE EXCEPTION 'Keep the motto to 60 characters'; END IF;
  IF nullif(trim(coalesce(p_call,'')),'') IS NOT NULL AND trim(p_call) !~* '^https://' THEN RAISE EXCEPTION 'Call links should start with https://'; END IF;
  IF nullif(trim(coalesce(p_backup,'')),'') IS NOT NULL AND trim(p_backup) !~* '^https://' THEN RAISE EXCEPTION 'Call links should start with https://'; END IF;
  UPDATE public.trips SET motto=nullif(trim(coalesce(p_motto,'')),''), call_link=nullif(trim(coalesce(p_call,'')),''), backup_call_link=nullif(trim(coalesce(p_backup,'')),'') WHERE id=p_trip;
END $$;


--
-- Name: set_trip_minors(uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_trip_minors(p_trip uuid, p_has boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips;
BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Captain only'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip FOR UPDATE;
 IF t.season_rule IS DISTINCT FROM 'a2c' THEN RAISE EXCEPTION 'This setting is for new trips'; END IF;
 IF coalesce(p_has,false) THEN
   UPDATE public.trips SET vibe='family', has_minors=true WHERE id=p_trip;
   UPDATE public.trip_adult_settings SET enabled=false WHERE trip_id=p_trip;
 ELSE
   IF trip_private.has_teen_member(p_trip) THEN RAISE EXCEPTION 'A player under 18 is in this trip'; END IF;
   UPDATE public.trips SET has_minors=false WHERE id=p_trip;
 END IF;
END $$;


--
-- Name: set_trip_timezone(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_trip_timezone(p_trip uuid, p_tz text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can change the trip time zone'; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = p_tz) THEN RAISE EXCEPTION 'Pick a valid time zone'; END IF;
 UPDATE public.trips SET trip_timezone = p_tz WHERE id = p_trip; END $$;


--
-- Name: set_trip_vibe(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_trip_vibe(p_trip uuid, p_vibe text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Captain only'; END IF;
 IF p_vibe NOT IN ('family','chill','party') THEN RAISE EXCEPTION 'Pick Family, Chill or Party'; END IF;
 IF p_vibe<>'family' AND EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND has_minors) THEN RAISE EXCEPTION 'MINORS_FAMILY: Trips with players under 18 use Family content only'; END IF;
 UPDATE public.trips SET vibe=p_vibe WHERE id=p_trip;
 INSERT INTO public.trip_adult_settings(trip_id,enabled) VALUES(p_trip,p_vibe='party') ON CONFLICT(trip_id) DO UPDATE SET enabled=excluded.enabled; END $$;


--
-- Name: set_weekly_question(uuid, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_weekly_question(p_trip uuid, p_week integer, p_prompt text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE q public.weekly_questions; BEGIN PERFORM trip_private.require_feature(p_trip, 'qotw');
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can change the question'; END IF;
SELECT * INTO q FROM public.weekly_questions WHERE trip_id=p_trip AND week_number=p_week;
IF NOT FOUND THEN RAISE EXCEPTION 'That question isn''t scheduled yet'; END IF;
IF q.drops_at <= now() THEN RAISE EXCEPTION 'This question already dropped'; END IF;
IF p_prompt IS NULL OR length(trim(p_prompt))=0 THEN UPDATE public.weekly_questions SET prompt=trip_private.pick_weekly_prompt(p_trip), source='pool' WHERE trip_id=p_trip AND week_number=p_week;
ELSE IF length(trim(p_prompt)) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'Keep it between 3 and 200 characters'; END IF;
 UPDATE public.weekly_questions SET prompt=trim(p_prompt), source='custom' WHERE trip_id=p_trip AND week_number=p_week; END IF; END $$;


--
-- Name: set_welcome_copy(text, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_welcome_copy(p_intro text, p_faq jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
 IF length(trim(p_intro)) NOT BETWEEN 10 AND 600 OR jsonb_typeof(p_faq)<>'array' OR jsonb_array_length(p_faq) NOT BETWEEN 5 AND 6 OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_faq) x WHERE length(trim(x->>'q')) NOT BETWEEN 4 AND 120 OR length(trim(x->>'a')) NOT BETWEEN 5 AND 500) THEN RAISE EXCEPTION 'Add a founder note and five or six questions with answers'; END IF;
 UPDATE public.app_settings SET founder_intro=trim(p_intro),welcome_faq=p_faq,updated_at=now() WHERE id=true;
END $$;


--
-- Name: set_wheels_up(uuid, date, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_wheels_up(p_trip uuid, p_date date, p_time text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$ BEGIN
IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can do this'; END IF;
IF p_time !~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'Enter a time like 14:35'; END IF;
UPDATE public.trip_day_games SET wheels_up=p_time WHERE trip_id=p_trip AND day_date=p_date; END $_$;


--
-- Name: set_window_prep(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.set_window_prep(p_exp uuid, p_days integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp FOR UPDATE;
 IF NOT FOUND OR e.creator_id<>auth.uid() THEN RAISE EXCEPTION 'Only the creator can set preparation'; END IF;
 IF e.track<>'travel' OR e.started_at IS NOT NULL OR e.finished_at IS NOT NULL THEN RAISE EXCEPTION 'Preparation can only be set on a new Window Seat experience'; END IF;
 IF e.prep_days IS NOT NULL THEN RAISE EXCEPTION 'Preparation is already set'; END IF;
 IF p_days IS NOT NULL AND p_days NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'Choose up to ten preparation days'; END IF;
 UPDATE public.culture_experiences SET prep_days=p_days,updated_at=now() WHERE id=p_exp AND creator_id=auth.uid() AND prep_days IS NULL;
END $$;


--
-- Name: share_preview(uuid, uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.share_preview(p_trip uuid, p_exp uuid, p_on boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; e public.culture_experiences; v_country text; v_region text; v_city text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
  IF p_trip IS NOT NULL THEN
    SELECT * INTO t FROM public.trips WHERE id=p_trip;
    IF t.id IS NULL OR NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can share a preview'; END IF;
    IF NOT coalesce(p_on,false) THEN DELETE FROM public.experience_previews WHERE trip_id=p_trip; RETURN false; END IF;
    IF t.is_sandbox THEN RAISE EXCEPTION 'Test Lab trips can''t share previews'; END IF;
    IF t.kind NOT IN ('trip','at_home') THEN RAISE EXCEPTION 'This experience can''t share a preview'; END IF;
    IF t.ended_at IS NULL AND current_date <= t.end_date THEN RAISE EXCEPTION 'Previews can be shared after the trip ends'; END IF;
    IF t.kind='at_home' THEN
      v_country := CASE t.at_home_pack WHEN 'thailand' THEN 'TH' WHEN 'mexico' THEN 'MX' WHEN 'japan' THEN 'JP' ELSE NULL END;
    ELSE
      v_country := nullif(btrim(t.passport_country),'');
      v_city := nullif(btrim(t.passport_city),'');
      v_region := nullif(btrim(t.passport_state),'');
      IF lower(coalesce(v_country,'')) = ANY(ARRAY['usa','us','u.s.','united states','united states of america']) THEN v_country := 'US'; END IF;
      IF length(coalesce(v_country,''))=2 AND upper(v_country) IN ('NV','CA','NY','FL','TX','HI','AZ','CO','GA','IL','WA') THEN v_region := upper(v_country); v_country := 'US'; END IF;
    END IF;
    INSERT INTO public.experience_previews(trip_id,kind,country,region,city,month_year,length_days,vibe,squad_size,games_played,checkin_done,takeoff_done,task_titles,game_nights,stamps_earned)
    SELECT t.id, t.kind, v_country, v_region, left(v_city,60), to_char(t.start_date,'YYYY-MM'), (t.end_date - t.start_date + 1), t.vibe,
      (SELECT count(*) FROM public.trip_members WHERE trip_id=t.id AND status='approved'),
      (SELECT count(DISTINCT game_number) FROM public.game_nights WHERE trip_id=t.id AND NOT skipped AND starts_at <= now() AND game_number IS NOT NULL),
      (SELECT count(*) FROM public.mission_claims WHERE trip_id=t.id AND phase='checkin' AND status='released'),
      (SELECT count(*) FROM public.mission_claims WHERE trip_id=t.id AND phase='takeoff' AND status='released'),
      coalesce((SELECT array_agg(x.title) FROM (SELECT DISTINCT title FROM public.mission_claims WHERE trip_id=t.id AND phase='checkin' AND status='released' AND title IS NOT NULL LIMIT 6) x), '{}'),
      CASE WHEN t.kind='at_home' THEN (SELECT count(*) FROM public.home_day_sessions WHERE trip_id=t.id AND starts_at <= now()) ELSE (SELECT count(*) FROM public.game_nights WHERE trip_id=t.id AND NOT skipped AND starts_at <= now()) END,
      coalesce((SELECT sum(g.stamps) FROM trip_private.game_stamps(t.id) g), 0)
    ON CONFLICT (trip_id) DO UPDATE SET country=excluded.country, region=excluded.region, city=excluded.city, month_year=excluded.month_year, length_days=excluded.length_days, vibe=excluded.vibe, squad_size=excluded.squad_size, games_played=excluded.games_played, checkin_done=excluded.checkin_done, takeoff_done=excluded.takeoff_done, task_titles=excluded.task_titles, game_nights=excluded.game_nights, stamps_earned=excluded.stamps_earned, updated_at=now();
    RETURN true;
  END IF;
  SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp;
  IF e.id IS NULL OR e.creator_id <> auth.uid() THEN RAISE EXCEPTION 'Only the creator can share a preview'; END IF;
  IF NOT coalesce(p_on,false) THEN DELETE FROM public.experience_previews WHERE culture_exp_id=p_exp; RETURN false; END IF;
  IF coalesce(trip_private.age_of(auth.uid()),0) < 18 THEN RAISE EXCEPTION 'Sharing previews is for members 18+'; END IF;
  IF e.finished_at IS NULL THEN RAISE EXCEPTION 'Finish the experience first'; END IF;
  IF e.unlisted_at IS NOT NULL THEN RAISE EXCEPTION 'This experience was unlisted'; END IF;
  IF e.trip_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.trips WHERE id=e.trip_id AND is_sandbox) THEN RAISE EXCEPTION 'Test Lab experiences can''t share previews'; END IF;
  INSERT INTO public.experience_previews(culture_exp_id,kind,country,region,city,month_year,length_days,squad_size,task_titles,culture_public)
  SELECT e.id, CASE WHEN e.track='travel' THEN 'culture_travel' ELSE 'culture_home' END, e.country, e.region, e.city, to_char(e.start_date,'YYYY-MM'), e.days, 1,
    coalesce((SELECT array_agg(x.title) FROM (SELECT title FROM public.culture_exp_days WHERE experience_id=e.id ORDER BY day_number LIMIT 6) x), '{}'),
    e.visibility='public'
  ON CONFLICT (culture_exp_id) DO UPDATE SET country=excluded.country, region=excluded.region, city=excluded.city, month_year=excluded.month_year, length_days=excluded.length_days, task_titles=excluded.task_titles, culture_public=excluded.culture_public, updated_at=now();
  RETURN true;
END $$;


--
-- Name: shares_trip(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.shares_trip(p_other uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT p_other = auth.uid() OR EXISTS (SELECT 1 FROM public.trip_members a JOIN public.trip_members b ON a.trip_id=b.trip_id
  WHERE a.user_id=auth.uid() AND b.user_id=p_other AND a.status='approved' AND b.status='approved') $$;


--
-- Name: shuffle_teams(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.shuffle_teams(p_trip uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE teams uuid[]; caps int[]; filled int[]; u uuid; i int; n int; best int; moved int := 0;
BEGIN PERFORM trip_private.require_feature(p_trip, 'teams');
  IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can shuffle teams'; END IF;
  IF EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped AND starts_at <= now()) AND NOT trip_private.lab_bypass(p_trip) THEN RAISE EXCEPTION 'Teams can only be shuffled before the first game night'; END IF;
  PERFORM 1 FROM public.trip_teams WHERE trip_id=p_trip FOR UPDATE;
  SELECT array_agg(id ORDER BY created_at, id) INTO teams FROM public.trip_teams WHERE trip_id=p_trip;
  n := coalesce(array_length(teams,1),0);
  IF n < 2 THEN RAISE EXCEPTION 'Add at least 2 teams first'; END IF;
  SELECT array_agg(trip_private.team_capacity(x) ORDER BY o) INTO caps FROM unnest(teams) WITH ORDINALITY z(x,o);
  IF (SELECT sum(c) FROM unnest(caps) c) < (SELECT count(*) FROM public.trip_members WHERE trip_id=p_trip AND status='approved') THEN RAISE EXCEPTION 'Not enough team spots for everyone — raise a team limit first'; END IF;
  filled := array_fill(0, ARRAY[n]);
  DELETE FROM public.trip_team_members WHERE trip_id=p_trip;
  FOR u IN SELECT user_id FROM public.trip_members WHERE trip_id=p_trip AND status='approved' ORDER BY random() LOOP
    best := NULL;
    FOR i IN 1..n LOOP
      IF filled[i] < caps[i] AND (best IS NULL OR filled[i] < filled[best]) THEN best := i; END IF;
    END LOOP;
    INSERT INTO public.trip_team_members(trip_id,user_id,team_id) VALUES (p_trip,u,teams[best]);
    filled[best] := filled[best] + 1; moved := moved + 1;
  END LOOP;
  RETURN moved;
END $$;


--
-- Name: skip_card(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.skip_card(p_trip uuid, p_category text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_id bigint; BEGIN
IF p_category IN ('travel','food','childhood','deep','spicy') AND NOT EXISTS (SELECT 1 FROM public.game_night_flow f JOIN public.game_nights n ON n.trip_id=f.trip_id AND n.week_number=f.week_number WHERE f.trip_id=p_trip AND f.phase='cards' AND f.category=p_category AND n.starts_at BETWEEN clock_timestamp()-interval '12 hours' AND clock_timestamp()+interval '12 hours') THEN RAISE EXCEPTION 'No active card round'; END IF;
PERFORM trip_private.use_skip(p_trip,'card','',NULL);
RETURN trip_private.draw_game_card(p_trip,p_category); END $$;


--
-- Name: skip_limit(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.skip_limit(p_trip uuid, p_season text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
SELECT CASE WHEN p_season='trip' THEN 3 ELSE least(3, greatest(1, (SELECT count(*)::int FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped)/4)) END $$;


--
-- Name: skip_limit_for(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.skip_limit_for(p_trip uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
RETURN trip_private.skip_limit(p_trip,'game'); END $$;


--
-- Name: solo_action(text, uuid, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_action(p_action text, p_exp uuid, p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences; s jsonb; v_today date; v_day int; q public.solo_quests; v_path text; v_story text; v_streak int := 0; d int; v_best int; v_pts int; v_av int;
BEGIN
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp;
 IF NOT FOUND OR e.creator_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Not your experience'; END IF;
 IF e.play_mode<>'solo' THEN RAISE EXCEPTION 'This experience is played with others'; END IF;
 v_today := trip_private.solo_today(auth.uid());
 v_day := (v_today - e.start_date) + 1;
 IF p_action='open' THEN
   SELECT * INTO q FROM public.solo_quests WHERE experience_id=p_exp AND day_number=(p->>'day')::int FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'No quest for that day'; END IF;
   IF q.day_number > v_day THEN RAISE EXCEPTION 'This quest is still sealed until its trip day'; END IF;
   IF e.finished_at IS NOT NULL THEN RAISE EXCEPTION 'This experience is finished'; END IF;
   UPDATE public.solo_quests SET opened_at=coalesce(opened_at,now()), updated_at=now() WHERE id=q.id;
 ELSIF p_action='finish' THEN
   SELECT * INTO q FROM public.solo_quests WHERE experience_id=p_exp AND day_number=(p->>'day')::int FOR UPDATE;
   IF NOT FOUND OR q.opened_at IS NULL THEN RAISE EXCEPTION 'Open the quest first'; END IF;
   IF q.finished_at IS NOT NULL THEN RAISE EXCEPTION 'Already counted'; END IF;
   IF e.finished_at IS NOT NULL THEN RAISE EXCEPTION 'This experience is finished'; END IF;
   v_path := p->>'photo'; v_story := btrim(coalesce(p->>'story',''));
   IF v_path IS NULL OR split_part(v_path,'/',1)<>p_exp::text OR split_part(v_path,'/',2)<>auth.uid()::text
      OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id='culture-photos' AND o.name=v_path) THEN RAISE EXCEPTION 'Add your photo first'; END IF;
   IF length(v_story) NOT BETWEEN 10 AND 600 THEN RAISE EXCEPTION 'Write a short story for your guide page (10–600 characters)'; END IF;
   UPDATE public.solo_quests SET finished_at=now(), photo_path=v_path, story=v_story, speed_bonus=(now() <= opened_at + interval '3 hours'), updated_at=now() WHERE id=q.id;
 ELSIF p_action<>'state' THEN RAISE EXCEPTION 'Unknown action';
 END IF;
 PERFORM trip_private.solo_ensure(p_exp);
 s := trip_private.solo_score(p_exp);
 v_pts := (s->>'points')::int; v_av := (s->>'available')::int;
 FOR d IN REVERSE least(v_day, e.days)..1 LOOP
   IF EXISTS (SELECT 1 FROM public.solo_quests x WHERE x.experience_id=p_exp AND x.day_number=d AND x.finished_at IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.culture_exp_days x WHERE x.experience_id=p_exp AND x.day_number=d AND x.done_at IS NOT NULL) THEN v_streak := v_streak+1;
   ELSIF d < v_day THEN EXIT; END IF;
 END LOOP;
 SELECT max((trip_private.solo_score(o.id)->>'points')::int) INTO v_best FROM public.culture_experiences o WHERE o.creator_id=auth.uid() AND o.play_mode='solo' AND o.id<>p_exp;
 RETURN jsonb_build_object(
  'today_day', v_day, 'days', e.days, 'start_date', e.start_date, 'points', v_pts, 'available', v_av,
  'fare', trip_private.solo_fare(v_pts, v_av),
  'targets', jsonb_build_object('Economy', ceil(v_av*0.40)::int, 'Business', ceil(v_av*0.65)::int, 'First Class', ceil(v_av*0.85)::int),
  'streak', v_streak, 'personal_best', v_best,
  'stamps', jsonb_build_object('speed_runner', (s->>'speed')::int >= 3, 'clean_sweep', (s->>'quests_done')::int >= e.days AND e.days>0,
     'local_tongue', (s->>'lang')::int > 0 AND (s->>'lang')::int = (s->>'lang_done')::int, 'destination', e.finished_at IS NOT NULL),
  'quests', (SELECT coalesce(jsonb_agg(jsonb_build_object('day', x.day_number, 'sealed', x.opened_at IS NULL, 'arrived', x.day_number <= v_day,
     'title', CASE WHEN x.opened_at IS NOT NULL THEN x.title END, 'text', CASE WHEN x.opened_at IS NOT NULL THEN x.mission_text END,
     'backstory', CASE WHEN x.opened_at IS NOT NULL THEN x.backstory END, 'keywords', CASE WHEN x.opened_at IS NOT NULL THEN to_jsonb(x.keywords) END,
     'insight', CASE WHEN x.opened_at IS NOT NULL THEN x.insight END, 'budget', CASE WHEN x.opened_at IS NOT NULL THEN x.budget_note END,
     'opened_at', x.opened_at, 'finished_at', x.finished_at, 'speed_bonus', x.speed_bonus, 'photo', x.photo_path, 'story', x.story) ORDER BY x.day_number),'[]'::jsonb)
     FROM public.solo_quests x WHERE x.experience_id=p_exp));
END $$;


--
-- Name: solo_ensure(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_ensure(p_exp uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.culture_experiences WHERE id=p_exp AND a2e_kind IS NOT NULL) THEN PERFORM trip_private.a2e_solo_ensure(p_exp);
 ELSE PERFORM trip_private.solo_ensure_legacy(p_exp); END IF;
END $$;


--
-- Name: solo_ensure_legacy(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_ensure_legacy(p_exp uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences; d int; c record; v_dest text; a int;
BEGIN
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp;
 IF e.play_mode<>'solo' THEN RETURN; END IF;
 a := coalesce(trip_private.age_of(e.creator_id),0);
 v_dest := coalesce(nullif(e.city,''), nullif(e.region,''), e.country);
 FOR d IN 1..e.days LOOP
   IF EXISTS (SELECT 1 FROM public.solo_quests WHERE experience_id=p_exp AND day_number=d) THEN CONTINUE; END IF;
   SELECT sm.* INTO c FROM public.security_missions sm
    WHERE sm.trip_id IS NULL AND sm.kind='solo' AND sm.presentation_tag='solo_guide' AND length(btrim(sm.insight))>12 AND sm.budget_note IS NOT NULL
      AND (a>=21 OR NOT ('night_owl' = ALL(sm.traveler_tags)))
      AND NOT (a<18 AND (sm.text||' '||sm.title) ~* '(stranger|passer|(photo|photograph|film|record|video|selfie)\w*\s+(with\s+|of\s+)?(a\s+|an\s+|the\s+)?(local|people|person|someone|vendor|crowd)|after dark|late at night)')
      AND NOT EXISTS (SELECT 1 FROM public.solo_quests q WHERE q.user_id=e.creator_id AND lower(q.title)=lower(replace(sm.title,'{destination}',v_dest)))
    ORDER BY (sm.traveler_tags && e.traveler_types) DESC, (sm.category IN (SELECT lens FROM public.solo_quests WHERE experience_id=p_exp)) ASC, md5(sm.id::text||p_exp::text||d::text)
    LIMIT 1;
   IF NOT FOUND THEN
     SELECT sm.* INTO c FROM public.security_missions sm WHERE sm.trip_id IS NULL AND sm.kind='solo' AND (a>=21 OR NOT ('night_owl' = ALL(sm.traveler_tags)))
       AND NOT EXISTS (SELECT 1 FROM public.solo_quests q WHERE q.experience_id=p_exp AND lower(q.title) LIKE lower(replace(sm.title,'{destination}',v_dest))||'%')
       ORDER BY md5(sm.id::text||p_exp::text||d::text) LIMIT 1;
     IF NOT FOUND THEN CONTINUE; END IF;
   END IF;
   INSERT INTO public.solo_quests(experience_id,user_id,day_number,title,mission_text,backstory,keywords,insight,lens,budget_note)
   VALUES (p_exp,e.creator_id,d,replace(c.title,'{destination}',v_dest),replace(c.text,'{destination}',v_dest),replace(c.backstory,'{destination}',v_dest),
     ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(c.keywords) k),replace(c.insight,'{destination}',v_dest),c.category,c.budget_note)
   ON CONFLICT DO NOTHING;
 END LOOP;
END $$;


--
-- Name: solo_fare(integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_fare(p_points integer, p_available integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
 SELECT CASE WHEN p_available<=0 THEN 'Standby' WHEN p_points >= ceil(p_available*0.85) THEN 'First Class' WHEN p_points >= ceil(p_available*0.65) THEN 'Business' WHEN p_points >= ceil(p_available*0.40) THEN 'Economy' ELSE 'Standby' END $$;


--
-- Name: solo_no_trip(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_no_trip() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NEW.play_mode='solo' THEN NEW.trip_id := NULL; IF NEW.visibility='squad' THEN NEW.visibility := 'private'; END IF; END IF; RETURN NEW; END $$;


--
-- Name: solo_score(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_score(p_exp uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.culture_experiences WHERE id=p_exp AND a2e_kind='show' AND play_mode='solo') THEN jsonb_set(trip_private.solo_score_legacy(p_exp),'{points}',to_jsonb((trip_private.solo_score_legacy(p_exp)->>'points')::int+CASE WHEN EXISTS(SELECT 1 FROM public.culture_showcase_rewards WHERE experience_id=p_exp) THEN 5 ELSE 0 END)) ELSE trip_private.solo_score_legacy(p_exp) END $$;


--
-- Name: solo_score_legacy(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_score_legacy(p_exp uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 WITH e AS (SELECT * FROM public.culture_experiences WHERE id=p_exp),
 q AS (SELECT count(*) n, count(*) FILTER (WHERE finished_at IS NOT NULL) done, count(*) FILTER (WHERE speed_bonus) speed,
        count(*) FILTER (WHERE lens='language') lang, count(*) FILTER (WHERE lens='language' AND finished_at IS NOT NULL) lang_done FROM public.solo_quests WHERE experience_id=p_exp),
 c AS (SELECT coalesce(sum(points),0) avail, coalesce(sum(points) FILTER (WHERE done_at IS NOT NULL),0) got FROM public.culture_exp_days WHERE experience_id=p_exp)
 SELECT jsonb_build_object(
  'points', (q.done*10 + q.speed*5 + c.got)::int,
  'available', ((SELECT days FROM e)*15 + c.avail)::int,
  'quests_done', q.done, 'quests', (SELECT days FROM e), 'speed', q.speed, 'lang', q.lang, 'lang_done', q.lang_done)
 FROM q, c $$;


--
-- Name: solo_today(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.solo_today(p_user uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT (now() AT TIME ZONE coalesce((SELECT nullif(time_zone,'') FROM public.profiles WHERE id=p_user),'UTC'))::date $$;


--
-- Name: speed_bonus_ok(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.speed_bonus_ok(p_revealed timestamp with time zone, p_finished timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
 SELECT p_finished >= p_revealed AND p_finished <= p_revealed + interval '3 hours' $$;


--
-- Name: spend_credits(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.spend_credits(p_trip uuid, p_action text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c int := trip_private.credit_cost(p_action); have int; uid uuid;
BEGIN PERFORM trip_private.ai_gate(p_action, p_trip, auth.uid()); PERFORM trip_private.require_feature(p_trip, 'ai_extras');
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 PERFORM trip_private.teen_block('AI');
 IF c IS NULL THEN RAISE EXCEPTION 'Not allowed'; END IF;
 IF NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'AI ideas are for beta members only.'; END IF;
 IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can use AI credits.'; END IF;
 PERFORM 1 FROM public.trips WHERE id=p_trip FOR UPDATE;
 SELECT remaining INTO have FROM trip_private.credit_status(p_trip);
 IF have < c THEN RAISE EXCEPTION 'OUT_OF_CREDITS: This needs % AI credits and the trip has %.', c, have; END IF;
 INSERT INTO public.ai_usage(user_id, trip_id, kind, credits) VALUES (auth.uid(), p_trip, p_action, c) RETURNING id INTO uid;
 RETURN uid;
END $$;


--
-- Name: spin_next_game(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.spin_next_game(p_trip uuid) RETURNS TABLE(game_number integer, week_number integer, spin_time timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_target integer; v_current integer; v_game integer; v_used integer[]; v_now timestamptz:=clock_timestamp(); BEGIN PERFORM trip_private.require_feature(p_trip, 'spin_wheel');
IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF;
IF NOT trip_private.trip_open(p_trip) THEN RAISE EXCEPTION 'This trip has ended'; END IF;
SELECT n.week_number INTO v_current FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at<=v_now ORDER BY n.starts_at DESC LIMIT 1;
SELECT n.week_number INTO v_target FROM public.game_nights n WHERE n.trip_id=p_trip AND n.game_number IS NULL AND n.starts_at>v_now AND NOT n.skipped AND (v_current IS NULL OR n.week_number>v_current) ORDER BY n.week_number LIMIT 1;
IF v_target IS NULL THEN RAISE EXCEPTION 'No upcoming week needs a game'; END IF;
-- Quest step gate applies only when someone has a quest marked done for this night; nights with no presented quests (incl. the pre-quest app) spin as before.
IF v_current IS NOT NULL AND trip_private.night_open(p_trip,v_current)
   AND EXISTS (SELECT 1 FROM public.season_quests q WHERE q.trip_id=p_trip AND q.quest_kind='preflight' AND q.night_week=v_current AND q.status='pending')
   AND NOT EXISTS (SELECT 1 FROM public.game_night_flow f WHERE f.trip_id=p_trip AND f.week_number=v_current AND f.quest_step_at IS NOT NULL) THEN RAISE EXCEPTION 'Present your quests before spinning for next week'; END IF;
IF v_target=1 THEN RAISE EXCEPTION 'The Captain chooses the first game'; END IF;
IF NOT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=auth.uid() AND m.status='approved' AND (m.role IN ('captain','co_captain') OR m.user_id=(SELECT n.host_id FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=coalesce(v_current,1)))) THEN RAISE EXCEPTION 'Only a leader or this week''s host can spin'; END IF;
IF NOT EXISTS (SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_target-1 AND n.game_number IS NOT NULL) THEN RAISE EXCEPTION 'Choose the previous week''s game first'; END IF;
INSERT INTO public.trip_play_state(trip_id) VALUES(p_trip) ON CONFLICT DO NOTHING;
SELECT coalesce(s.used_games,'{}'::integer[]) INTO v_used FROM public.trip_play_state s WHERE s.trip_id=p_trip FOR UPDATE;
SELECT g.number INTO v_game FROM public.game_catalog g WHERE NOT(g.number=ANY(v_used)) ORDER BY random() LIMIT 1;
IF v_game IS NULL THEN SELECT g.number INTO v_game FROM public.game_catalog g WHERE g.number<>(SELECT n.game_number FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_target-1) ORDER BY random() LIMIT 1; v_used:='{}'; END IF;
IF v_game IS NULL THEN RAISE EXCEPTION 'No game available'; END IF;
UPDATE public.game_nights n SET game_number=v_game WHERE n.trip_id=p_trip AND n.week_number=v_target AND n.game_number IS NULL;
IF NOT FOUND THEN RAISE EXCEPTION 'That week already has a game'; END IF;
UPDATE public.trip_play_state s SET used_games=array_append(v_used,v_game),spin_game=v_game,spin_week=v_target,spin_at=v_now WHERE s.trip_id=p_trip;
INSERT INTO public.game_pick_log(trip_id,week_number,game_number,actor,method) VALUES(p_trip,v_target,v_game,auth.uid(),'surprise');
RETURN QUERY SELECT v_game,v_target,v_now; END $$;


--
-- Name: start_game_turns(uuid, integer, integer, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.start_game_turns(p_trip uuid, p_week integer, p_cards integer, p_random boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_order uuid[]; BEGIN IF NOT trip_private.can_run_turns(p_trip,p_week) THEN RAISE EXCEPTION 'Host or leader only'; END IF;
IF NOT trip_private.night_open(p_trip,p_week) THEN RAISE EXCEPTION 'Turns run only while the game night is live'; END IF;
IF p_cards NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Choose 1 to 5 cards'; END IF; SELECT array_agg(user_id ORDER BY CASE WHEN p_random THEN random() ELSE 0 END,joined_at,user_id) INTO v_order FROM public.trip_members WHERE status='approved' AND trip_id=p_trip; IF cardinality(v_order)<1 THEN RAISE EXCEPTION 'No players'; END IF;
DELETE FROM public.game_night_turns WHERE trip_id=p_trip AND room<>'all';
INSERT INTO public.game_night_turns(trip_id,room,week_number,cards_per_person,player_order,turn_index,card_number,active) VALUES(p_trip,'all',p_week,p_cards,v_order,0,1,true) ON CONFLICT(trip_id,room) DO UPDATE SET week_number=excluded.week_number,cards_per_person=excluded.cards_per_person,player_order=excluded.player_order,turn_index=0,card_number=1,active=true; END $$;


--
-- Name: step_down(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.step_down(p_trip uuid, p_to uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can step down'; END IF;
 IF p_to = auth.uid() OR NOT trip_private.is_trip_member(p_trip, p_to) THEN RAISE EXCEPTION 'Pick an approved member'; END IF;
 IF coalesce(trip_private.age_of(p_to),0) < 21 AND NOT EXISTS (SELECT 1 FROM public.sandbox_bots WHERE user_id=p_to) THEN RAISE EXCEPTION 'Captains are 21+. Pick someone 21 or older.'; END IF;
 UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND user_id=auth.uid();
 UPDATE public.trip_members SET role='captain' WHERE trip_id=p_trip AND user_id=p_to;
 PERFORM trip_private.log_role(p_trip, auth.uid(), p_to, 'captain', 'stepped down');
END $$;


--
-- Name: submit_checkin(uuid, text, text, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.submit_checkin(p_trip uuid, p_context text, p_key text, p_answers jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM trip_members WHERE trip_id = p_trip AND user_id = auth.uid() AND status = 'approved') THEN RAISE EXCEPTION 'Not a member of this trip'; END IF;
  IF p_context NOT IN ('game_night','trip_day') OR length(p_key) > 40 OR length(p_answers::text) > 3000 THEN RAISE EXCEPTION 'Invalid check-in'; END IF;
  INSERT INTO checkin_responses(user_id, trip_id, context, context_key, answers) VALUES (auth.uid(), p_trip, p_context, p_key, p_answers)
  ON CONFLICT (user_id, trip_id, context, context_key) DO NOTHING;
END $$;


--
-- Name: submit_trip_feedback(uuid, boolean, integer, text, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.submit_trip_feedback(p_trip uuid, p_skipped boolean, p_score integer, p_favorite text, p_change text, p_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; BEGIN
  IF NOT public.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
  SELECT * INTO t FROM public.trips WHERE id=p_trip;
  IF t.ended_at IS NULL AND (now() AT TIME ZONE t.home_timezone)::date <= t.end_date THEN RAISE EXCEPTION 'Feedback opens when the trip ends'; END IF;
  IF NOT coalesce(p_skipped,false) AND p_score IS NULL THEN RAISE EXCEPTION 'Pick a score from 0 to 10'; END IF;
  INSERT INTO public.trip_feedback(trip_id,user_id,skipped,score,favorite,change_text,squad_message)
  VALUES (p_trip, auth.uid(), coalesce(p_skipped,false),
    CASE WHEN p_skipped THEN NULL ELSE p_score END, CASE WHEN p_skipped THEN NULL ELSE p_favorite END,
    CASE WHEN p_skipped THEN NULL ELSE nullif(left(trim(coalesce(p_change,'')),500),'') END,
    CASE WHEN p_skipped THEN NULL ELSE nullif(left(trim(coalesce(p_message,'')),280),'') END)
  ON CONFLICT (trip_id,user_id) DO NOTHING;
  IF NOT FOUND THEN RAISE EXCEPTION 'You already shared feedback for this trip'; END IF;
END $$;


--
-- Name: surprise_night_game(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.surprise_night_game(p_trip uuid, p_week integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_used integer[]; v_game integer; v_n public.game_nights;
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 SELECT * INTO v_n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
 IF NOT FOUND OR v_n.skipped OR v_n.starts_at<=now() OR v_n.game_locked OR (v_n.game_number IS NOT NULL AND v_n.game_revealed) OR NOT(trip_private.is_leader(p_trip) OR v_n.host_id=auth.uid()) THEN RAISE EXCEPTION 'Only the host or a leader can choose an upcoming, unassigned or unrevealed night'; END IF;
 SELECT coalesce(array_agg(DISTINCT game_number),'{}'::integer[]) INTO v_used FROM public.game_nights WHERE trip_id=p_trip AND week_number<>p_week AND game_number IS NOT NULL;
 SELECT number INTO v_game FROM public.game_catalog WHERE NOT(number=ANY(v_used)) AND number IS DISTINCT FROM v_n.game_number ORDER BY random() LIMIT 1;
 IF v_game IS NULL THEN SELECT number INTO v_game FROM public.game_catalog WHERE number IS DISTINCT FROM v_n.game_number ORDER BY random() LIMIT 1; END IF;
 IF v_game IS NULL THEN RAISE EXCEPTION 'No other game available'; END IF;
 PERFORM trip_private.pick_night_game(p_trip,p_week,v_game);
 UPDATE public.game_pick_log SET method='surprise' WHERE id=(SELECT max(id) FROM public.game_pick_log WHERE trip_id=p_trip AND week_number=p_week AND actor=auth.uid());
 RETURN v_game;
END $$;


--
-- Name: sync_passport(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sync_passport(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t record; home text; country text; state_name text; city_name text; k text; last_part text;
BEGIN
 IF p_user IS NULL OR (p_user <> auth.uid() AND NOT EXISTS (SELECT 1 FROM public.trip_members a JOIN public.trip_members b ON b.trip_id=a.trip_id AND b.status='approved' WHERE a.user_id=auth.uid() AND a.status='approved' AND b.user_id=p_user)) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 DELETE FROM public.passport_stamps s WHERE s.user_id=p_user AND NOT EXISTS (SELECT 1 FROM public.trip_members m JOIN public.trips xt ON xt.id=m.trip_id WHERE m.user_id=p_user AND m.status='approved' AND m.trip_id=s.trip_id AND xt.kind='trip' AND NOT xt.is_sandbox AND (xt.ended_at IS NOT NULL OR (now() AT TIME ZONE xt.home_timezone)::date > xt.end_date+2));
 SELECT nullif(btrim(home_country),'') INTO home FROM public.player_profiles WHERE user_id=p_user;
 IF home IS NULL THEN DELETE FROM public.passport_stamps WHERE user_id=p_user; RETURN; END IF;
 FOR t IN SELECT tr.* FROM public.trips tr JOIN public.trip_members m ON m.trip_id=tr.id WHERE m.user_id=p_user AND m.status='approved' AND tr.kind='trip' AND NOT tr.is_sandbox AND (tr.ended_at IS NOT NULL OR (now() AT TIME ZONE tr.home_timezone)::date > tr.end_date+2) LOOP
   last_part := nullif(btrim(split_part(t.destination, ',', array_length(string_to_array(t.destination,','),1))), '');
   country := coalesce(nullif(btrim(t.passport_country),''),last_part);
   IF country IS NULL THEN CONTINUE; END IF;
   IF lower(country) IN ('usa','us','u.s.','united states of america','united states') THEN country:='United States'; END IF;
   IF t.passport_country IS NULL AND lower(country) = ANY(ARRAY['alabama','alaska','arizona','arkansas','california','colorado','connecticut','delaware','florida','georgia','hawaii','idaho','illinois','indiana','iowa','kansas','kentucky','louisiana','maine','maryland','massachusetts','michigan','minnesota','mississippi','missouri','montana','nebraska','nevada','new hampshire','new jersey','new mexico','new york','north carolina','north dakota','ohio','oklahoma','oregon','pennsylvania','rhode island','south carolina','south dakota','tennessee','texas','utah','vermont','virginia','washington','west virginia','wisconsin','wyoming','dc','district of columbia','al','ak','az','ar','ca','co','ct','de','fl','ga','hi','id','il','in','ia','ks','ky','la','me','md','ma','mi','mn','ms','mo','mt','ne','nv','nh','nj','nm','ny','nc','nd','oh','ok','or','pa','ri','sc','sd','tn','tx','ut','vt','va','wa','wv','wi','wy']) THEN country:='United States'; END IF;
   IF lower(home) IN ('usa','us','u.s.','united states of america','united states') THEN home:='United States'; END IF;
   IF lower(country)=lower(home) THEN
     IF country <> 'United States' THEN DELETE FROM public.passport_stamps WHERE user_id=p_user AND trip_id=t.id; CONTINUE; END IF;
     k:='road_trip'; state_name:=coalesce(nullif(btrim(t.passport_state),''),CASE WHEN last_part <> 'United States' AND last_part <> 'USA' AND last_part <> 'US' THEN last_part END); city_name:=coalesce(nullif(btrim(t.passport_city),''),nullif(btrim(split_part(t.destination,',',1)),''));
     IF state_name IS NULL THEN DELETE FROM public.passport_stamps WHERE user_id=p_user AND trip_id=t.id; CONTINUE; END IF;
   ELSE
     k:='international'; state_name:=NULL; city_name:=coalesce(nullif(btrim(t.passport_city),''),nullif(btrim(split_part(t.destination,',',1)),''));
   END IF;
   INSERT INTO public.passport_stamps(user_id,trip_id,kind,country,state,city,stamped_on) VALUES(p_user,t.id,k,country,state_name,city_name,t.end_date)
   ON CONFLICT (user_id,trip_id) DO UPDATE SET kind=excluded.kind,country=excluded.country,state=excluded.state,city=excluded.city,stamped_on=excluded.stamped_on;
 END LOOP;
END $$;


--
-- Name: sync_profile_to_cards(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.sync_profile_to_cards() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
UPDATE public.trip_player_cards SET real_name=NEW.real_name, game_name=NEW.game_name, avatar_style=NEW.avatar_style, avatar_seed=NEW.avatar_seed, avatar_path=NEW.avatar_path, hometown=NEW.hometown, occupation=NEW.occupation, fun_fact=NEW.fun_fact, trip_persona=NEW.trip_persona, next_year_goal=NEW.next_year_goal, pronouns=NEW.pronouns WHERE user_id=NEW.user_id;
RETURN NEW; END $$;


--
-- Name: take_over_captain(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.take_over_captain(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE cap uuid; seen timestamptz; BEGIN
 PERFORM 1 FROM public.trips WHERE id=p_trip FOR UPDATE;
 IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='co_captain' AND status='approved') THEN RAISE EXCEPTION 'Only the Co-Captain can take over'; END IF;
 IF coalesce(trip_private.age_of(auth.uid()),0) < 21 THEN RAISE EXCEPTION 'Captains are 21+. Ask your crew''s Captain to hand off to someone 21 or older.'; END IF;
 SELECT m.user_id, p.last_seen_at INTO cap, seen FROM public.trip_members m LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.trip_id=p_trip AND m.role='captain';
 IF cap IS NOT NULL AND coalesce(seen, now()) > now()-interval '14 days' THEN RAISE EXCEPTION 'The Captain has been active in the last 14 days'; END IF;
 UPDATE public.trip_members SET role='player' WHERE trip_id=p_trip AND user_id=auth.uid(); UPDATE public.trip_members SET role='co_captain' WHERE trip_id=p_trip AND user_id=cap;
 UPDATE public.trip_members SET role='captain' WHERE trip_id=p_trip AND user_id=auth.uid();
 PERFORM trip_private.log_role(p_trip, cap, auth.uid(), 'captain', 'takeover');
END $$;


--
-- Name: takeoff_week(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.takeoff_week(p_trip uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
SELECT n.week_number FROM public.game_nights n JOIN public.trips t ON t.id=n.trip_id WHERE n.trip_id=p_trip AND NOT n.skipped AND (n.starts_at AT TIME ZONE t.home_timezone)::date < t.start_date ORDER BY n.starts_at DESC LIMIT 1 $$;


--
-- Name: team_capacity(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.team_capacity(p_team uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT coalesce(t.capacity, greatest(1, ceil((SELECT count(*) FROM public.trip_members m WHERE m.trip_id=t.trip_id AND m.status='approved')::numeric / greatest(1,(SELECT count(*) FROM public.trip_teams x WHERE x.trip_id=t.trip_id)))::int)) FROM public.trip_teams t WHERE t.id=p_team $$;


--
-- Name: teen_block(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.teen_block(p_what text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF auth.uid() IS NULL OR coalesce(trip_private.age_of(auth.uid()),0) < 18 THEN RAISE EXCEPTION '% is for players 18 and older.', p_what; END IF; END $$;


--
-- Name: thumb_quest(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.thumb_quest(p_post uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE q public.quest_posts; BEGIN
 SELECT * INTO q FROM public.quest_posts WHERE id=p_post; IF NOT FOUND THEN RAISE EXCEPTION 'Quest not found'; END IF;
 PERFORM trip_private.play_day(q.trip_id,q.day_date);
 IF q.user_id=auth.uid() THEN RAISE EXCEPTION 'You can''t verify your own quest'; END IF;
 IF q.photo_path IS NULL THEN RAISE EXCEPTION 'Honor-system quests do not need squad verification'; END IF;
 INSERT INTO public.quest_thumbs(post_id,trip_id,user_id) VALUES(p_post,q.trip_id,auth.uid()) ON CONFLICT DO NOTHING;
END $$;


--
-- Name: touch_guide_item(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.touch_guide_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$ BEGIN NEW.updated_at := now(); RETURN NEW; END $$;


