    CONSTRAINT cultural_inspirations_meaning_check CHECK ((length(meaning) <= 2000)),
    CONSTRAINT cultural_inspirations_mode_check CHECK ((mode = ANY (ARRAY['solo'::text, 'team'::text, 'challenge'::text]))),
