    CONSTRAINT cultural_inspirations_song_artist_check CHECK ((length(song_artist) <= 120)),
    CONSTRAINT cultural_inspirations_song_url_check CHECK ((length(song_url) <= 500)),
    CONSTRAINT cultural_inspirations_steps_check CHECK ((length(steps) <= 5000)),
