    CONSTRAINT season_quests_check1 CHECK (((status = 'approved'::text) = ((approved_at IS NOT NULL) AND (approved_by IS NOT NULL) AND (awarded_points IS NOT NULL)))),
    CONSTRAINT season_quests_check2 CHECK (((awarded_points IS NULL) OR (awarded_points = points))),
    CONSTRAINT season_quests_points_check CHECK (((points >= 0) AND (points <= 12))),
    CONSTRAINT season_quests_quest_kind_check CHECK ((quest_kind = ANY (ARRAY['preflight'::text, 'carry_on'::text]))),
