    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    phase text DEFAULT 'hidden'::text NOT NULL,
    read_index integer DEFAULT 0 NOT NULL,
    winner_id uuid,
    tie_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    tie_spin_at timestamp with time zone,
    shuffle_salt uuid DEFAULT gen_random_uuid() NOT NULL,
    CONSTRAINT weekly_questions_phase_check CHECK ((phase = ANY (ARRAY['hidden'::text, 'reading'::text, 'voting'::text, 'tie'::text, 'revealed'::text]))),
    CONSTRAINT weekly_questions_prompt_check CHECK (((length(prompt) >= 3) AND (length(prompt) <= 200))),
    CONSTRAINT weekly_questions_source_check CHECK ((source = ANY (ARRAY['pool'::text, 'custom'::text])))
);


