--
-- Name: app_admins Admins see own row; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins see own row" ON public.app_admins FOR SELECT TO authenticated USING ((user_id = auth.uid()));


--
-- Name: app_settings Anyone reads launch switch; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Anyone reads launch switch" ON public.app_settings FOR SELECT TO anon USING (true);


--
-- Name: trip_feedback App owner reads feedback; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "App owner reads feedback" ON public.trip_feedback FOR SELECT TO authenticated USING ((trip_private.is_app_admin() AND (NOT (EXISTS ( SELECT 1
   FROM public.trips t
  WHERE ((t.id = trip_feedback.trip_id) AND t.is_sandbox))))));


--
-- Name: game_cards Approved adults see spicy base cards; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Approved adults see spicy base cards" ON public.game_cards FOR SELECT TO authenticated USING (((trip_id IS NULL) AND (category = 'spicy'::text) AND (EXISTS ( SELECT 1
   FROM (public.trip_members m
     JOIN public.game_nights n ON (((n.trip_id = m.trip_id) AND (n.game_number = game_cards.game_number))))
  WHERE ((m.user_id = auth.uid()) AND trip_private.is_approved_adult(m.trip_id, auth.uid()))))));


--
-- Name: song_discs Approved members read discs; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Approved members read discs" ON public.song_discs FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id, auth.uid()));


--
-- Name: at_home_song_winners Approved members see winning disc; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Approved members see winning disc" ON public.at_home_song_winners FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.at_home_activities a
  WHERE ((a.id = at_home_song_winners.activity_id) AND trip_private.is_trip_member(a.trip_id, auth.uid())))));


--
-- Name: window_guide_items Authors, Captain, and crew after publish read guide items; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Authors, Captain, and crew after publish read guide items" ON public.window_guide_items FOR SELECT TO authenticated USING (((author_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE ((m.trip_id = window_guide_items.trip_id) AND (m.user_id = auth.uid()) AND (m.role = 'captain'::text) AND (m.status = 'approved'::text)))) OR ((status = 'approved'::text) AND (EXISTS ( SELECT 1
   FROM public.trips t
  WHERE ((t.id = window_guide_items.trip_id) AND (t.guide_published_at IS NOT NULL)))) AND (EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE ((m.trip_id = window_guide_items.trip_id) AND (m.user_id = auth.uid()) AND (m.status = 'approved'::text)))))));


--
-- Name: player_birthdays Birthday owner or trip captain reads; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Birthday owner or trip captain reads" ON public.player_birthdays FOR SELECT TO authenticated USING (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM (public.trip_members m
     JOIN public.trip_members c ON ((c.trip_id = m.trip_id)))
  WHERE ((m.user_id = player_birthdays.user_id) AND (c.user_id = auth.uid()) AND (c.role = 'captain'::text))))));


--
-- Name: game_night_polls Captain creates poll; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Captain creates poll" ON public.game_night_polls FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE ((m.trip_id = game_night_polls.trip_id) AND (m.user_id = auth.uid()) AND (m.role = 'captain'::text)))));


--
-- Name: game_night_polls Captain edits poll; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Captain edits poll" ON public.game_night_polls FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE ((m.trip_id = game_night_polls.trip_id) AND (m.user_id = auth.uid()) AND (m.role = 'captain'::text))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE ((m.trip_id = game_night_polls.trip_id) AND (m.user_id = auth.uid()) AND (m.role = 'captain'::text)))));


