-- Name: trip_day_tags Leaders add day tags; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Leaders add day tags" ON public.trip_day_tags FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM (public.trip_members m
     JOIN public.trips t ON ((t.id = m.trip_id)))
  WHERE ((m.trip_id = trip_day_tags.trip_id) AND (m.user_id = auth.uid()) AND (m.role = ANY (ARRAY['captain'::text, 'co_captain'::text])) AND ((trip_day_tags.day_date >= t.start_date) AND (trip_day_tags.day_date <= t.end_date))))));


