  WHERE ((m.trip_id = trip_day_tags.trip_id) AND (m.user_id = auth.uid()) AND (m.role = ANY (ARRAY['captain'::text, 'co_captain'::text])))))) WITH CHECK ((EXISTS ( SELECT 1
