INSERT INTO public.app_settings (id, public_launch, updated_at, founder_intro, welcome_faq, founding_open, founding_closed_at, boarding_tile, ai_enabled, ai_daily_global_cap, ai_daily_user_cap, ai_updated_at, beta_free) VALUES
	(true, false, '2026-10-22 00:00:00+00', 'I’m Tymeka “Ty” Smith, an Army veteran and forever trip junkie. I built TripJunkies so every squad feels closer before takeoff.', '[{"a": "Game nights before departure, challenges during the trip, and a recap after.", "q": "How does it work?"}, {"a": "Beta passes are $0 today, with no card needed. Your Captain sees the trip price before unlocking.", "q": "What does it cost?"}, {"a": "Your Captain sends a personal link or a join code. You choose when to join.", "q": "How do invites work?"}, {"a": "The Captain sets up the trip, invites the squad and keeps everything moving.", "q": "What does a Captain do?"}, {"a": "Join the call, play together and vote in the app when the night is live.", "q": "How do game nights work?"}]', true, NULL, 'current', true, 150, 15, NULL, true);


