INSERT INTO public.at_home_packs (key, name, emoji, overview, created_at) VALUES
	('thailand', 'Thailand', '🇹🇭', 'Golden temples, night markets and a whole lot of basil. Thailand is the land of smiles — sweet, salty, sour and spicy all on one plate.', '2026-10-22 00:00:00+00'),
	('mexico', 'Mexico', '🇲🇽', 'Bright colors, big flavors and music that makes you move. Mexico mixes ancient traditions with fiesta energy.', '2026-10-22 00:00:00+00'),
	('japan', 'Japan', '🇯🇵', 'Neon cities, quiet gardens and tiny details done perfectly. Japan is about craft, cozy food and a little kawaii.', '2026-10-22 00:00:00+00');


