INSERT INTO public.at_home_pack_items (id, pack, category, title, body, want, alt, adult, created_at, backstory, search_keywords) VALUES
	(1, 'thailand', 'dish', 'Pad kra pao', 'Stir-fry ground chicken with garlic, soy and basil, top with a fried egg. Easy/cheap: instant noodles + basil + egg.', 'Basil (any kind) and an egg', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(2, 'thailand', 'dish', 'Mango sticky rice', 'Sweet rice + coconut milk + sliced mango. Easy/cheap: rice pudding cup with mango on top.', 'A mango or mango cup', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(3, 'thailand', 'order_in', 'Thai takeout night', 'Everyone orders one Thai dish and shows it on the call. Rate spice levels 1–5 🌶️.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(4, 'thailand', 'phrase', 'Sawasdee ka / krap', 'Hello! Women end with "ka", men with "krap". Bonus: "khob khun" = thank you.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(5, 'thailand', 'phrase', 'Mai pen rai', '"No worries / it''s all good." Use it once today.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(6, 'thailand', 'playlist', 'Bangkok night market', 'Thai pop, luk thung and chill lounge beats. Everyone adds one song.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(8, 'thailand', 'trivia', 'Thailand mini trivia', 'Capital? (Bangkok) · Old name? (Siam) · National animal? (Elephant)', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(9, 'thailand', 'movie', 'Movie pick: The Cave (2019)', 'The true story of the Thai cave rescue. Or any street-food doc episode set in Bangkok.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(10, 'thailand', 'snack', 'Snack swap: Thai iced tea', 'Black tea + sweetened condensed milk over ice. Everyone grabs one sweet + one salty snack.', NULL, 'No-alcohol by default', false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(12, 'thailand', 'build', 'Paper lotus float', 'Fold a paper lotus (Loy Krathong style) and float it in a bowl of water.', 'Paper and a bowl', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(13, 'thailand', 'starter', 'Conversation starter', 'Street food or fancy restaurant — which one wins forever?', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(14, 'thailand', 'starter', 'Conversation starter', 'What would your Thai nickname be and why?', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(41, 'japan', 'phrase', 'Arigatou gozaimasu', '"Thank you very much." Say it to someone today.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"japan culture","japan traditions"}'),
	(42, 'japan', 'playlist', 'Tokyo neon', 'City pop, J-pop and anime openings. Everyone adds one song.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"japan culture","japan traditions"}'),
	(43, 'japan', 'dress_up', 'Cozy Tokyo street', 'Oversized hoodie + something cute (a clip, a pin, a plushie).', 'A hoodie', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"japan culture","japan traditions"}'),
	(15, 'thailand', 'question', 'Question', 'If you opened a night-market stall, what would you sell?', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(16, 'thailand', 'question', 'Question', 'Which squad member would win a spicy-food challenge?', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(17, 'thailand', 'culture', 'Wai greeting', 'Press your palms together and bow slightly — the higher the hands, the more respect.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(18, 'thailand', 'culture', 'Muay Thai minute', 'Try 60 seconds of shadow boxing — the "art of eight limbs".', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"thailand culture","thailand traditions"}'),
	(19, 'mexico', 'dish', 'Tacos al pastor-ish', 'Pan-fry chicken or pork with chili, garlic and pineapple; serve in tortillas. Easy/cheap: quesadillas.', 'Tortillas', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(20, 'mexico', 'dish', 'Elote in a cup', 'Corn + mayo + lime + chili powder + cheese. Easy/cheap: canned corn works.', 'A can of corn', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(21, 'mexico', 'order_in', 'Taco Tuesday (any day)', 'Everyone orders tacos or burritos. Vote on best salsa.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(22, 'mexico', 'phrase', '¡Salud!', '"Cheers!" Bonus: "¿Qué onda?" = what''s up?', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(23, 'mexico', 'phrase', 'Mi casa es tu casa', '"My house is your house" — say it when someone joins the call.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(24, 'mexico', 'playlist', 'Fiesta mix', 'Mariachi, cumbia and Latin pop. Everyone adds one song.', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(25, 'mexico', 'dress_up', 'Color clash', 'Wear the brightest colors you own. Bonus: a flower in your hair.', 'Something bright', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(26, 'mexico', 'trivia', 'Mexico mini trivia', 'Capital? (Mexico City) · Chocolate''s origin? (Mexico) · Day of the Dead date? (Nov 1–2)', NULL, NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
