	(28, 'mexico', 'snack', 'Snack swap: agua fresca', 'Blend fruit + water + a little sugar and lime. Grab chips and salsa.', NULL, 'No-alcohol by default', false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
	(30, 'mexico', 'build', 'Mini piñata', 'Make a tiny piñata from a paper cup or bag, fill with candy.', 'A paper bag and some candy', NULL, false, '2026-10-22 00:00:00+00', 'A window into the traditions, daily life and creativity of this place.', '{"mexico culture","mexico traditions"}'),
