INSERT INTO public.game_catalog (number, name, how_to_play, twist, how_to_win, prep, created_at, updated_at) VALUES
	(1, 'Two Truths and a Trip', 'Say two truths and one lie. Everyone calls out the lie.', 'Tell the story behind a truth.', 'Most correct guesses.', 'None.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(2, 'Baby Pic: Guess the Age', 'Screen-share a baby or kid photo and share a memory from that age. Everyone types an age guess.', 'What was your world like then?', 'Closest guess earns one point per photo; most points wins.', 'Have a childhood photo ready.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(3, 'Whose Song Is It', 'Text the host two songs beforehand. The host plays clips; guess whose songs they are.', 'The owner explains why each song matters.', 'Most correct guesses.', 'Send the host two songs.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(4, 'Hot Seat', 'Each person answers five questions from the deck. No skipping.', 'Ask one follow-up to get the real story.', 'Anonymous vote for best answers.', 'None.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(5, 'Destination Trivia', 'The host reads trivia cards about the trip destination.', 'Share a surprising fact you learned.', 'Most correct answers.', 'Host opens destination cards.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(6, 'Phrase of the Week', 'Learn three phrases in the destination language, or local slang for a domestic trip, and say them live.', 'Use one in a sentence about the trip.', 'Vote for best delivery.', 'Pick three phrases.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(7, 'Cook-Off', 'Eat a dish inspired by the destination on the call.', 'Share a food that reminds you of home.', 'Group vote.', 'Bring a dish or snack.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(8, 'Most Likely To', 'Read a prompt and vote live for the person most likely to do it.', 'The winner defends their title.', 'Most votes becomes legend of the week.', 'None.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(9, 'Gartic Phone Night', 'The host shares a garticphone.com link. Draw and watch the chaos unfold.', 'Everyone narrates their favorite reveal.', 'Vote for funniest drawing.', 'Host opens garticphone.com.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(10, 'Camera Roll Roulette', 'Draw a number. Everyone shows that numbered photo on camera, no skips, and tells its story.', 'What happened just before or after?', 'Vote for best story.', 'Have your camera roll ready.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(11, 'Emoji Me', 'Text the host five emojis that describe you. Host screen-shares the sets; guess whose is whose.', 'Explain your five emojis.', 'Most correct guesses.', 'Send the host five emojis.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(12, 'Would You Rather', 'Pick a destination-inspired dilemma quickly, then defend your choice.', 'Can anyone change your mind?', 'Vote for best defense.', 'None.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(13, 'Who Said It', 'Read a mystery statement and guess which squad member said it.', 'Ask for the story behind the answer.', 'Most correct guesses.', 'None.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(14, 'Never Have I Ever', 'Read a clean travel or life prompt. Everyone shares if they have done it.', 'Tell the story if you want to.', 'Vote for the most memorable story.', 'None.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00'),
	(15, 'Hot Takes', 'Share your opinion on a playful debate and defend it.', 'See who can change a mind.', 'Vote for the best defense.', 'None.', '2026-10-22 00:00:00+00', '2026-10-22 00:00:00+00');


