INSERT INTO public.weekly_question_pool (id, prompt, spicy, created_at) VALUES
	(1, 'What''s the one food you HAVE to try on this trip?', false, '2026-10-22 00:00:00+00'),
	(2, 'Window seat or aisle seat, and defend your answer.', false, '2026-10-22 00:00:00+00'),
	(3, 'What''s the best trip you''ve ever taken, in one sentence?', false, '2026-10-22 00:00:00+00'),
	(4, 'Would you rather lose your luggage or your phone for the whole trip?', false, '2026-10-22 00:00:00+00'),
	(5, 'What''s your most chaotic travel story?', false, '2026-10-22 00:00:00+00'),
	(6, 'What song should be the official trip anthem?', false, '2026-10-22 00:00:00+00'),
	(7, 'What''s one thing you always overpack?', false, '2026-10-22 00:00:00+00'),
	(8, 'Street food or fancy dinner: which wins?', false, '2026-10-22 00:00:00+00'),
	(9, 'What''s a childhood vacation memory you still think about?', false, '2026-10-22 00:00:00+00'),
	(10, 'Would you rather have a 6 AM flight or a 2 AM layover?', false, '2026-10-22 00:00:00+00'),
	(11, 'What''s your go-to airport snack?', false, '2026-10-22 00:00:00+00'),
	(12, 'Which squad member would survive longest lost in a foreign city?', false, '2026-10-22 00:00:00+00'),
	(13, 'What''s the weirdest food you''ve ever eaten?', false, '2026-10-22 00:00:00+00'),
	(14, 'Beach day or city day?', false, '2026-10-22 00:00:00+00'),
	(15, 'What''s one thing on your trip bucket list?', false, '2026-10-22 00:00:00+00'),
	(16, 'Would you rather only eat breakfast foods or only eat desserts all trip?', false, '2026-10-22 00:00:00+00'),
	(17, 'What''s your travel superpower?', false, '2026-10-22 00:00:00+00'),
	(18, 'What''s the best souvenir you''ve ever brought home?', false, '2026-10-22 00:00:00+00'),
	(19, 'If this trip were a movie, what would it be called?', false, '2026-10-22 00:00:00+00'),
	(20, 'What''s a food you hated as a kid but love now?', false, '2026-10-22 00:00:00+00'),
	(21, 'Would you rather plan every minute or wing the whole day?', false, '2026-10-22 00:00:00+00'),
	(22, 'What''s your favorite memory with someone in this squad?', false, '2026-10-22 00:00:00+00'),
	(23, 'What''s the first thing you do when you land somewhere new?', false, '2026-10-22 00:00:00+00'),
	(24, 'Spicy, sweet, or salty: pick a food personality.', false, '2026-10-22 00:00:00+00'),
	(25, 'What''s one phrase you want to learn before we go?', false, '2026-10-22 00:00:00+00'),
	(26, 'Would you rather swim with sharks or skydive?', false, '2026-10-22 00:00:00+00'),
	(27, 'What''s your most-used emoji, and why?', false, '2026-10-22 00:00:00+00'),
	(28, 'What''s the best meal you''ve ever had on vacation?', false, '2026-10-22 00:00:00+00'),
	(29, 'Who in the squad is most likely to miss the flight?', false, '2026-10-22 00:00:00+00'),
	(30, 'What''s one rule the squad should follow on this trip?', false, '2026-10-22 00:00:00+00'),
	(31, 'What''s your ideal lazy vacation day?', false, '2026-10-22 00:00:00+00'),
	(32, 'Would you rather have unlimited flights or unlimited hotel stays?', false, '2026-10-22 00:00:00+00'),
	(37, 'What''s the latest you''ve ever stayed out on vacation?', true, '2026-10-22 00:00:00+00'),
	(33, 'What quiet skill are you proud you learned?', true, '2026-10-22 00:00:00+00'),
	(35, 'What is a surprisingly useful travel habit you learned the hard way?', true, '2026-10-22 00:00:00+00'),
	(36, 'What small ritual should the squad start on this trip?', true, '2026-10-22 00:00:00+00'),
