-- The photo-purge cron key, new for each database (trip_private.cron_keys holds no copied secret).
INSERT INTO trip_private.cron_keys(name, key)
VALUES ('purge_photos', encode(extensions.gen_random_bytes(32), 'hex'))
ON CONFLICT (name) DO NOTHING;

-- ---------------------------------------------------------------------------------------------
-- Supabase-owned schemas: storage buckets (all private; access through the policies below and
-- signed URLs), auth triggers, storage policies, realtime tables, cron jobs.
INSERT INTO storage.buckets (id, name, public) VALUES
  ('trip-photos', 'trip-photos', false),
  ('quest-proofs', 'quest-proofs', false),
  ('player-avatars', 'player-avatars', false),
  ('culture-photos', 'culture-photos', false),
  ('inspiration-photos', 'inspiration-photos', false),
  ('window-guide', 'window-guide', false),
  ('bug-screenshots', 'bug-screenshots', false)
ON CONFLICT (id) DO NOTHING;
CREATE TRIGGER guard_auth_signup_age BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION trip_private.guard_auth_signup_age();
CREATE POLICY "Account avatar view" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'player-avatars'::text) AND (split_part(name, '/'::text, 1) = 'account'::text) AND (split_part(name, '/'::text, 2) ~ '^[0-9a-f-]{36}$'::text) AND trip_private.shares_trip((split_part(name, '/'::text, 2))::uuid)));
CREATE POLICY "Founder views bug screenshots" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'bug-screenshots'::text) AND trip_private.is_app_admin()));
CREATE POLICY "Members view trip game photos" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'trip-photos'::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN trip_private.is_trip_member((split_part(name, '/'::text, 1))::uuid, auth.uid())
    ELSE false
END));
CREATE POLICY "Players replace own trip photo" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((bucket_id = 'player-avatars'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN trip_private.is_trip_member((split_part(name, '/'::text, 1))::uuid, auth.uid())
    ELSE false
END))
  WITH CHECK (((bucket_id = 'player-avatars'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND (lower(name) ~ '\.(jpe?g|png|webp)$'::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN trip_private.is_trip_member((split_part(name, '/'::text, 1))::uuid, auth.uid())
    ELSE false
END));
CREATE POLICY "Players upload own trip game photos" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'trip-photos'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND (lower(name) ~ '\.(jpe?g|png|webp)$'::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN trip_private.is_trip_member((split_part(name, '/'::text, 1))::uuid, auth.uid())
    ELSE false
END AND trip_private.photo_quota_ok(name)));
CREATE POLICY "Players upload own trip photo" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'player-avatars'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND (lower(name) ~ '\.(jpe?g|png|webp)$'::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN trip_private.is_trip_member((split_part(name, '/'::text, 1))::uuid, auth.uid())
    ELSE false
END));
CREATE POLICY "Shared-trip avatar view" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'player-avatars'::text) AND (split_part(name, '/'::text, 2) ~ '^[0-9a-f-]{36}$'::text) AND trip_private.shares_trip((split_part(name, '/'::text, 2))::uuid)));
CREATE POLICY "Upload own bug screenshots" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'bug-screenshots'::text) AND (split_part(name, '/'::text, 1) = (auth.uid())::text) AND (lower(name) ~ '\.(jpe?g|png|webp)$'::text)));
CREATE POLICY "View bug screenshots" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'bug-screenshots'::text) AND ((split_part(name, '/'::text, 1) = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM public.bug_reports r
  WHERE ((r.screenshot_path = objects.name) AND (r.trip_id IS NOT NULL) AND trip_private.is_leader(r.trip_id)))))));
CREATE POLICY "Window crew read guide photos" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'window-guide'::text) AND (EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE (((m.trip_id)::text = (storage.foldername(objects.name))[1]) AND (m.user_id = auth.uid()) AND (m.status = 'approved'::text))))));
CREATE POLICY "Window crew upload own guide photos" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'window-guide'::text) AND ((storage.foldername(name))[2] = (auth.uid())::text) AND (EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE (((m.trip_id)::text = (storage.foldername(objects.name))[1]) AND (m.user_id = auth.uid()) AND (m.status = 'approved'::text))))));
CREATE POLICY "culture photos delete own" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
  USING (((bucket_id = 'culture-photos'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text)));
CREATE POLICY "culture photos read" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'culture-photos'::text) AND (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) AND trip_private.can_view_culture((split_part(name, '/'::text, 1))::uuid)));
CREATE POLICY "culture photos upload" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'culture-photos'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND (lower(name) ~ '\.(jpe?g|png|webp)$'::text) AND (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) AND (EXISTS ( SELECT 1
   FROM public.culture_experiences e
  WHERE ((e.id = (split_part(objects.name, '/'::text, 1))::uuid) AND (e.creator_id = auth.uid()) AND (e.finished_at IS NULL))))));
CREATE POLICY inspiration_photo_remove ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
  USING (((bucket_id = 'inspiration-photos'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN (EXISTS ( SELECT 1
       FROM public.cultural_inspirations c
      WHERE ((c.id = (split_part(objects.name, '/'::text, 1))::uuid) AND (c.creator_id = auth.uid()))))
    ELSE false
END));
CREATE POLICY inspiration_photo_upload ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'inspiration-photos'::text) AND (lower(name) ~ '\.(jpe?g|png|webp)$'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN (EXISTS ( SELECT 1
       FROM public.cultural_inspirations c
      WHERE ((c.id = (split_part(objects.name, '/'::text, 1))::uuid) AND (c.creator_id = auth.uid()) AND (c.hidden_at IS NULL) AND trip_private.feature_on(c.trip_id, 'inspiration'::text))))
    ELSE false
END));
CREATE POLICY inspiration_photo_view ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'inspiration-photos'::text) AND
CASE
    WHEN (split_part(name, '/'::text, 1) ~ '^[0-9a-f-]{36}$'::text) THEN (EXISTS ( SELECT 1
       FROM public.cultural_inspirations c
      WHERE ((c.id = (split_part(objects.name, '/'::text, 1))::uuid) AND trip_private.feature_on(c.trip_id, 'inspiration'::text) AND trip_private.is_trip_member(c.trip_id, auth.uid()) AND ((c.creator_id = auth.uid()) OR (c.partner_id = auth.uid()) OR ((c.hidden_at IS NULL) AND (c.reveal_on <= CURRENT_DATE))))))
    ELSE false
END));
CREATE POLICY "quest proofs read owner leader shared" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'quest-proofs'::text) AND trip_private.proof_read_ok(name)));
CREATE POLICY "quest proofs upload own open quest" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'quest-proofs'::text) AND trip_private.proof_upload_ok(name)));
