ALTER PUBLICATION supabase_realtime ADD TABLE public.game_scores;
ALTER PUBLICATION supabase_realtime ADD TABLE public.live_votes;
ALTER PUBLICATION supabase_realtime ADD TABLE public.stamp_settings;
